   initial wr1_cnt   = 16'd0;
   initial arm_cnt   = 16'd0;
   initial clr_cnt   = 16'd0;
   initial hit_cnt   = 16'd0;
   initial sr_cnt    = 16'd0;
   initial done_d    = 1'b0;
   initial sr_d      = 1'b0;
   initial fsm_d     = 2'd0;
   initial wdt_cnt   = 20'd0;
   initial wdt_to    = 1'b0;
   initial err_bits  = 4'd0;
   initial err_code  = 3'd0;
   initial err_ts    = 32'd0;
   initial err_valid = 1'b0;
   initial dbg_o     = 32'd0;

   wire       dbg_fsm_busy  = (fsm_a == 2'd1) || (fsm_a == 2'd2);
   wire       dbg_fsm_move  = (fsm_a != fsm_d);
   wire       dbg_clr_a     = en_a && clr_cmd;
   wire       err_arm_busy  = en_a && arm_cmd && !clr_cmd && (fsm_a != 2'd0);
   wire       err_wr_busy   = en_a && wr_en && dbg_fsm_busy;
   wire       err_wdt       = dbg_fsm_busy && (wdt_cnt == WDT_LIMIT);
   wire       err_bod       = bod_clr && !en_b;
   wire [3:0] err_now       = {err_bod, err_wdt, err_wr_busy, err_arm_busy};
   wire [2:0] err_enc       = err_now[0] ? 3'd1 :
                              err_now[1] ? 3'd2 :
                              err_now[2] ? 3'd3 :
                              err_now[3] ? 3'd4 : 3'd0;
   wire       done_rise     = done_a && !done_d;
   wire       sr_rise       = slot_reset_b && !sr_d;

   reg [31:0] dbg_mux;
   always @(*) begin
       case ({wr_sel, sel_in})
           3'd0: dbg_mux = cyc_cnt;
           3'd1: dbg_mux = beat_cnt;
           3'd2: dbg_mux = {wr1_cnt, wr0_cnt};
           3'd3: dbg_mux = {arm_cnt, clr_cnt};
           3'd4: dbg_mux = {hit_cnt, sr_cnt};
           3'd5: dbg_mux = {err_valid, 3'd0, err_code, 1'b0, err_bits, wdt_to, wdt_cnt[18:0]};
           3'd6: dbg_mux = err_ts;
           default: dbg_mux = {thr_b, streak_b};
       endcase
   end

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
           cyc_cnt   <= 32'd0;
           beat_cnt  <= 32'd0;
           wr0_cnt   <= 16'd0;
           wr1_cnt   <= 16'd0;
           arm_cnt   <= 16'd0;
           clr_cnt   <= 16'd0;
           hit_cnt   <= 16'd0;
           sr_cnt    <= 16'd0;
           done_d    <= 1'b0;
           sr_d      <= 1'b0;
           fsm_d     <= 2'd0;
           wdt_cnt   <= 20'd0;
           wdt_to    <= 1'b0;
           err_bits  <= 4'd0;
           err_code  <= 3'd0;
           err_ts    <= 32'd0;
           err_valid <= 1'b0;
           dbg_o     <= 32'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
           cyc_cnt <= cyc_cnt + 32'd1;
           if (beat_valid && (beat_cnt != 32'hFFFFFFFF))
               beat_cnt <= beat_cnt + 32'd1;
           if (en_a && wr_en && !wr_sel && (wr0_cnt != 16'hFFFF))
               wr0_cnt <= wr0_cnt + 16'd1;
           if (en_a && wr_en && wr_sel && (wr1_cnt != 16'hFFFF))
               wr1_cnt <= wr1_cnt + 16'd1;
           if (en_a && arm_cmd && (arm_cnt != 16'hFFFF))
               arm_cnt <= arm_cnt + 16'd1;
           if (dbg_clr_a && (clr_cnt != 16'hFFFF))
               clr_cnt <= clr_cnt + 16'd1;
           done_d <= done_a;
           sr_d   <= slot_reset_b;
           fsm_d  <= fsm_a;
           if (done_rise && (hit_cnt != 16'hFFFF))
               hit_cnt <= hit_cnt + 16'd1;
           if (sr_rise && (sr_cnt != 16'hFFFF))
               sr_cnt <= sr_cnt + 16'd1;
           if (!dbg_fsm_busy || dbg_fsm_move || dbg_clr_a)
               wdt_cnt <= 20'd0;
           else if (wdt_cnt != WDT_LIMIT)
               wdt_cnt <= wdt_cnt + 20'd1;
           if (dbg_clr_a)
               wdt_to <= 1'b0;
           else if (err_wdt)
               wdt_to <= 1'b1;
           if (bod_clr && en_b) begin
               err_bits  <= 4'd0;
               err_code  <= 3'd0;
               err_ts    <= 32'd0;
               err_valid <= 1'b0;
           end else begin
               err_bits <= err_bits | err_now;
               if (!err_valid && (err_now != 4'd0)) begin
                   err_valid <= 1'b1;
                   err_code  <= err_enc;
                   err_ts    <= cyc_cnt;
               end
           end
           dbg_o <= dbg_mux;
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
   assign wdt_o      = wdt_to;
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;
localparam [1:0] OV_DEPTH = 2'd2;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;
reg [127:0] bq_d0, bq_d1, bq_d2, bq_d3;
reg [127:0] bq_head;
reg [3:0] bq_tag;
reg [1:0] bq_wp, bq_rp;
reg [2:0] bq_cnt;
reg [127:0] ov_d0, ov_d1;
reg [127:0] ov_head;
reg [1:0] ov_tag;
reg ov_wp, ov_rp;
reg [1:0] ov_cnt;
reg [127:0] bq_in_data;
reg bq_in_tag;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;
initial bq_d0 = 128'h0;
initial bq_d1 = 128'h0;
initial bq_d2 = 128'h0;
initial bq_d3 = 128'h0;
initial bq_tag = 4'h0;
initial bq_wp = 2'd0;
initial bq_rp = 2'd0;
initial bq_cnt = 3'd0;
initial ov_d0 = 128'h0;
initial ov_d1 = 128'h0;
initial ov_tag = 2'h0;
initial ov_wp = 1'b0;
initial ov_rp = 1'b0;
initial ov_cnt = 2'd0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
wire bq_empty = (bq_cnt == 3'd0);
wire bq_full = (bq_cnt >= 3'd4);
wire bq_pop = en && !clr_cmd && !bq_empty && (fsm != S_DONE);
wire bq_space = !bq_full || bq_pop;
wire ov_empty = (ov_cnt == 2'd0);
wire ov_full = (ov_cnt >= OV_DEPTH);
wire ov_drain = en && !clr_cmd && !ov_empty && bq_space;
wire beat_direct = en && !clr_cmd && beat_valid && ov_empty && bq_space;
wire ov_fill = en && !clr_cmd && beat_valid && !beat_direct && (!ov_full || ov_drain);
wire beat_accept = beat_direct || ov_fill;
wire bq_push = ov_drain || beat_direct;
wire push_tag = (fsm == S_ARMED) && match0;
wire start_drop = en && !clr_cmd && push_tag && !beat_accept;
wire head_start = bq_pop && bq_tag[bq_rp];
wire match1 = bq_pop && (((bq_head ^ wval1) & wmask1) == 128'h0);

always @(*) begin
case (bq_rp)
2'd0: bq_head = bq_d0;
2'd1: bq_head = bq_d1;
2'd2: bq_head = bq_d2;
default: bq_head = bq_d3;
endcase
end
always @(*) begin
case (ov_rp)
1'b0: ov_head = ov_d0;
default: ov_head = ov_d1;
endcase
end
always @(*) begin
if (ov_empty) begin
bq_in_data = beat_data;
bq_in_tag = push_tag;
end else begin
bq_in_data = ov_head;
bq_in_tag = ov_tag[ov_rp];
end
end

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
S_ARMED: if (start_drop && !started_seen) fsm_nxt = S_IDLE;
else if (head_start) fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
bq_d0 <= 128'h0;
bq_d1 <= 128'h0;
bq_d2 <= 128'h0;
bq_d3 <= 128'h0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
ov_d0 <= 128'h0;
ov_d1 <= 128'h0;
ov_tag <= 2'h0;
ov_wp <= 1'b0;
ov_rp <= 1'b0;
ov_cnt <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
ov_tag <= 2'h0;
ov_wp <= 1'b0;
ov_rp <= 1'b0;
ov_cnt <= 2'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
if (beat_accept && push_tag) started_seen <= 1'b1;
if (bq_pop) begin
bq_tag[bq_rp] <= 1'b0;
bq_rp <= bq_rp + 2'd1;
end
if (bq_push) begin
case (bq_wp)
2'd0: bq_d0 <= bq_in_data;
2'd1: bq_d1 <= bq_in_data;
2'd2: bq_d2 <= bq_in_data;
default: bq_d3 <= bq_in_data;
endcase
bq_tag[bq_wp] <= bq_in_tag;
bq_wp <= bq_wp + 2'd1;
end
if (ov_drain) begin
ov_tag[ov_rp] <= 1'b0;
ov_rp <= ov_rp + 1'b1;
end
if (ov_fill) begin
case (ov_wp)
1'b0: ov_d0 <= beat_data;
default: ov_d1 <= beat_data;
endcase
ov_tag[ov_wp] <= push_tag;
ov_wp <= ov_wp + 1'b1;
end
case ({ov_fill, ov_drain})
2'b10: ov_cnt <= ov_cnt + 2'd1;
2'b01: ov_cnt <= ov_cnt - 2'd1;
default: ov_cnt <= ov_cnt;
endcase
case ({bq_push, bq_pop})
2'b10: bq_cnt <= bq_cnt + 3'd1;
2'b01: bq_cnt <= bq_cnt - 3'd1;
default: bq_cnt <= bq_cnt;
endcase
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);

   always @(posedge clk)
       if (!rst) assert (!(fsm == S_ARMED && started_seen) || (bq_cnt != 3'd0));
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
    if (rd_ptr == 3'd7)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
    2'd2: stat_o <= {8'h0, wrap_cnt, 15'h0, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
output reg rest_ack,
output reg vfy_busy,
output reg [2:0] vfy_cnt,
output reg [1:0] retry_cnt,
output reg [1:0] last_retry,
output reg retry_exh
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;
localparam [2:0] VFY_LAST = 3'd5;
localparam [1:0] RETRY_MAX = 2'd3;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
vfy_busy = 1'b0; vfy_cnt = 3'd0;
retry_cnt = 2'd0; last_retry = 2'd0; retry_exh = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
vfy_busy <= 1'b0; vfy_cnt <= 3'd0;
retry_cnt <= 2'd0; last_retry <= 2'd0; retry_exh <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
retry_cnt <= 2'd0;
retry_exh <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
if (!vfy_busy) begin
vfy_busy <= 1'b1;
vfy_cnt <= 3'd0;
end
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
last_retry <= retry_cnt;
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
// Post-ramp rail verification. The rail must settle for VFY_LAST+1
// enabled cycles before the ramp is acknowledged. A request seen while
// settling means the saved context is stale: drop the save and redo it,
// up to RETRY_MAX times, after which the ramp is accepted and flagged.
if (vfy_busy) begin
if (i_req && retry_cnt != RETRY_MAX) begin
vfy_busy <= 1'b0;
retry_cnt <= retry_cnt + 2'd1;
save_ack <= 1'b0;
state <= S_SAVE;
end else begin
if (i_req)
retry_exh <= 1'b1;
if (vfy_cnt == VFY_LAST) begin
vfy_busy <= 1'b0;
ramp_ack <= 1'b1;
state <= S_REST;
end else begin
vfy_cnt <= vfy_cnt + 3'd1;
end
end
end
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
endmodule

module wormhole_route_unit #(
    parameter [63:0] MY_X = 64'd4,
    parameter [63:0] MY_Y = 64'd2
) (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [1:0]  flit_type,
    input  wire [3:0]  in_ch,
    input  wire [63:0] dest_x,
    input  wire [63:0] dest_y,
    output reg  [2:0]  out_port,
output wire        out_fire,
output reg  [23:0] diag_status
);
    localparam [1:0] FT_BODY = 2'b00;
    localparam [1:0] FT_HEAD = 2'b01;
    localparam [1:0] FT_TAIL = 2'b10;

    localparam [2:0] P_LOCAL = 3'd0;
    localparam [2:0] P_EAST  = 3'd1;
    localparam [2:0] P_WEST  = 3'd2;
    localparam [2:0] P_NORTH = 3'd3;
    localparam [2:0] P_SOUTH = 3'd4;

    reg [15:0] route_valid;
    reg [47:0] route_port;
    reg [63:0] head_cnt;
    reg [63:0] body_cnt;
    reg        head_seen;
    reg        armed;

    initial begin
        route_valid = 16'd0;
        route_port  = 48'd0;
        head_cnt    = 64'd0;
        body_cnt    = 64'd0;
        head_seen   = 1'b0;
        armed       = 1'b1;
        out_port    = 3'd0;
    end

    wire ch_busy = route_valid[in_ch];
    wire do_head = in_valid && (flit_type == FT_HEAD) && !ch_busy;
    wire do_body = in_valid && (flit_type == FT_BODY) && ch_busy;
    wire do_tail = in_valid && (flit_type == FT_TAIL) && ch_busy;

    assign out_fire = do_head || do_body || do_tail;

    reg [2:0] calc_port;
    always @(*) begin
        if (dest_x > MY_X)      calc_port = P_EAST;
        else if (dest_x < MY_X) calc_port = P_WEST;
        else if (dest_y > MY_Y) calc_port = P_NORTH;
        else if (dest_y < MY_Y) calc_port = P_SOUTH;
        else                    calc_port = P_LOCAL;
    end

    wire [2:0] stored_port = route_port[in_ch*3 +: 3];
localparam [15:0] WDOG_LIMIT = 16'd1000;
reg [15:0] tail_cnt;
reg [15:0] err_cnt;
reg [3:0]  last_err_ch;
reg [1:0]  last_err_type;
reg [15:0] idle_cnt;
reg        wdog_trip;
reg [4:0]  port_hit;
initial begin
tail_cnt      = 16'd0;
err_cnt       = 16'd0;
last_err_ch   = 4'd0;
last_err_type = 2'd0;
idle_cnt      = 16'd0;
wdog_trip     = 1'b0;
port_hit      = 5'd0;
diag_status   = 24'd0;
end
wire err_head_busy = in_valid && (flit_type == FT_HEAD) && ch_busy;
wire err_orphan    = in_valid && ((flit_type == FT_BODY) || (flit_type == FT_TAIL)) && !ch_busy;
wire err_badtype   = in_valid && (flit_type == 2'b11);
wire any_err       = err_head_busy || err_orphan || err_badtype;
always @(posedge clk) begin
if (do_tail)
tail_cnt <= tail_cnt + 16'd1;
if (any_err) begin
if (err_cnt != 16'hFFFF)
err_cnt <= err_cnt + 16'd1;
last_err_ch   <= in_ch;
last_err_type <= flit_type;
end
if (out_fire)
idle_cnt <= 16'd0;
else if (idle_cnt != 16'hFFFF)
idle_cnt <= idle_cnt + 16'd1;
if (idle_cnt == WDOG_LIMIT)
wdog_trip <= 1'b1;
else if (out_fire)
wdog_trip <= 1'b0;
if (do_head)
port_hit <= port_hit | (5'd1 << calc_port);
diag_status <= {wdog_trip, port_hit, last_err_type, last_err_ch,
err_cnt[5:0], tail_cnt[5:0]};
end

    always @(posedge clk) begin
        if (do_head) begin
            route_valid[in_ch]         <= 1'b1;
            route_port[in_ch*3 +: 3]   <= calc_port;
            head_cnt                   <= head_cnt + 64'd1;
            head_seen                  <= 1'b1;
            out_port                   <= calc_port;
        end
        if (do_body) begin
            body_cnt <= body_cnt + 64'd1;
            out_port <= stored_port;
        end
        if (do_tail) begin
            route_valid[in_ch] <= 1'b0;
            armed              <= 1'b0;
            out_port           <= stored_port;
        end
    end

    always @(*) assert (!armed || (body_cnt == 64'd0) || head_seen);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
   output reg          done,
   output reg  [127:0] trig_data,
   output wire         bq_full
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;
   reg [127:0] bq_d0, bq_d1, bq_d2, bq_d3;
   reg [3:0] bq_vld, bq_t0, bq_t1;
   reg [1:0] bq_wp, bq_rp;
   reg [127:0] bq_head;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;
   initial trig_data = 128'h0;
   initial bq_d0 = 128'h0;
   initial bq_d1 = 128'h0;
   initial bq_d2 = 128'h0;
   initial bq_d3 = 128'h0;
   initial bq_vld = 4'h0;
   initial bq_t0 = 4'h0;
   initial bq_t1 = 4'h0;
   initial bq_wp = 2'd0;
   initial bq_rp = 2'd0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);
   wire bq_live  = (fsm == S_ARMED) || (fsm == S_RUN);
   wire bq_push  = bq_live && (match0 || match1) && !bq_vld[bq_wp];
   wire bq_pop   = bq_vld[bq_rp];
   wire bq_hd_t0 = bq_t0[bq_rp];
   wire bq_hd_t1 = bq_t1[bq_rp];
   assign bq_full = &bq_vld;
   always @(*)
       case (bq_rp)
           2'd0: bq_head = bq_d0;
           2'd1: bq_head = bq_d1;
           2'd2: bq_head = bq_d2;
           default: bq_head = bq_d3;
       endcase

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
           S_ARMED: if (bq_pop && bq_hd_t0) fsm_nxt = S_RUN;
           S_RUN:   if (bq_pop && bq_hd_t1) fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
           trig_data <= 128'h0;
           bq_d0 <= 128'h0;
           bq_d1 <= 128'h0;
           bq_d2 <= 128'h0;
           bq_d3 <= 128'h0;
           bq_vld <= 4'h0;
           bq_t0 <= 4'h0;
           bq_t1 <= 4'h0;
           bq_wp <= 2'd0;
           bq_rp <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
               bq_vld <= 4'h0;
               bq_wp <= 2'd0;
               bq_rp <= 2'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
               if (fsm == S_ARMED && bq_push && match0) started_seen <= 1'b1;
               if (bq_pop) begin
                   bq_vld[bq_rp] <= 1'b0;
                   bq_rp <= bq_rp + 2'd1;
                   if (fsm == S_RUN && bq_hd_t1) trig_data <= bq_head;
               end
               if (bq_push) begin
                   bq_vld[bq_wp] <= 1'b1;
                   bq_t0[bq_wp] <= match0;
                   bq_t1[bq_wp] <= match1;
                   bq_wp <= bq_wp + 2'd1;
                   case (bq_wp)
                       2'd0: bq_d0 <= beat_data;
                       2'd1: bq_d1 <= beat_data;
                       2'd2: bq_d2 <= beat_data;
                       default: bq_d3 <= beat_data;
                   endcase
               end
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;
reg [127:0] pf_data [0:3];
reg [3:0]   pf_tag  [0:3];
reg [1:0]   pf_wp;
reg [1:0]   pf_rp;
reg [2:0]   pf_used;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
pf_data[0] = 128'h0;
pf_data[1] = 128'h0;
pf_data[2] = 128'h0;
pf_data[3] = 128'h0;
pf_tag[0]  = 4'd0;
pf_tag[1]  = 4'd0;
pf_tag[2]  = 4'd0;
pf_tag[3]  = 4'd0;
pf_wp      = 2'd0;
pf_rp      = 2'd0;
pf_used    = 3'd0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end
   // shared crossbar lane: this source owns the even arbitration slots
   wire       slot_gnt    = ~stat_sel[0];
   wire       pf_full     = (pf_used == 3'd4);
   wire       pf_empty    = (pf_used == 3'd0);
   wire       pf_push     = win && !pf_full;
   wire       pf_pop      = win && !pf_empty && slot_gnt;
   wire [3:0] pf_head_tag = pf_tag[pf_rp];
   wire       pf_last     = (pf_head_tag == 4'd7);

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
pf_data[0] <= 128'h0;
pf_data[1] <= 128'h0;
pf_data[2] <= 128'h0;
pf_data[3] <= 128'h0;
pf_tag[0]  <= 4'd0;
pf_tag[1]  <= 4'd0;
pf_tag[2]  <= 4'd0;
pf_tag[3]  <= 4'd0;
pf_wp      <= 2'd0;
pf_rp      <= 2'd0;
pf_used    <= 3'd0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
   if (pf_pop && pf_last)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
   2'd2: stat_o <= {5'h0, pf_used, wrap_cnt, 15'h0, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
               pf_wp   <= 2'd0;
               pf_rp   <= 2'd0;
               pf_used <= 3'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
               if (pf_push) begin
                   pf_data[pf_wp] <= rom_word;
                   pf_tag[pf_wp]  <= {1'b0, rd_ptr};
                   pf_wp          <= pf_wp + 2'd1;
                   rd_ptr         <= rd_ptr + 3'd1;
               end
               if (pf_pop) begin
                   out_q <= pf_data[pf_rp];
                   out_v <= 1'b1;
                   pf_rp <= pf_rp + 2'd1;
                   if (pf_last)
                       cnt <= 4'd0;
                   else
                       cnt <= cnt + 4'd1;
               end
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
output reg rest_ack,
output reg vfy_busy,
output reg [2:0] vfy_cnt,
output reg [1:0] retry_cnt,
output reg [1:0] last_retry,
output reg retry_exh
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;
localparam [2:0] VFY_LAST = 3'd5;
localparam [1:0] RETRY_MAX = 2'd3;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
vfy_busy = 1'b0; vfy_cnt = 3'd0;
retry_cnt = 2'd0; last_retry = 2'd0; retry_exh = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
vfy_busy <= 1'b0; vfy_cnt <= 3'd0;
retry_cnt <= 2'd0; last_retry <= 2'd0; retry_exh <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
retry_cnt <= 2'd0;
retry_exh <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
if (!vfy_busy) begin
vfy_busy <= 1'b1;
vfy_cnt <= 3'd0;
end
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
last_retry <= retry_cnt;
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
// Post-ramp rail verification. The rail must settle for VFY_LAST+1
// enabled cycles before the ramp is acknowledged. A request seen while
// settling means the saved context is stale: drop the save and redo it,
// up to RETRY_MAX times, after which the ramp is accepted and flagged.
if (vfy_busy) begin
if (i_req && retry_cnt != RETRY_MAX) begin
vfy_busy <= 1'b0;
retry_cnt <= retry_cnt + 2'd1;
save_ack <= 1'b0;
state <= S_SAVE;
end else begin
if (i_req)
retry_exh <= 1'b1;
if (vfy_cnt == VFY_LAST) begin
vfy_busy <= 1'b0;
ramp_ack <= 1'b1;
state <= S_REST;
end else begin
vfy_cnt <= vfy_cnt + 3'd1;
end
end
end
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module pg_seq_pool (
    input wire clk,
    input wire rst,
    input wire [5:0] i_ce,
    input wire [5:0] i_req,
    output wire [2:0] pool_o,
    output wire [5:0] gnt_o,
    output wire [5:0] win_o,
    output wire [17:0] state_o,
    output wire [5:0] save_ack_o,
    output wire [5:0] ramp_ack_o,
    output wire [5:0] rest_ack_o,
    output wire [5:0] vfy_busy_o,
    output wire [17:0] vfy_cnt_o,
    output wire [11:0] retry_cnt_o,
    output wire [11:0] last_retry_o,
    output wire [5:0] retry_exh_o,
    output wire [47:0] ramp_cnt_o
);
    // Shared power-down budget: at most TOTAL rails may be in a window at once.
    localparam [2:0] TOTAL = 3'd4;

    reg [2:0] pool;
    initial pool = TOTAL;

    wire win_t0, win_t1, win_t2, win_t3, win_t4, win_t5;
    wire [2:0] state_t0, state_t1, state_t2, state_t3, state_t4, state_t5;
