    wire rest_t0, rest_t1, rest_t2, rest_t3, rest_t4, rest_t5;
    wire vbusy_t0, vbusy_t1, vbusy_t2, vbusy_t3, vbusy_t4, vbusy_t5;
    wire [2:0] vcnt_t0, vcnt_t1, vcnt_t2, vcnt_t3, vcnt_t4, vcnt_t5;
    wire [1:0] rcnt_t0, rcnt_t1, rcnt_t2, rcnt_t3, rcnt_t4, rcnt_t5;
    wire [1:0] lretry_t0, lretry_t1, lretry_t2, lretry_t3, lretry_t4, lretry_t5;
    wire rexh_t0, rexh_t1, rexh_t2, rexh_t3, rexh_t4, rexh_t5;
    wire [7:0] rampc_t0, rampc_t1, rampc_t2, rampc_t3, rampc_t4, rampc_t5;

    wire [5:0] w = {win_t5, win_t4, win_t3, win_t2, win_t1, win_t0};
    wire [5:0] done = {(state_t5 == 3'd4), (state_t4 == 3'd4), (state_t3 == 3'd4),
                       (state_t2 == 3'd4), (state_t1 == 3'd4), (state_t0 == 3'd4)};

    // Idle sequencers asking to enter a window; lowest index wins a free credit.
    wire [5:0] cand = ~w & i_req & i_ce;
    wire [5:0] gnt = (pool != 3'd0) ? (cand & (~cand + 6'd1)) : 6'd0;
    // A sequencer leaving S_DONE hands its credit back.
