module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o,
output reg  [2:0]   out_tag,
output reg          out_last,
output reg          out_par,
output wire [1:0]   eq_lvl_o,
output wire [15:0]  eq_stall_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;
reg [127:0] pf_data [0:3];
reg [3:0]   pf_tag  [0:3];
reg [1:0]   pf_wp;
reg [1:0]   pf_rp;
reg [2:0]   pf_used;
// egress retiming queue: decouples prefetch from the shared lane grant
reg [127:0] eq_data [0:1];
reg [3:0]   eq_tag  [0:1];
reg         eq_wp;
reg         eq_rp;
reg [1:0]   eq_used;
reg [15:0]  stall_cnt;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
pf_data[0] = 128'h0;
pf_data[1] = 128'h0;
pf_data[2] = 128'h0;
pf_data[3] = 128'h0;
pf_tag[0]  = 4'd0;
pf_tag[1]  = 4'd0;
pf_tag[2]  = 4'd0;
pf_tag[3]  = 4'd0;
pf_wp      = 2'd0;
pf_rp      = 2'd0;
pf_used    = 3'd0;
eq_data[0] = 128'h0;
eq_data[1] = 128'h0;
eq_tag[0]  = 4'd0;
eq_tag[1]  = 4'd0;
eq_wp      = 1'b0;
eq_rp      = 1'b0;
eq_used    = 2'd0;
stall_cnt  = 16'd0;
out_tag    = 3'd0;
out_last   = 1'b0;
out_par    = 1'b0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end
   // shared crossbar lane: this source owns the even arbitration slots
   wire       slot_gnt    = ~stat_sel[0];
   wire       pf_full     = (pf_used == 3'd4);
   wire       pf_empty    = (pf_used == 3'd0);
   wire       pf_push     = win && !pf_full;
   wire       eq_full     = (eq_used == 2'd2);
   wire       eq_empty    = (eq_used == 2'd0);
   wire       eq_pop      = win && !eq_empty && slot_gnt;
   wire       pf_pop      = win && !pf_empty && (!eq_full || eq_pop);
   wire       eq_push     = pf_pop;
   wire [3:0] pf_head_tag = pf_tag[pf_rp];
   wire [3:0] eq_head_tag = eq_tag[eq_rp];
   wire       eq_last     = (eq_head_tag == 4'd7);
   wire       pf_stall    = win && !pf_empty && !pf_pop;
   assign eq_lvl_o   = eq_used;
   assign eq_stall_o = stall_cnt;

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
pf_data[0] <= 128'h0;
pf_data[1] <= 128'h0;
pf_data[2] <= 128'h0;
pf_data[3] <= 128'h0;
pf_tag[0]  <= 4'd0;
pf_tag[1]  <= 4'd0;
pf_tag[2]  <= 4'd0;
pf_tag[3]  <= 4'd0;
pf_wp      <= 2'd0;
pf_rp      <= 2'd0;
pf_used    <= 3'd0;
eq_data[0] <= 128'h0;
eq_data[1] <= 128'h0;
eq_tag[0]  <= 4'd0;
eq_tag[1]  <= 4'd0;
eq_wp      <= 1'b0;
eq_rp      <= 1'b0;
eq_used    <= 2'd0;
stall_cnt  <= 16'd0;
out_tag    <= 3'd0;
out_last   <= 1'b0;
out_par    <= 1'b0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
   if (eq_pop && eq_last)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
if (pf_stall && !start && !stop)
    stall_cnt <= stall_cnt + 16'd1;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
   2'd2: stat_o <= {3'h0, eq_used, pf_used, wrap_cnt, 15'h0, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
               pf_wp   <= 2'd0;
               pf_rp   <= 2'd0;
               pf_used <= 3'd0;
               eq_wp   <= 1'b0;
               eq_rp   <= 1'b0;
               eq_used <= 2'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
               if (pf_push) begin
                   pf_data[pf_wp] <= rom_word;
                   pf_tag[pf_wp]  <= {1'b0, rd_ptr};
                   pf_wp          <= pf_wp + 2'd1;
                   rd_ptr         <= rd_ptr + 3'd1;
               end
               if (pf_pop) begin
                  eq_data[eq_wp] <= pf_data[pf_rp];
                  eq_tag[eq_wp]  <= pf_head_tag;
                  eq_wp          <= eq_wp + 1'b1;
                  pf_rp          <= pf_rp + 2'd1;
              end
              if (eq_pop) begin
                  out_q    <= eq_data[eq_rp];
                  out_tag  <= eq_head_tag[2:0];
                  out_last <= eq_last;
                  out_par  <= ^eq_data[eq_rp];
                  out_v    <= 1'b1;
                  eq_rp    <= eq_rp + 1'b1;
                  if (eq_last)
                      cnt <= 4'd0;
                  else
                      cnt <= cnt + 4'd1;
              end
              case ({eq_push, eq_pop})
                  2'b10:   eq_used <= eq_used + 2'd1;
                  2'b01:   eq_used <= eq_used - 2'd1;
                  default: eq_used <= eq_used;
              endcase
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module xbar_route_rom (
    input  wire         clk,
