            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
st0_v  <= 1'b0;
st1_v  <= 1'b0;
st2_v  <= 1'b0;
st3_v  <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
st0_q   <= rom_word;
st0_idx <= rd_ptr;
st0_v   <= 1'b1;
st1_q   <= st0_q;
st1_idx <= st0_idx;
st1_v   <= st0_v;
st2_q   <= st1_q;
st2_idx <= st1_idx;
st2_v   <= st1_v;
st3_q   <= st2_q;
st3_idx <= st2_idx;
