out_q <= st3_q;
out_v <= 1'b1;
if (st3_idx == 3'd7)
cnt <= 4'd0;
else
cnt <= cnt + 4'd1;
end
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
