module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
   output reg          done,
   output wire         beat_ready,
   output wire [1:0]   q_level,
   output wire [127:0] q_head
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

   // two-entry beat staging queue; the start comparator is evaluated on
   // entry so a later watchpoint rewrite cannot retroactively change it
   reg [127:0] q_data0, q_data1;
   reg q_st0, q_st1;
   reg q_rd, q_wr;
   reg [1:0] q_cnt;
   initial q_data0 = 128'h0;
   initial q_data1 = 128'h0;
   initial q_st0 = 1'b0;
   initial q_st1 = 1'b0;
   initial q_rd = 1'b0;
   initial q_wr = 1'b0;
   initial q_cnt = 2'd0;

   wire q_full = (q_cnt == 2'd2);
   wire q_hv   = (q_cnt != 2'd0);
   wire q_hst  = q_rd ? q_st1 : q_st0;
   assign q_head     = q_rd ? q_data1 : q_data0;
   assign q_level    = q_cnt;
   assign beat_ready = !q_full;
   // pops stall while the watchpoint port is being written
   wire q_pop  = en && !clr_cmd && q_hv && !wr_en;
   wire q_push = en && !clr_cmd && beat_valid && (!q_full || q_pop);

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
   wire match1 = q_hv && (((q_head ^ wval1) & wmask1) == 128'h0);
   wire start_hit = (fsm == S_ARMED) && match0;

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
           S_ARMED: if (q_pop && q_hst)  fsm_nxt = S_RUN;
           S_RUN:   if (q_pop && match1) fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
           q_data0 <= 128'h0;
           q_data1 <= 128'h0;
           q_st0 <= 1'b0;
           q_st1 <= 1'b0;
           q_rd <= 1'b0;
           q_wr <= 1'b0;
           q_cnt <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
               q_cnt <= 2'd0;
               q_rd <= 1'b0;
               q_wr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
               if (start_hit && q_push) started_seen <= 1'b1;
               if (q_push) begin
                   if (q_wr) begin
                       q_data1 <= beat_data;
                       q_st1   <= start_hit;
                   end else begin
                       q_data0 <= beat_data;
                       q_st0   <= start_hit;
                   end
                   q_wr <= !q_wr;
               end
               if (q_pop) q_rd <= !q_rd;
               if (q_push && !q_pop) q_cnt <= q_cnt + 2'd1;
               else if (q_pop && !q_push) q_cnt <= q_cnt - 2'd1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [3:0]  n_acc_in,   // accesses accepted into the lookup stage
output reg  [3:0]  n_acc_out,  // accesses retired from the lookup stage
output reg  [15:0] dbg_status   // rotating debug/statistics readout
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
initial n_acc_in  = 4'd0;
initial n_acc_out = 4'd0;
   // ---- debug / statistics bank (observability only) ----
   reg [7:0]  dbg_grant_cnt   = 8'd0;
   reg [7:0]  dbg_fault_cnt   = 8'd0;
   reg [5:0]  dbg_cfg_wr_cnt  = 6'd0;
   reg [5:0]  dbg_cfg_rej_cnt = 6'd0;
   reg [7:0]  dbg_idle_cnt    = 8'd0;
   reg        dbg_wdog_trip   = 1'b0;
   reg [15:0] dbg_addr_d1     = 16'd0;
   reg [15:0] dbg_fault_addr  = 16'd0;
   reg [1:0]  dbg_sel         = 2'd0;
   initial dbg_status = 16'd0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
// a hit retiring while the ledger shows nothing outstanding is a spurious response
fault  <= miss_q || (hit_q && (n_acc_in == n_acc_out));
if (acc_valid)
    n_acc_in <= n_acc_in + 4'd1;
if (hit_q || miss_q)
    n_acc_out <= n_acc_out + 4'd1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

   always @(posedge clk) begin
       if (i_ce) begin
           dbg_addr_d1 <= acc_addr;
           if (grant && (dbg_grant_cnt != 8'hFF))
               dbg_grant_cnt <= dbg_grant_cnt + 8'd1;
           if (fault && (dbg_fault_cnt != 8'hFF))
               dbg_fault_cnt <= dbg_fault_cnt + 8'd1;
           if (miss_q)
               dbg_fault_addr <= dbg_addr_d1;
           if (cfg_we) begin
               if (pre_lock && (cfg_idx < 5'd24))
                   dbg_cfg_wr_cnt <= dbg_cfg_wr_cnt + 6'd1;
               else
                   dbg_cfg_rej_cnt <= dbg_cfg_rej_cnt + 6'd1;
           end
           if (acc_valid) begin
               dbg_idle_cnt  <= 8'd0;
               dbg_wdog_trip <= 1'b0;
           end else if (dbg_idle_cnt == 8'hFF)
               dbg_wdog_trip <= 1'b1;
           else
               dbg_idle_cnt <= dbg_idle_cnt + 8'd1;
           dbg_sel <= dbg_sel + 2'd1;
           case (dbg_sel)
               2'd0:    dbg_status <= {dbg_grant_cnt, dbg_fault_cnt};
               2'd1:    dbg_status <= {dbg_cfg_wr_cnt, dbg_cfg_rej_cnt, pre_lock, dbg_wdog_trip, 2'b00};
               2'd2:    dbg_status <= dbg_fault_addr;
               default: dbg_status <= {dbg_idle_cnt, 4'd0, n_acc_in - n_acc_out};
           endcase
       end
   end

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output wire [3:0]   pipe_vld,
output wire [2:0]   out_tag,
output reg  [31:0]  dbg_stat
,
    output wire [3:0] cnt_o,
    output wire [2:0] rd_ptr_o,
    output wire [2:0] st0_idx_o,
    output wire st0_v_o,
    output wire [2:0] st1_idx_o,
    output wire st1_v_o,
    output wire [2:0] st2_idx_o,
    output wire st2_v_o,
    output wire [2:0] st3_idx_o,
    output wire st3_v_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [127:0] st0_q, st1_q, st2_q, st3_q;
reg [2:0]   st0_idx, st1_idx, st2_idx, st3_idx;
reg         st0_v, st1_v, st2_v, st3_v;
assign pipe_vld = {st3_v, st2_v, st1_v, st0_v};
assign out_tag  = st3_idx;
reg [7:0]  start_cnt;
reg [7:0]  stop_cnt;
reg [15:0] beat_cnt;
reg [15:0] csum;
reg [11:0] idle_wdog;
reg        wdog_flag;
reg        err_flag;
reg        seq_err;
reg [2:0]  last_tag;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
st0_q = 128'h0; st1_q = 128'h0; st2_q = 128'h0; st3_q = 128'h0;
st0_idx = 3'd0; st1_idx = 3'd0; st2_idx = 3'd0; st3_idx = 3'd0;
st0_v = 1'b0; st1_v = 1'b0; st2_v = 1'b0; st3_v = 1'b0;
start_cnt = 8'd0;
stop_cnt  = 8'd0;
beat_cnt  = 16'd0;
csum      = 16'd0;
idle_wdog = 12'd0;
wdog_flag = 1'b0;
err_flag  = 1'b0;
seq_err   = 1'b0;
last_tag  = 3'd7;
dbg_stat  = 32'd0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
st0_q <= 128'h0; st1_q <= 128'h0; st2_q <= 128'h0; st3_q <= 128'h0;
st0_idx <= 3'd0; st1_idx <= 3'd0; st2_idx <= 3'd0; st3_idx <= 3'd0;
st0_v <= 1'b0; st1_v <= 1'b0; st2_v <= 1'b0; st3_v <= 1'b0;
start_cnt <= 8'd0;
stop_cnt  <= 8'd0;
beat_cnt  <= 16'd0;
csum      <= 16'd0;
idle_wdog <= 12'd0;
wdog_flag <= 1'b0;
err_flag  <= 1'b0;
seq_err   <= 1'b0;
last_tag  <= 3'd7;
dbg_stat  <= 32'd0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
st0_v  <= 1'b0;
st1_v  <= 1'b0;
st2_v  <= 1'b0;
st3_v  <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
st0_q   <= rom_word;
st0_idx <= rd_ptr;
st0_v   <= 1'b1;
st1_q   <= st0_q;
st1_idx <= st0_idx;
st1_v   <= st0_v;
st2_q   <= st1_q;
st2_idx <= st1_idx;
st2_v   <= st1_v;
st3_q   <= st2_q;
st3_idx <= st2_idx;
st3_v   <= st2_v;
if (st3_v) begin
out_q <= st3_q;
out_v <= 1'b1;
if (st3_idx == 3'd7)
cnt <= 4'd0;
else
cnt <= cnt + 4'd1;
end
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                end
            end
        end
if (rst_n) begin
if (en) begin
if (start)
start_cnt <= start_cnt + 8'd1;
if (stop)
stop_cnt <= stop_cnt + 8'd1;
if (start && stop)
err_flag <= 1'b1;
if (start || win)
idle_wdog <= 12'd0;
else if (idle_wdog != 12'hFFF)
idle_wdog <= idle_wdog + 12'd1;
if (idle_wdog == 12'hFFE)
wdog_flag <= 1'b1;
if (start)
last_tag <= 3'd7;
if (win && !start && !stop && st3_v) begin
beat_cnt <= beat_cnt + 16'd1;
csum     <= {csum[14:0], csum[15]} ^ st3_q[15:0] ^ st3_q[127:112];
last_tag <= st3_idx;
if (st3_idx != last_tag + 3'd1)
seq_err <= 1'b1;
end
end
dbg_stat <= {wdog_flag, err_flag, seq_err, idle_wdog[4:0], start_cnt ^ stop_cnt, beat_cnt ^ csum};
end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
    assign cnt_o = cnt;
    assign rd_ptr_o = rd_ptr;
    assign st0_idx_o = st0_idx;
    assign st0_v_o = st0_v;
    assign st1_idx_o = st1_idx;
    assign st1_v_o = st1_v;
    assign st2_idx_o = st2_idx;
    assign st2_v_o = st2_v;
    assign st3_idx_o = st3_idx;
    assign st3_v_o = st3_v;
endmodule

module xbar_route_pool (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [3:0]   req,
    input  wire [3:0]   start,
    input  wire [3:0]   stop,
    output reg  [127:0] out_q,
    output reg          out_v,
    output reg  [1:0]   out_src,
    output wire [3:0]   frame_v,
    output wire [11:0]  out_tag_all,
    output wire [15:0]  pipe_vld_all,
    output wire [127:0] dbg_all,
    output wire [1:0]   pool_o,
output wire [3:0]   hold_o,
output wire         park_o,
output wire [1:0]   park_lane_o,
output wire [1:0]   boost_o,
output wire [11:0]  age_all_o,
output wire [15:0]  lease_all_o,
output wire [31:0]  arb_stat_o
);
    reg [1:0] pool;
    reg       h0, h1, h2, h3;
   // starvation guard / lease controller
   reg [2:0] age0, age1, age2, age3;
   reg [3:0] lease0, lease1, lease2, lease3;
   reg       park_v;
   reg [1:0] park_lane;
   reg [1:0] boost_ptr;
   reg [7:0] park_cnt;
   reg [7:0] ret_cnt;
   reg [7:0] revoke_cnt;
   reg [3:0] last_rv;

    initial begin
        pool = 2'd2;
        h0 = 1'b0; h1 = 1'b0; h2 = 1'b0; h3 = 1'b0;
       age0 = 3'd0; age1 = 3'd0; age2 = 3'd0; age3 = 3'd0;
       lease0 = 4'd0; lease1 = 4'd0; lease2 = 4'd0; lease3 = 4'd0;
       park_v     = 1'b0;
       park_lane  = 2'd0;
       boost_ptr  = 2'd0;
       park_cnt   = 8'd0;
       ret_cnt    = 8'd0;
       revoke_cnt = 8'd0;
       last_rv    = 4'd0;
    end

    wire [127:0] t0_out_q, t1_out_q, t2_out_q, t3_out_q;
    wire         t0_out_v, t1_out_v, t2_out_v, t3_out_v;
    wire [3:0]   t0_pipe_vld, t1_pipe_vld, t2_pipe_vld, t3_pipe_vld;
    wire [2:0]   t0_out_tag, t1_out_tag, t2_out_tag, t3_out_tag;
    wire [31:0]  t0_dbg, t1_dbg, t2_dbg, t3_dbg;
    wire [3:0]   t0_cnt, t1_cnt, t2_cnt, t3_cnt;
    wire [2:0]   t0_rd_ptr, t1_rd_ptr, t2_rd_ptr, t3_rd_ptr;
    wire [2:0]   t0_st0_idx, t0_st1_idx, t0_st2_idx, t0_st3_idx;
    wire [2:0]   t1_st0_idx, t1_st1_idx, t1_st2_idx, t1_st3_idx;
    wire [2:0]   t2_st0_idx, t2_st1_idx, t2_st2_idx, t2_st3_idx;
    wire [2:0]   t3_st0_idx, t3_st1_idx, t3_st2_idx, t3_st3_idx;
    wire         t0_st0_v, t0_st1_v, t0_st2_v, t0_st3_v;
    wire         t1_st0_v, t1_st1_v, t1_st2_v, t1_st3_v;
    wire         t2_st0_v, t2_st1_v, t2_st2_v, t2_st3_v;
    wire         t3_st0_v, t3_st1_v, t3_st2_v, t3_st3_v;

    wire t0_en = en && h0;
    wire t1_en = en && h1;
    wire t2_en = en && h2;
    wire t3_en = en && h3;

    xbar_route_rom u0 (.clk(clk), .rst_n(rst_n), .en(t0_en), .start(start[0]), .stop(stop[0]),
        .out_q(t0_out_q), .out_v(t0_out_v), .pipe_vld(t0_pipe_vld), .out_tag(t0_out_tag), .dbg_stat(t0_dbg),
        .cnt_o(t0_cnt), .rd_ptr_o(t0_rd_ptr),
        .st0_idx_o(t0_st0_idx), .st0_v_o(t0_st0_v), .st1_idx_o(t0_st1_idx), .st1_v_o(t0_st1_v),
        .st2_idx_o(t0_st2_idx), .st2_v_o(t0_st2_v), .st3_idx_o(t0_st3_idx), .st3_v_o(t0_st3_v));

    xbar_route_rom u1 (.clk(clk), .rst_n(rst_n), .en(t1_en), .start(start[1]), .stop(stop[1]),
        .out_q(t1_out_q), .out_v(t1_out_v), .pipe_vld(t1_pipe_vld), .out_tag(t1_out_tag), .dbg_stat(t1_dbg),
        .cnt_o(t1_cnt), .rd_ptr_o(t1_rd_ptr),
        .st0_idx_o(t1_st0_idx), .st0_v_o(t1_st0_v), .st1_idx_o(t1_st1_idx), .st1_v_o(t1_st1_v),
        .st2_idx_o(t1_st2_idx), .st2_v_o(t1_st2_v), .st3_idx_o(t1_st3_idx), .st3_v_o(t1_st3_v));

    xbar_route_rom u2 (.clk(clk), .rst_n(rst_n), .en(t2_en), .start(start[2]), .stop(stop[2]),
        .out_q(t2_out_q), .out_v(t2_out_v), .pipe_vld(t2_pipe_vld), .out_tag(t2_out_tag), .dbg_stat(t2_dbg),
        .cnt_o(t2_cnt), .rd_ptr_o(t2_rd_ptr),
        .st0_idx_o(t2_st0_idx), .st0_v_o(t2_st0_v), .st1_idx_o(t2_st1_idx), .st1_v_o(t2_st1_v),
        .st2_idx_o(t2_st2_idx), .st2_v_o(t2_st2_v), .st3_idx_o(t2_st3_idx), .st3_v_o(t2_st3_v));

    xbar_route_rom u3 (.clk(clk), .rst_n(rst_n), .en(t3_en), .start(start[3]), .stop(stop[3]),
        .out_q(t3_out_q), .out_v(t3_out_v), .pipe_vld(t3_pipe_vld), .out_tag(t3_out_tag), .dbg_stat(t3_dbg),
        .cnt_o(t3_cnt), .rd_ptr_o(t3_rd_ptr),
        .st0_idx_o(t3_st0_idx), .st0_v_o(t3_st0_v), .st1_idx_o(t3_st1_idx), .st1_v_o(t3_st1_v),
        .st2_idx_o(t3_st2_idx), .st2_v_o(t3_st2_v), .st3_idx_o(t3_st3_idx), .st3_v_o(t3_st3_v));

    // credit return: frame end (last ROM index leaving stage 3) or lane stopped
    wire r0 = h0 && en && (stop[0] || (!start[0] && t0_st3_v && t0_st3_idx == 3'd7));
    wire r1 = h1 && en && (stop[1] || (!start[1] && t1_st3_v && t1_st3_idx == 3'd7));
    wire r2 = h2 && en && (stop[2] || (!start[2] && t2_st3_v && t2_st3_idx == 3'd7));
    wire r3 = h3 && en && (stop[3] || (!start[3] && t3_st3_v && t3_st3_idx == 3'd7));

   // lease timer: a lane that holds a credit but never launches a frame
   // (no start and nothing entering its pipeline) hands the credit back
   wire p0 = start[0] || t0_st0_v;
   wire p1 = start[1] || t1_st0_v;
   wire p2 = start[2] || t2_st0_v;
   wire p3 = start[3] || t3_st0_v;
   wire lx0 = (lease0 == 4'hF);
   wire lx1 = (lease1 == 4'hF);
   wire lx2 = (lease2 == 4'hF);
   wire lx3 = (lease3 == 4'hF);
   wire rv0 = h0 && en && !r0 && !start[0] && lx0;
   wire rv1 = h1 && en && !r1 && !start[1] && lx1;
   wire rv2 = h2 && en && !r2 && !start[2] && lx2;
   wire rv3 = h3 && en && !r3 && !start[3] && lx3;
   wire [3:0] rv_vec = {rv3, rv2, rv1, rv0};
   wire [2:0] rv_cnt = {2'b00, rv0} + {2'b00, rv1} + {2'b00, rv2} + {2'b00, rv3};

   // starvation guard: a requester passed over for seven enabled cycles
   wire s0 = req[0] && !h0 && (age0 == 3'd7);
   wire s1 = req[1] && !h1 && (age1 == 3'd7);
   wire s2 = req[2] && !h2 && (age2 == 3'd7);
   wire s3 = req[3] && !h3 && (age3 == 3'd7);
   reg       stv_any;
   reg [1:0] stv_sel;
   always @(*) begin
       stv_any = s0 || s1 || s2 || s3;
       stv_sel = 2'd0;
       case (boost_ptr)
           2'd0: begin
               if (s0)      stv_sel = 2'd0;
               else if (s1) stv_sel = 2'd1;
               else if (s2) stv_sel = 2'd2;
               else         stv_sel = 2'd3;
           end
           2'd1: begin
               if (s1)      stv_sel = 2'd1;
               else if (s2) stv_sel = 2'd2;
               else if (s3) stv_sel = 2'd3;
               else         stv_sel = 2'd0;
           end
           2'd2: begin
               if (s2)      stv_sel = 2'd2;
               else if (s3) stv_sel = 2'd3;
               else if (s0) stv_sel = 2'd0;
               else         stv_sel = 2'd1;
           end
           default: begin
               if (s3)      stv_sel = 2'd3;
               else if (s0) stv_sel = 2'd0;
               else if (s1) stv_sel = 2'd1;
               else         stv_sel = 2'd2;
           end
       endcase
   end

   // reservation slot: one credit parked for the chosen starved lane,
   // handed over on the next enabled cycle, or returned if the lane
   // has withdrawn its request; the parked lane is idle by construction
   wire park_take = en && !park_v && (pool != 2'd0) && stv_any;
   wire park_fire = en && park_v && req[park_lane];
   wire park_ret  = en && park_v && !req[park_lane];
   wire pf0 = park_fire && (park_lane == 2'd0);
   wire pf1 = park_fire && (park_lane == 2'd1);
   wire pf2 = park_fire && (park_lane == 2'd2);
   wire pf3 = park_fire && (park_lane == 2'd3);
   wire pb0 = park_v && (park_lane == 2'd0);
   wire pb1 = park_v && (park_lane == 2'd1);
   wire pb2 = park_v && (park_lane == 2'd2);
   wire pb3 = park_v && (park_lane == 2'd3);

    // one grant per cycle, fixed priority, only from a non-empty pool
   // a reservation take preempts the normal arbiter for that cycle
   wire credit_ok = en && (pool != 2'd0) && !park_take;
   wire g0 = credit_ok && req[0] && !h0 && !pb0;
   wire g1 = credit_ok && req[1] && !h1 && !pb1 && !g0;
   wire g2 = credit_ok && req[2] && !h2 && !pb2 && !g0 && !g1;
   wire g3 = credit_ok && req[3] && !h3 && !pb3 && !g0 && !g1 && !g2;
    wire g_any = g0 || g1 || g2 || g3;

    wire [2:0] rel_cnt = {2'b00, r0} + {2'b00, r1} + {2'b00, r2} + {2'b00, r3};
   wire [2:0] pool_nx = {1'b0, pool} + rel_cnt + rv_cnt + {2'b00, park_ret}
                        - {2'b00, g_any} - {2'b00, park_take};

    always @(posedge clk) begin
        if (!rst_n) begin
            pool <= 2'd2;
            h0 <= 1'b0; h1 <= 1'b0; h2 <= 1'b0; h3 <= 1'b0;
           age0 <= 3'd0; age1 <= 3'd0; age2 <= 3'd0; age3 <= 3'd0;
           lease0 <= 4'd0; lease1 <= 4'd0; lease2 <= 4'd0; lease3 <= 4'd0;
           park_v     <= 1'b0;
           park_lane  <= 2'd0;
           boost_ptr  <= 2'd0;
           park_cnt   <= 8'd0;
           ret_cnt    <= 8'd0;
           revoke_cnt <= 8'd0;
           last_rv    <= 4'd0;
        end else begin
            pool <= pool_nx[1:0];
           h0 <= g0 || pf0 || (h0 && !r0 && !rv0);
           h1 <= g1 || pf1 || (h1 && !r1 && !rv1);
           h2 <= g2 || pf2 || (h2 && !r2 && !rv2);
           h3 <= g3 || pf3 || (h3 && !r3 && !rv3);
           if (en) begin
               // request aging
               if (!req[0] || h0 || g0 || pf0)
                   age0 <= 3'd0;
               else if (age0 != 3'd7)
                   age0 <= age0 + 3'd1;
               if (!req[1] || h1 || g1 || pf1)
                   age1 <= 3'd0;
               else if (age1 != 3'd7)
                   age1 <= age1 + 3'd1;
               if (!req[2] || h2 || g2 || pf2)
                   age2 <= 3'd0;
               else if (age2 != 3'd7)
                   age2 <= age2 + 3'd1;
               if (!req[3] || h3 || g3 || pf3)
                   age3 <= 3'd0;
               else if (age3 != 3'd7)
                   age3 <= age3 + 3'd1;
               // lease timers
               if (!h0 || p0 || r0 || rv0)
                   lease0 <= 4'd0;
               else if (!lx0)
                   lease0 <= lease0 + 4'd1;
               if (!h1 || p1 || r1 || rv1)
                   lease1 <= 4'd0;
               else if (!lx1)
                   lease1 <= lease1 + 4'd1;
               if (!h2 || p2 || r2 || rv2)
                   lease2 <= 4'd0;
               else if (!lx2)
                   lease2 <= lease2 + 4'd1;
               if (!h3 || p3 || r3 || rv3)
                   lease3 <= 4'd0;
               else if (!lx3)
                   lease3 <= lease3 + 4'd1;
               // reservation slot
               if (park_take) begin
                   park_v    <= 1'b1;
                   park_lane <= stv_sel;
                   boost_ptr <= stv_sel + 2'd1;
                   park_cnt  <= park_cnt + 8'd1;
               end else if (park_fire || park_ret) begin
                   park_v    <= 1'b0;
               end
               if (park_ret)
                   ret_cnt <= ret_cnt + 8'd1;
               if (rv_vec != 4'd0) begin
                   revoke_cnt <= revoke_cnt + {5'd0, rv_cnt};
                   last_rv    <= rv_vec;
               end
           end
        end
    end

    // output port: lowest credited lane with valid data drives the shared bus
    always @(*) begin
        out_q   = 128'h0;
        out_v   = 1'b0;
        out_src = 2'd0;
        if (h0 && t0_out_v) begin
            out_q = t0_out_q; out_v = 1'b1; out_src = 2'd0;
        end else if (h1 && t1_out_v) begin
            out_q = t1_out_q; out_v = 1'b1; out_src = 2'd1;
        end else if (h2 && t2_out_v) begin
            out_q = t2_out_q; out_v = 1'b1; out_src = 2'd2;
        end else if (h3 && t3_out_v) begin
            out_q = t3_out_q; out_v = 1'b1; out_src = 2'd3;
        end
    end

    assign frame_v      = {t3_out_v, t2_out_v, t1_out_v, t0_out_v};
    assign out_tag_all  = {t3_out_tag, t2_out_tag, t1_out_tag, t0_out_tag};
    assign pipe_vld_all = {t3_pipe_vld, t2_pipe_vld, t1_pipe_vld, t0_pipe_vld};
    assign dbg_all      = {t3_dbg, t2_dbg, t1_dbg, t0_dbg};
    assign pool_o       = pool;
    assign hold_o       = {h3, h2, h1, h0};
   assign park_o       = park_v;
   assign park_lane_o  = park_lane;
   assign boost_o      = boost_ptr;
   assign age_all_o    = {age3, age2, age1, age0};
   assign lease_all_o  = {lease3, lease2, lease1, lease0};
   assign arb_stat_o   = {last_rv, park_v, park_lane, stv_any, revoke_cnt, ret_cnt, park_cnt};

    always @(posedge clk)
        assert (pool <= 2'd2);
endmodule

module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
   output wire [10:0] o_seq_stat
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
   wire frame_end = (phase == RUN) && last_col && last_row && !abort_req;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                       if (seq_fire)
                           phase <= RUN;
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                       if (arm_req || seq_rearm) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module toast_spi_cs_keeper (
   input  wire        clk,
   input  wire        rst,
   input  wire        en,
   input  wire        hold_done,
   input  wire        gap_end,
   input  wire        launch,
   input  wire        q_empty,
   input  wire [4:0]  head_slv,
   input  wire [4:0]  sel,
   output wire        keep,
   output wire        merge,
   output wire [23:0] rel_mask,
   output wire        held_o,
   output wire [2:0]  burst_o,
   output wire [2:0]  peak_o,
   output wire [7:0]  merge_cnt_o,
   output wire [7:0]  brk_cnt_o,
   output wire [23:0] merged_mask_o
);
   localparam [2:0] MAX_BURST = 3'd4;

   reg        held        = 1'b0;
   reg [2:0]  burst       = 3'd0;
   reg [2:0]  peak        = 3'd0;
   reg [7:0]  merge_cnt   = 8'd0;
   reg [7:0]  brk_cnt     = 8'd0;
   reg [23:0] merged_mask = 24'd0;

   // CS is carried into the gap when the burst has room and the next frame
   // targets the same slave, or the queue is empty (linger for a follow-up).
   wire       same_slv = (head_slv == sel);
   wire       room     = (burst < MAX_BURST);
   wire       cont     = held && launch && same_slv;
   wire       broken   = held && gap_end && !cont;
   wire [2:0] burst_nx = cont ? burst + 3'd1 : 3'd0;

   assign keep          = hold_done && room && (q_empty || same_slv);
   assign merge         = held && same_slv;
   assign rel_mask      = held ? (24'd1 << sel) : 24'd0;
   assign held_o        = held;
   assign burst_o       = burst;
   assign peak_o        = peak;
   assign merge_cnt_o   = merge_cnt;
   assign brk_cnt_o     = brk_cnt;
   assign merged_mask_o = merged_mask;

   always @(posedge clk) begin
       if (rst) begin
           held        <= 1'b0;
           burst       <= 3'd0;
           peak        <= 3'd0;
           merge_cnt   <= 8'd0;
           brk_cnt     <= 8'd0;
           merged_mask <= 24'd0;
       end else if (en) begin
           if (hold_done)
               held <= keep;
           else if (gap_end)
               held <= 1'b0;

           if (launch) begin
               burst <= burst_nx;
               if (burst_nx > peak)
                   peak <= burst_nx;
           end

           if (cont) begin
               if (merge_cnt != 8'hFF)
                   merge_cnt <= merge_cnt + 8'd1;
               merged_mask <= merged_mask | (24'd1 << sel);
           end

           if (broken && brk_cnt != 8'hFF)
               brk_cnt <= brk_cnt + 8'd1;
       end
   end
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
   output wire         full,
   output wire         cs_held,
   output wire [2:0]   cs_burst,
   output wire [2:0]   cs_peak_burst,
   output wire [7:0]   cs_merge_count,
   output wire [7:0]   cs_break_count,
   output wire [23:0]  cs_merged_slaves
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

    wire can_pop = (count != 5'd0) &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

   wire        hold_done = (st == ST_HOLD) && (dly == 8'd0);
   wire        gap_end   = (st == ST_GAP) && (dly == 8'd0);
   wire        cs_keep;
   wire        cs_merge;
   wire [23:0] cs_rel;
   wire        kp_held;
   wire [2:0]  kp_burst;
   wire [2:0]  kp_peak;

   toast_spi_cs_keeper u_keeper (
       .clk           (clk),
       .rst           (rst),
       .en            (en),
       .hold_done     (hold_done),
       .gap_end       (gap_end),
       .launch        (can_pop),
       .q_empty       (count == 5'd0),
       .head_slv      (head_slv),
       .sel           (sel),
       .keep          (cs_keep),
       .merge         (cs_merge),
       .rel_mask      (cs_rel),
       .held_o        (kp_held),
       .burst_o       (kp_burst),
       .peak_o        (kp_peak),
       .merge_cnt_o   (cs_merge_count),
       .brk_cnt_o     (cs_break_count),
       .merged_mask_o (cs_merged_slaves)
   );

   assign cs_held       = kp_held;
   assign cs_burst      = kp_burst;
   assign cs_peak_burst = kp_peak;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                       if (!cs_keep)
                           cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                       cs_vec <= (cs_vec & ~cs_rel) | (24'd1 << head_slv);
                        shreg  <= head_dat;
                       dly    <= cs_merge ? 8'd0 : cfg_setup;
                        st     <= ST_SETUP;
                   end else begin
                       cs_vec <= cs_vec & ~cs_rel;
                       st     <= ST_IDLE;
                   end
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
output wire [31:0] o_x3,
output wire        o_cmd_ready,
output wire [3:0]  o_cmd_level,
output wire        o_cmd_ovf,
output wire [3:0]  o_pend_go,
output wire        o_busy,
output wire [7:0]  o_seq_cnt,
output wire [7:0]  o_stall_cnt,
output wire [15:0] o_dirty
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];
reg        cq_we   [0:7];
reg [3:0]  cq_addr [0:7];
reg [31:0] cq_data [0:7];
reg        cq_go   [0:7];
reg        cq_mode [0:7];
reg [3:0]  cq_wptr;
reg [3:0]  cq_rptr;
reg        cs_v;
reg        cs_we;
reg [3:0]  cs_addr;
reg [31:0] cs_data;
reg        cs_go;
reg        cs_mode;
reg        cq_ovf;
reg [7:0]  seq_cnt;
reg [7:0]  stall_cnt;
reg [15:0] rf_dirty;

    integer i;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
cq_wptr   = 4'd0;
cq_rptr   = 4'd0;
cs_v      = 1'b0;
cs_we     = 1'b0;
cs_addr   = 4'd0;
cs_data   = 32'd0;
cs_go     = 1'b0;
cs_mode   = 1'b0;
cq_ovf    = 1'b0;
seq_cnt   = 8'd0;
stall_cnt = 8'd0;
rf_dirty  = 16'd0;
for (i = 0; i < 8; i = i + 1) begin
cq_we[i]   = 1'b0;
cq_addr[i] = 4'd0;
cq_data[i] = 32'd0;
cq_go[i]   = 1'b0;
cq_mode[i] = 1'b0;
end
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);
wire        cq_empty  = (cq_wptr == cq_rptr);
wire        cq_full   = (cq_wptr[3] != cq_rptr[3]) && (cq_wptr[2:0] == cq_rptr[2:0]);
wire [3:0]  cq_level  = cq_wptr - cq_rptr;
wire [2:0]  cq_widx   = cq_wptr[2:0];
wire [2:0]  cq_ridx   = cq_rptr[2:0];
wire        cq_flush  = en && clr;
wire        cmd_go    = start && armed && !cq_flush;
wire        cmd_req   = wr_en || cmd_go;
wire        cq_push   = cmd_req && !cq_full;
wire        cs_fire   = en && !clr && cs_v && (step == 32'd0);
wire        cs_launch = cs_fire && cs_go;
wire        cq_pop    = en && !clr && !cq_empty && (!cs_v || cs_fire);
reg [3:0] cq_pend_go;
reg [2:0] cq_off;
integer   j;
always @(*) begin
cq_pend_go = 4'd0;
for (j = 0; j < 8; j = j + 1) begin
cq_off = j - cq_ridx;
if (cq_go[j] && ({1'b0, cq_off} < cq_level))
cq_pend_go = cq_pend_go + 4'd1;
end
end

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
cq_wptr   <= 4'd0;
cq_rptr   <= 4'd0;
cs_v      <= 1'b0;
cs_we     <= 1'b0;
cs_addr   <= 4'd0;
cs_data   <= 32'd0;
cs_go     <= 1'b0;
cs_mode   <= 1'b0;
cq_ovf    <= 1'b0;
seq_cnt   <= 8'd0;
stall_cnt <= 8'd0;
rf_dirty  <= 16'd0;
for (i = 0; i < 8; i = i + 1) begin
cq_we[i]   <= 1'b0;
cq_addr[i] <= 4'd0;
cq_data[i] <= 32'd0;
cq_go[i]   <= 1'b0;
cq_mode[i] <= 1'b0;
end
end else begin
if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
if (cs_launch)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
if (cs_launch) begin
                    step <= 32'd1;
mode <= cs_mode;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
        end
if (cq_push) begin
cq_we[cq_widx]   <= wr_en;
cq_addr[cq_widx] <= wr_addr;
cq_data[cq_widx] <= wr_data;
cq_go[cq_widx]   <= cmd_go;
cq_mode[cq_widx] <= sel_add;
cq_wptr          <= cq_wptr + 4'd1;
end
if (cq_flush) begin
cq_rptr   <= cq_wptr;
cs_v      <= 1'b0;
cq_ovf    <= 1'b0;
stall_cnt <= 8'd0;
end else begin
if (cq_pop) begin
cs_v    <= 1'b1;
cs_we   <= cq_we[cq_ridx];
cs_addr <= cq_addr[cq_ridx];
cs_data <= cq_data[cq_ridx];
cs_go   <= cq_go[cq_ridx];
cs_mode <= cq_mode[cq_ridx];
cq_rptr <= cq_rptr + 4'd1;
end else if (cs_fire) begin
cs_v <= 1'b0;
end
if (cs_fire) begin
if (cs_go)
rf_dirty <= 16'd0;
else if (cs_we)
rf_dirty[cs_addr] <= 1'b1;
end
if (cs_launch)
seq_cnt <= seq_cnt + 8'd1;
if (cs_v && !cs_fire && stall_cnt != 8'hFF)
stall_cnt <= stall_cnt + 8'd1;
end
if (cmd_req && cq_full)
cq_ovf <= 1'b1;
end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
if (cs_fire && cs_we)
rf[cs_addr] <= cs_data;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];
assign o_cmd_ready = !cq_full;
assign o_cmd_level = cq_level;
assign o_cmd_ovf   = cq_ovf;
assign o_pend_go   = cq_pend_go + {3'd0, cs_v && cs_go};
assign o_busy      = (step != 32'd0) || cs_v || !cq_empty;
assign o_seq_cnt   = seq_cnt;
assign o_stall_cnt = stall_cnt;
assign o_dirty     = rf_dirty;

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

module tplan_launch_sched (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire fire_i,
   input wire restart_i,
   input wire abort_req,
   input wire frame_end_i,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire launch_o,
   output wire hold_o,
   output wire tok_o,
   output wire late_o,
   output wire [2:0] slot_o,
   output wire [2:0] last_slot_o,
   output wire [3:0] wait_max_o,
   output wire [3:0] skip_o,
   output wire [3:0] gap_o,
   output wire [6:0] hist_o,
   output wire [3:0] hist_vld_o
);
   reg [3:0] cfg_div;
   reg       cfg_align;
   reg       cfg_gap_en;
   reg       cfg_force;
   reg [3:0] cfg_dl;
   reg [3:0] cfg_gap;
   reg [1:0] cfg_hsel;
   reg [7:0] cfg_mask;
   reg [3:0] div_cnt;
   reg [2:0] slot_idx;
   reg       tok;
   reg [3:0] wait_cnt;
   reg [3:0] wait_max;
   reg       late;
   reg [3:0] skip_cnt;
   reg [3:0] gap_cnt;
   reg [2:0] last_slot;
   reg [6:0] hist [0:3];
   reg [3:0] hist_vld;
   integer g;
   integer h;
   initial begin
       for (g = 0; g < 4; g = g + 1)
           hist[g] = 7'd0;
   end
   initial cfg_div = 4'd0;
   initial cfg_align = 1'b0;
   initial cfg_gap_en = 1'b0;
   initial cfg_force = 1'b0;
   initial cfg_dl = 4'd0;
   initial cfg_gap = 4'd0;
   initial cfg_hsel = 2'd0;
   initial cfg_mask = 8'd0;
   initial div_cnt = 4'd0;
   initial slot_idx = 3'd0;
   initial tok = 1'b0;
   initial wait_cnt = 4'd0;
   initial wait_max = 4'd0;
   initial late = 1'b0;
   initial skip_cnt = 4'd0;
   initial gap_cnt = 4'd0;
   initial last_slot = 3'd0;
   initial hist_vld = 4'd0;
   // slot timebase: one slot every cfg_div+1 cycles, eight slots per window
   wire armed = (phase_i == 2'd1);
   wire slot_tick = (div_cnt >= cfg_div);
   wire slot_ok = (cfg_mask == 8'd0) || cfg_mask[slot_idx];
   wire aligned = !cfg_align || (slot_tick && slot_ok);
   wire dl_hit = (cfg_dl != 4'd0) && (wait_cnt >= cfg_dl);
   wire forced = cfg_force && tok && dl_hit;
   wire want = tok || fire_i;
   assign launch_o = armed && want && !abort_req && !restart_i && (aligned || forced);
   wire skipped = tok && cfg_align && slot_tick && !slot_ok && !launch_o;
   wire stat_clr = csr_we && (csr_addr == 3'd5) && csr_wdata[2];
   assign hold_o = cfg_gap_en && (gap_cnt != 4'd0);
   assign tok_o = tok;
   assign late_o = late;
   assign slot_o = slot_idx;
   assign last_slot_o = last_slot;
   assign wait_max_o = wait_max;
   assign skip_o = skip_cnt;
   assign gap_o = gap_cnt;
   assign hist_o = hist[cfg_hsel];
   assign hist_vld_o = hist_vld;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_div <= 4'd0;
           cfg_align <= 1'b0;
           cfg_gap_en <= 1'b0;
           cfg_force <= 1'b0;
           cfg_dl <= 4'd0;
           cfg_gap <= 4'd0;
           cfg_hsel <= 2'd0;
           cfg_mask <= 8'd0;
           div_cnt <= 4'd0;
           slot_idx <= 3'd0;
           tok <= 1'b0;
           wait_cnt <= 4'd0;
           wait_max <= 4'd0;
           late <= 1'b0;
           skip_cnt <= 4'd0;
           gap_cnt <= 4'd0;
           last_slot <= 3'd0;
           hist_vld <= 4'd0;
           for (h = 0; h < 4; h = h + 1)
               hist[h] <= 7'd0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd4: cfg_div <= csr_wdata[3:0];
                   3'd5: begin
                       cfg_align <= csr_wdata[0];
                       cfg_gap_en <= csr_wdata[1];
                       cfg_force <= csr_wdata[3];
                       cfg_dl <= csr_wdata[7:4];
                   end
                   3'd6: begin
                       cfg_gap <= csr_wdata[3:0];
                       cfg_hsel <= csr_wdata[5:4];
                   end
                   3'd7: cfg_mask <= csr_wdata;
               endcase
           end
           if (stat_clr) begin
               wait_max <= 4'd0;
               late <= 1'b0;
               skip_cnt <= 4'd0;
               hist_vld <= 4'd0;
           end
           if (slot_tick) begin
               div_cnt <= 4'd0;
               slot_idx <= slot_idx + 3'd1;
           end else begin
               div_cnt <= div_cnt + 4'd1;
           end
           if (abort_req) begin
               tok <= 1'b0;
               wait_cnt <= 4'd0;
               gap_cnt <= 4'd0;
           end else begin
               if (restart_i || !armed) begin
                   tok <= 1'b0;
                   wait_cnt <= 4'd0;
               end else if (launch_o) begin
                   tok <= 1'b0;
                   wait_cnt <= 4'd0;
                   last_slot <= slot_idx;
                   if (wait_cnt > wait_max)
                       wait_max <= wait_cnt;
                   hist[0] <= {slot_idx, wait_cnt};
                   for (h = 1; h < 4; h = h + 1)
                       hist[h] <= hist[h - 1];
                   hist_vld <= {hist_vld[2:0], 1'b1};
               end else if (fire_i) begin
                   tok <= 1'b1;
                   if (!tok)
                       wait_cnt <= 4'd0;
               end else if (tok) begin
                   if (wait_cnt != 4'hF)
                       wait_cnt <= wait_cnt + 4'd1;
               end
               if (tok && dl_hit)
                   late <= 1'b1;
               if (skipped && (skip_cnt != 4'hF))
                   skip_cnt <= skip_cnt + 4'd1;
               if (frame_end_i)
                   gap_cnt <= cfg_gap_en ? cfg_gap : 4'd0;
               else if (slot_tick && (gap_cnt != 4'd0))
                   gap_cnt <= gap_cnt - 4'd1;
           end
       end
   end
endmodule
module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
  output wire [10:0] o_seq_stat,
  output wire o_arm_rdy,
  output wire [20:0] o_lnch_stat,
  output wire [10:0] o_lnch_hist
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
   wire frame_end = (phase == RUN) && last_col && last_row && !abort_req;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );
  wire lnch_go, lnch_hold, lnch_tok, lnch_late;
  wire [2:0] lnch_slot, lnch_last;
  wire [3:0] lnch_wait_max, lnch_skip, lnch_gap;
  wire [6:0] lnch_hist;
  wire [3:0] lnch_hist_vld;
  tplan_launch_sched u_lnch (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .phase_i(phase),
      .fire_i(seq_fire),
      .restart_i(seq_start_ack),
      .abort_req(abort_req),
      .frame_end_i(frame_end),
      .csr_we(csr_we),
      .csr_addr(wr_addr[2:0]),
      .csr_wdata(wr_data[7:0]),
      .launch_o(lnch_go),
      .hold_o(lnch_hold),
      .tok_o(lnch_tok),
      .late_o(lnch_late),
      .slot_o(lnch_slot),
      .last_slot_o(lnch_last),
      .wait_max_o(lnch_wait_max),
      .skip_o(lnch_skip),
      .gap_o(lnch_gap),
      .hist_o(lnch_hist),
      .hist_vld_o(lnch_hist_vld)
  );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                      if (lnch_go)
                           phase <= RUN;
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                      if ((arm_req || seq_rearm) && !lnch_hold) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};
  assign o_arm_rdy = !lnch_hold;
  assign o_lnch_stat = {lnch_tok, lnch_late, lnch_hold, lnch_slot, lnch_last, lnch_wait_max, lnch_skip, lnch_gap};
  assign o_lnch_hist = {lnch_hist_vld, lnch_hist};

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

// In-band control/status bank for the CS sequencer. Frames pushed with the
// reserved slave index 31 are decoded here instead of entering the queue.
module toast_spi_cs_csr (
  input  wire         clk,
  input  wire         rst,
  input  wire         en,
  input  wire         wr,
  input  wire [127:0] wdata,
  input  wire         idle,
  input  wire         launch,
  input  wire         head_vld,
  input  wire [4:0]   head_slv,
  input  wire [4:0]   sel,
  input  wire [7:0]   dflt_setup,
  output wire         head_ok,
  output wire         merge_ok,
  output wire [7:0]   setup_dly,
  output wire         man_on_o,
  output wire [4:0]   man_slv_o,
  output wire [23:0]  man_mask,
  output wire         man_upd,
  output wire [23:0]  man_nx,
  output wire         pend_o,
  output wire [4:0]   pend_slv_o,
  output wire         blocked,
  output wire [23:0]  en_mask_o,
  output wire [23:0]  mrg_mask_o,
  output wire [23:0]  ovr_vld_o,
  output wire [7:0]   man_tmr_o,
  output wire [7:0]   cmd_cnt_o,
  output wire [7:0]   blk_cnt_o,
  output wire [1:0]   err_o
);
  localparam [7:0] OP_EN_WR  = 8'h01;
  localparam [7:0] OP_EN_SET = 8'h02;
  localparam [7:0] OP_EN_CLR = 8'h03;
  localparam [7:0] OP_MRG_WR = 8'h04;
  localparam [7:0] OP_MAN_CS = 8'h05;
  localparam [7:0] OP_SETUP  = 8'h06;
  localparam [7:0] OP_CLR_ST = 8'h07;

  reg [23:0] en_mask  = 24'hFFFFFF;
  reg [23:0] mrg_mask = 24'hFFFFFF;
  reg [23:0] ovr_vld  = 24'd0;
  reg [7:0]  ovr_dly [0:23];
  reg        man_on   = 1'b0;
  reg [4:0]  man_slv  = 5'd0;
  reg        man_lim  = 1'b0;
  reg [7:0]  man_tmr  = 8'd0;
  reg        pend     = 1'b0;
  reg        pend_on  = 1'b0;
  reg [4:0]  pend_slv = 5'd0;
  reg [7:0]  pend_tmo = 8'd0;
  reg [7:0]  cmd_cnt  = 8'd0;
  reg [7:0]  blk_cnt  = 8'd0;
  reg [1:0]  err      = 2'd0;

  integer k;
  initial begin
     for (k = 0; k < 24; k = k + 1)
        ovr_dly[k] = 8'd0;
  end

  // control word: [127:120] opcode, [24] flag, [23:16] timeout,
  // [15:8] delay, [4:0] slave index; mask opcodes use [23:0]
  wire [7:0]  op       = wdata[127:120];
  wire [4:0]  arg_slv  = wdata[4:0];
  wire [7:0]  arg_dly  = wdata[15:8];
  wire [7:0]  arg_tmo  = wdata[23:16];
  wire        arg_flag = wdata[24];
  wire [23:0] arg_mask = wdata[23:0];
  wire [23:0] arg_bit  = 24'd1 << arg_slv;
  wire        slv_op   = (op == OP_MAN_CS) || (op == OP_SETUP);
  wire        op_known = (op >= OP_EN_WR) && (op <= OP_CLR_ST);
  wire        bad_idx  = slv_op && (arg_slv >= 5'd24);
  wire        bad_op   = wr && !op_known;
  wire        bad_slv  = wr && op_known && bad_idx;
  wire        good     = wr && op_known && !bad_idx;

  wire       apply   = pend && idle && !launch;
  wire       expire  = man_on && man_lim && (man_tmr == 8'd0) &&
                       idle && !launch && !pend;
  wire [7:0] ovr_sel = ovr_dly[head_slv];

  assign head_ok    = en_mask[head_slv];
  assign blocked    = head_vld && !head_ok;
  assign merge_ok   = mrg_mask[sel];
  assign setup_dly  = ovr_vld[head_slv] ? ovr_sel : dflt_setup;
  assign man_mask   = man_on ? (24'd1 << man_slv) : 24'd0;
  assign man_upd    = apply || expire;
  assign man_nx     = (apply && pend_on) ? (24'd1 << pend_slv) : 24'd0;
  assign man_on_o   = man_on;
  assign man_slv_o  = man_slv;
  assign pend_o     = pend;
  assign pend_slv_o = pend_slv;
  assign en_mask_o  = en_mask;
  assign mrg_mask_o = mrg_mask;
  assign ovr_vld_o  = ovr_vld;
  assign man_tmr_o  = man_tmr;
  assign cmd_cnt_o  = cmd_cnt;
  assign blk_cnt_o  = blk_cnt;
  assign err_o      = err;

  always @(posedge clk) begin
     if (rst) begin
        en_mask  <= 24'hFFFFFF;
        mrg_mask <= 24'hFFFFFF;
        ovr_vld  <= 24'd0;
        man_on   <= 1'b0;
        man_slv  <= 5'd0;
        man_lim  <= 1'b0;
        man_tmr  <= 8'd0;
        pend     <= 1'b0;
        pend_on  <= 1'b0;
        pend_slv <= 5'd0;
        pend_tmo <= 8'd0;
        cmd_cnt  <= 8'd0;
        blk_cnt  <= 8'd0;
        err      <= 2'd0;
        for (k = 0; k < 24; k = k + 1)
           ovr_dly[k] <= 8'd0;
     end else if (en) begin
        if (good) begin
           case (op)
              OP_EN_WR:  en_mask  <= arg_mask;
              OP_EN_SET: en_mask  <= en_mask | arg_mask;
              OP_EN_CLR: en_mask  <= en_mask & ~arg_mask;
              OP_MRG_WR: mrg_mask <= arg_mask;
              OP_SETUP: begin
                 ovr_dly[arg_slv] <= arg_dly;
                 if (arg_flag)
                    ovr_vld <= ovr_vld | arg_bit;
                 else
                    ovr_vld <= ovr_vld & ~arg_bit;
              end
              default: ;
           endcase
        end

        // a manual select request waits until the sequencer is idle
        if (good && (op == OP_MAN_CS)) begin
           pend     <= 1'b1;
           pend_on  <= arg_flag;
           pend_slv <= arg_slv;
           pend_tmo <= arg_tmo;
        end else if (apply)
           pend <= 1'b0;

        // a queued frame always takes the select lines back
        if (launch) begin
           man_on  <= 1'b0;
           man_lim <= 1'b0;
           man_tmr <= 8'd0;
        end else if (apply) begin
           man_on  <= pend_on;
           man_slv <= pend_slv;
           man_lim <= pend_on && (pend_tmo != 8'd0);
           man_tmr <= pend_tmo;
        end else if (expire) begin
           man_on  <= 1'b0;
           man_lim <= 1'b0;
        end else if (man_on && man_lim && (man_tmr != 8'd0))
           man_tmr <= man_tmr - 8'd1;

        if (good && (op == OP_CLR_ST)) begin
           cmd_cnt <= 8'd0;
           blk_cnt <= 8'd0;
           err     <= 2'd0;
        end else begin
           if (good && (cmd_cnt != 8'hFF))
              cmd_cnt <= cmd_cnt + 8'd1;
           if (blocked && (blk_cnt != 8'hFF))
              blk_cnt <= blk_cnt + 8'd1;
           err <= err | {bad_slv, bad_op};
        end
     end
  end
endmodule

module toast_spi_cs_keeper (
   input  wire        clk,
   input  wire        rst,
   input  wire        en,
   input  wire        hold_done,
   input  wire        gap_end,
   input  wire        launch,
   input  wire        q_empty,
   input  wire [4:0]  head_slv,
   input  wire [4:0]  sel,
   output wire        keep,
   output wire        merge,
   output wire [23:0] rel_mask,
   output wire        held_o,
   output wire [2:0]  burst_o,
   output wire [2:0]  peak_o,
   output wire [7:0]  merge_cnt_o,
   output wire [7:0]  brk_cnt_o,
   output wire [23:0] merged_mask_o
);
   localparam [2:0] MAX_BURST = 3'd4;

   reg        held        = 1'b0;
   reg [2:0]  burst       = 3'd0;
   reg [2:0]  peak        = 3'd0;
   reg [7:0]  merge_cnt   = 8'd0;
   reg [7:0]  brk_cnt     = 8'd0;
   reg [23:0] merged_mask = 24'd0;

   // CS is carried into the gap when the burst has room and the next frame
   // targets the same slave, or the queue is empty (linger for a follow-up).
   wire       same_slv = (head_slv == sel);
   wire       room     = (burst < MAX_BURST);
   wire       cont     = held && launch && same_slv;
   wire       broken   = held && gap_end && !cont;
   wire [2:0] burst_nx = cont ? burst + 3'd1 : 3'd0;

   assign keep          = hold_done && room && (q_empty || same_slv);
   assign merge         = held && same_slv;
   assign rel_mask      = held ? (24'd1 << sel) : 24'd0;
   assign held_o        = held;
   assign burst_o       = burst;
   assign peak_o        = peak;
   assign merge_cnt_o   = merge_cnt;
   assign brk_cnt_o     = brk_cnt;
   assign merged_mask_o = merged_mask;

   always @(posedge clk) begin
       if (rst) begin
           held        <= 1'b0;
           burst       <= 3'd0;
           peak        <= 3'd0;
           merge_cnt   <= 8'd0;
           brk_cnt     <= 8'd0;
           merged_mask <= 24'd0;
       end else if (en) begin
           if (hold_done)
               held <= keep;
           else if (gap_end)
               held <= 1'b0;

           if (launch) begin
               burst <= burst_nx;
               if (burst_nx > peak)
                   peak <= burst_nx;
           end

           if (cont) begin
               if (merge_cnt != 8'hFF)
                   merge_cnt <= merge_cnt + 8'd1;
               merged_mask <= merged_mask | (24'd1 << sel);
           end

           if (broken && brk_cnt != 8'hFF)
               brk_cnt <= brk_cnt + 8'd1;
       end
   end
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
   output wire         full,
   output wire         cs_held,
   output wire [2:0]   cs_burst,
   output wire [2:0]   cs_peak_burst,
   output wire [7:0]   cs_merge_count,
   output wire [7:0]   cs_break_count,
  output wire [23:0]  cs_merged_slaves,
  output wire         cs_head_blocked,
  output wire         cs_manual,
  output wire         cs_cmd_pend,
  output wire [23:0]  cs_en_mask,
  output wire [23:0]  cs_merge_mask,
  output wire [23:0]  cs_setup_ovr,
  output wire [7:0]   cs_man_timer,
  output wire [7:0]   cs_cmd_count,
  output wire [7:0]   cs_blk_count,
  output wire [1:0]   cs_cmd_err
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

   // Frames pushed to the reserved index 31 are control words for the
   // CSR bank; a frame to a disabled slave waits at the queue head.
   wire        is_cmd = push && (push_slv == 5'd31);
   wire        csr_head_ok;
   wire        csr_merge_ok;
   wire [7:0]  csr_setup;
   wire        csr_man_on;
   wire [4:0]  csr_man_slv;
   wire [23:0] csr_man_mask;
   wire        csr_man_upd;
   wire [23:0] csr_man_nx;
   wire        csr_pend;
   wire [4:0]  csr_pend_slv;

   wire can_pop = (count != 5'd0) && csr_head_ok &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
   wire do_push = push && !is_cmd && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

   wire        hold_done = (st == ST_HOLD) && (dly == 8'd0);
   wire        gap_end   = (st == ST_GAP) && (dly == 8'd0);
   wire        cs_keep;
   wire        cs_merge;
   wire [23:0] cs_rel;
   wire        kp_held;
   wire [2:0]  kp_burst;
   wire [2:0]  kp_peak;

   toast_spi_cs_keeper u_keeper (
       .clk           (clk),
       .rst           (rst),
       .en            (en),
      .hold_done     (hold_done && csr_merge_ok),
       .gap_end       (gap_end),
       .launch        (can_pop),
       .q_empty       (count == 5'd0),
       .head_slv      (head_slv),
       .sel           (sel),
       .keep          (cs_keep),
       .merge         (cs_merge),
       .rel_mask      (cs_rel),
       .held_o        (kp_held),
       .burst_o       (kp_burst),
       .peak_o        (kp_peak),
       .merge_cnt_o   (cs_merge_count),
       .brk_cnt_o     (cs_break_count),
       .merged_mask_o (cs_merged_slaves)
   );

   assign cs_held       = kp_held;
   assign cs_burst      = kp_burst;
   assign cs_peak_burst = kp_peak;

  toast_spi_cs_csr u_csr (
      .clk        (clk),
      .rst        (rst),
      .en         (en),
      .wr         (is_cmd),
      .wdata      (push_data),
      .idle       (st == ST_IDLE),
      .launch     (can_pop),
      .head_vld   (count != 5'd0),
      .head_slv   (head_slv),
      .sel        (sel),
      .dflt_setup (cfg_setup),
      .head_ok    (csr_head_ok),
      .merge_ok   (csr_merge_ok),
      .setup_dly  (csr_setup),
      .man_on_o   (csr_man_on),
      .man_slv_o  (csr_man_slv),
      .man_mask   (csr_man_mask),
      .man_upd    (csr_man_upd),
      .man_nx     (csr_man_nx),
      .pend_o     (csr_pend),
      .pend_slv_o (csr_pend_slv),
      .blocked    (cs_head_blocked),
      .en_mask_o  (cs_en_mask),
      .mrg_mask_o (cs_merge_mask),
      .ovr_vld_o  (cs_setup_ovr),
      .man_tmr_o  (cs_man_timer),
      .cmd_cnt_o  (cs_cmd_count),
      .blk_cnt_o  (cs_blk_count),
      .err_o      (cs_cmd_err)
  );

  assign cs_manual   = csr_man_on;
  assign cs_cmd_pend = csr_pend;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                       cs_vec <= (cs_vec & ~csr_man_mask) | (24'd1 << head_slv);
                        shreg  <= head_dat;
                       dly    <= csr_setup;
                        st     <= ST_SETUP;
                   end else if (csr_man_upd) begin
                       cs_vec <= csr_man_nx;
                   end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                       if (!cs_keep)
                           cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                       cs_vec <= (cs_vec & ~cs_rel) | (24'd1 << head_slv);
                        shreg  <= head_dat;
                      dly    <= cs_merge ? 8'd0 : csr_setup;
                        st     <= ST_SETUP;
                   end else begin
                       cs_vec <= cs_vec & ~cs_rel;
                       st     <= ST_IDLE;
                   end
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);
endmodule

module toast_spi_rec_guard #(
    parameter [7:0] MIN_REC = 8'd16
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        rel,
    input  wire [4:0]  rel_slv,
    input  wire [7:0]  cfg_rec,
    input  wire        req,
    input  wire [4:0]  req_slv,
    output wire        hit,
    output wire        stall,
    output wire [23:0] mask,
    output wire [15:0] hist_tmr,
    output wire [9:0]  hist_slv,
    output wire [15:0] stall_cyc,
    output wire [7:0]  defer_cnt
);
    // Two slots cover the worst case: a recovery window is at most 255
    // cycles and consecutive CS releases are at least 131 cycles apart.
    localparam integer DEPTH = 2;

    reg [7:0]  tmr [0:DEPTH-1];
    reg [4:0]  slv [0:DEPTH-1];
    reg        stall_q = 1'b0;
    reg [7:0]  defers  = 8'd0;
    reg [15:0] stalls  = 16'd0;

    integer k;
    initial begin
        for (k = 0; k < DEPTH; k = k + 1) begin
            tmr[k] = 8'd0;
            slv[k] = 5'd0;
        end
    end

    reg [23:0] mask_c;
    integer j;
    always @(*) begin
        mask_c = 24'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            if (tmr[j] != 8'd0)
                mask_c = mask_c | (24'd1 << slv[j]);
    end

    wire [7:0] rec_len = (cfg_rec < MIN_REC) ? MIN_REC : cfg_rec;

    assign mask      = mask_c;
    assign hit       = (mask_c & (24'd1 << req_slv)) != 24'd0;
    assign stall     = req && hit;
    assign stall_cyc = stalls;
    assign defer_cnt = defers;

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : g_hist
            assign hist_tmr[8*g +: 8] = tmr[g];
            assign hist_slv[5*g +: 5] = slv[g];
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < DEPTH; k = k + 1) begin
                tmr[k] <= 8'd0;
                slv[k] <= 5'd0;
            end
            stall_q <= 1'b0;
            defers  <= 8'd0;
            stalls  <= 16'd0;
        end else if (en) begin
            for (k = 0; k < DEPTH; k = k + 1)
                if (tmr[k] != 8'd0)
                    tmr[k] <= tmr[k] - 8'd1;
            if (rel) begin
                tmr[0] <= rec_len;
                slv[0] <= rel_slv;
                for (k = 1; k < DEPTH; k = k + 1) begin
                    tmr[k] <= (tmr[k-1] != 8'd0) ? tmr[k-1] - 8'd1 : 8'd0;
                    slv[k] <= slv[k-1];
                end
            end
            stall_q <= stall;
            if (stall && (stalls != 16'hFFFF))
                stalls <= stalls + 16'd1;
            if (stall && !stall_q && (defers != 8'hFF))
                defers <= defers + 8'd1;
        end
    end
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire [23:0]  rec_mask,
    output wire         rec_stall,
    output wire [15:0]  rec_stall_cyc,
    output wire [7:0]   rec_defer,
    output wire         mosi,
    output wire         busy,
    output wire         full
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

    // Same-slave chip-select recovery guard
    wire        rg_hit;
    wire [15:0] rg_tmr;
    wire [9:0]  rg_slv;
    wire [7:0]  rec_tmr_new = rg_tmr[7:0];
    wire [7:0]  rec_tmr_old = rg_tmr[15:8];
    wire [4:0]  rec_slv_new = rg_slv[4:0];
    wire [4:0]  rec_slv_old = rg_slv[9:5];
    wire        cs_release  = (st == ST_HOLD) && (dly == 8'd0);

    wire pop_ready = (count != 5'd0) &&
                     ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
    wire can_pop   = pop_ready && !rg_hit;
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    toast_spi_rec_guard u_recg (
        .clk       (clk),
        .rst       (rst),
        .en        (en),
        .rel       (cs_release),
        .rel_slv   (sel),
        .cfg_rec   (cfg_hold),
        .req       (pop_ready),
        .req_slv   (head_slv),
        .hit       (rg_hit),
        .stall     (rec_stall),
        .mask      (rec_mask),
        .hist_tmr  (rg_tmr),
        .hist_slv  (rg_slv),
        .stall_cyc (rec_stall_cyc),
        .defer_cnt (rec_defer)
    );

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end else
                        st <= ST_IDLE;
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);

    // A recovery history slot is only recycled once its window has expired
    always @(posedge clk)
        if (cs_release)
            assert (rec_tmr_old == 8'd0);
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
output reg  [31:0] o_pkt_cnt,
output reg  [15:0] o_err_cnt,
output reg  [15:0] o_max_len,
output reg         o_wdog,
output reg  [7:0]  o_mon_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;
// link monitor / statistics (debug visibility only)
localparam [11:0] WDOG_LIMIT = 12'd2047;
reg [15:0] idle_cnt;
reg [11:0] wdog_cnt;
reg [15:0] cur_len;
reg [7:0]  rd_hist;
reg [1:0]  last_kcode;
reg        bad_k_seen;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
idle_cnt = 16'd0; wdog_cnt = 12'd0; cur_len = 16'd0; rd_hist = 8'd0;
last_kcode = 2'd0; bad_k_seen = 1'b0;
o_err_cnt = 16'd0; o_max_len = 16'd0; o_wdog = 1'b0; o_mon_status = 8'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
    wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
// monitor-side decodes
wire bad_k        = i_ce && i_k && !do_comma && !do_sof && !do_eof;
wire mon_pkt_data = do_data && (phase == PH_PKT);
wire [15:0] len_nxt = cur_len + 16'd1;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
idle_cnt <= 16'd0; wdog_cnt <= 12'd0; cur_len <= 16'd0; rd_hist <= 8'd0;
last_kcode <= 2'd0; bad_k_seen <= 1'b0;
o_err_cnt <= 16'd0; o_max_len <= 16'd0; o_wdog <= 1'b0; o_mon_status <= 8'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
if (!rst) begin
// idle cycle counter (saturating)
if (!i_ce && (idle_cnt != 16'hFFFF)) idle_cnt <= idle_cnt + 16'd1;
// illegal / out-of-sequence control symbol logger
if (bad_k) begin
bad_k_seen <= 1'b1;
if (o_err_cnt != 16'hFFFF) o_err_cnt <= o_err_cnt + 16'd1;
end
if (i_ce && i_k) last_kcode <= i_kcode;
// comma watchdog
if (do_comma) begin
wdog_cnt <= 12'd0;
o_wdog   <= 1'b0;
end else if (wdog_cnt != WDOG_LIMIT) begin
wdog_cnt <= wdog_cnt + 12'd1;
end else begin
o_wdog   <= 1'b1;
end
// packet payload length tracker
if (do_sof) begin
cur_len <= 16'd0;
end else if (mon_pkt_data && (cur_len != 16'hFFFF)) begin
cur_len <= len_nxt;
if (len_nxt > o_max_len) o_max_len <= len_nxt;
end
// running disparity history
if (i_ce) rd_hist <= {rd_hist[6:0], o_rd};
o_mon_status <= {bad_k_seen, (idle_cnt[15:12] != 4'd0), last_kcode, rd_hist[3:0]};
end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module tplan_px_drain (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire abort_req,
   input wire frame_act,
   input wire push,
   input wire push_eof,
   input wire [7:0] push_pix,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire ready,
   output wire drained,
   output wire eof_pend_o,
   output wire [2:0] fill_o,
   output wire [4:0] col_o,
   output wire [7:0] px_o,
   output wire px_vld_o,
   output wire px_eol_o,
   output wire hblank_o,
   output wire [7:0] sig_o,
   output wire [7:0] stall_o
);
   localparam [2:0] DEPTH = 3'd4;
   localparam [4:0] LINE_LAST = 5'd23;

   reg [7:0] fifo [0:3];
   reg [1:0] wr_ptr;
   reg [1:0] rd_ptr;
   reg [2:0] cnt;
   reg [3:0] cfg_div;
   reg [3:0] cfg_hblank;
   reg       cfg_inv;
   reg [7:0] cfg_blank;
   reg [3:0] div_cnt;
   reg [3:0] hb_cnt;
   reg [4:0] col_out;
   reg [7:0] px_q;
   reg       px_vld;
   reg       px_eol;
   reg       eof_pend;
   reg [7:0] sig_run;
   reg [7:0] sig_last;
   reg [7:0] stall_cnt;

   integer j;
   initial begin
       for (j = 0; j < 4; j = j + 1)
           fifo[j] = 8'h00;
   end
   initial wr_ptr = 2'd0;
   initial rd_ptr = 2'd0;
   initial cnt = 3'd0;
   initial cfg_div = 4'd0;
   initial cfg_hblank = 4'd0;
   initial cfg_inv = 1'b0;
   initial cfg_blank = 8'h00;
   initial div_cnt = 4'd0;
   initial hb_cnt = 4'd0;
   initial col_out = 5'd0;
   initial px_q = 8'h00;
   initial px_vld = 1'b0;
   initial px_eol = 1'b0;
   initial eof_pend = 1'b0;
   initial sig_run = 8'h00;
   initial sig_last = 8'h00;
   initial stall_cnt = 8'd0;

   function [7:0] crc8_step;
       input [7:0] c;
       input [7:0] d;
       integer b;
       reg [7:0] x;
       begin
           x = c ^ d;
           for (b = 0; b < 8; b = b + 1)
               x = x[7] ? ((x << 1) ^ 8'h07) : (x << 1);
           crc8_step = x;
       end
   endfunction

   wire full = (cnt == DEPTH);
   wire empty = (cnt == 3'd0);
   wire tick = (div_cnt == 4'd0);
   wire in_hb = (hb_cnt != 4'd0);
   wire acc = push && !full;
   wire pop = tick && !in_hb && !empty;
   wire [7:0] head_pix = fifo[rd_ptr] ^ {8{cfg_inv}};

   assign ready = !full;
   assign drained = eof_pend && empty && tick && !in_hb;
   assign eof_pend_o = eof_pend;
   assign fill_o = cnt;
   assign col_o = col_out;
   assign px_o = px_q;
   assign px_vld_o = px_vld;
   assign px_eol_o = px_eol;
   assign hblank_o = in_hb;
   assign sig_o = sig_last;
   assign stall_o = stall_cnt;

   always @(posedge clk) begin
       if (!rst_n) begin
           for (j = 0; j < 4; j = j + 1)
               fifo[j] <= 8'h00;
           wr_ptr <= 2'd0;
           rd_ptr <= 2'd0;
           cnt <= 3'd0;
           cfg_div <= 4'd0;
           cfg_hblank <= 4'd0;
           cfg_inv <= 1'b0;
           cfg_blank <= 8'h00;
           div_cnt <= 4'd0;
           hb_cnt <= 4'd0;
           col_out <= 5'd0;
           px_q <= 8'h00;
           px_vld <= 1'b0;
           px_eol <= 1'b0;
           eof_pend <= 1'b0;
           sig_run <= 8'h00;
           sig_last <= 8'h00;
           stall_cnt <= 8'd0;
       end else if (en) begin
           if (frame_act && full && !abort_req && (stall_cnt != 8'hFF))
               stall_cnt <= stall_cnt + 8'd1;
           if (csr_we) begin
               case (csr_addr)
                   3'd4: cfg_div <= csr_wdata[3:0];
                   3'd5: cfg_hblank <= csr_wdata[3:0];
                   3'd6: begin
                       cfg_inv <= csr_wdata[0];
                       if (csr_wdata[7])
                           stall_cnt <= 8'd0;
                   end
                   3'd7: cfg_blank <= csr_wdata;
               endcase
           end
           if (abort_req) begin
               wr_ptr <= 2'd0;
               rd_ptr <= 2'd0;
               cnt <= 3'd0;
               div_cnt <= 4'd0;
               hb_cnt <= 4'd0;
               col_out <= 5'd0;
               px_q <= cfg_blank;
               px_vld <= 1'b0;
               px_eol <= 1'b0;
               eof_pend <= 1'b0;
               sig_run <= 8'h00;
           end else begin
               if (acc) begin
                   fifo[wr_ptr] <= push_pix;
                   wr_ptr <= wr_ptr + 2'd1;
                   if (push_eof)
                       eof_pend <= 1'b1;
               end
               if (acc && !pop)
                   cnt <= cnt + 3'd1;
               else if (pop && !acc)
                   cnt <= cnt - 3'd1;
               if (!tick)
                   div_cnt <= div_cnt - 4'd1;
               else if (pop || in_hb)
                   div_cnt <= cfg_div;
               if (tick) begin
                   if (in_hb) begin
                       hb_cnt <= hb_cnt - 4'd1;
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end else if (pop) begin
                       px_q <= head_pix;
                       px_vld <= 1'b1;
                       rd_ptr <= rd_ptr + 2'd1;
                       sig_run <= crc8_step(sig_run, head_pix);
                       if (col_out == LINE_LAST) begin
                           col_out <= 5'd0;
                           hb_cnt <= cfg_hblank;
                           px_eol <= 1'b1;
                       end else begin
                           col_out <= col_out + 5'd1;
                           px_eol <= 1'b0;
                       end
                   end else begin
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end
               end
               if (drained) begin
                   eof_pend <= 1'b0;
                   sig_last <= sig_run;
                   sig_run <= 8'h00;
               end
           end
       end
   end
endmodule
module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
  output wire [10:0] o_seq_stat,
  output wire [7:0] o_scan_pix,
  output wire o_scan_vld,
  output wire o_scan_eol,
  output wire o_scan_hblank,
  output wire o_scan_ready,
  output wire o_drain_busy,
  output wire [7:0] o_scan_fill_col,
  output wire [7:0] o_frame_sig,
  output wire [7:0] o_scan_stall
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
  wire dr_ready, dr_drained, dr_eof_pend;
  wire dr_px_vld, dr_px_eol, dr_hblank;
  wire [2:0] dr_fill;
  wire [4:0] dr_col;
  wire [7:0] dr_px;
  wire [7:0] dr_sig;
  wire [7:0] dr_stall;
  wire [7:0] gen_pix = font_row(cur_char, row_cnt[2:0]);
  wire px_push = (phase == RUN) && !abort_req && dr_ready;
  wire frame_end = px_push && last_col && last_row;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );
  tplan_px_drain u_drain (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .abort_req(abort_req),
      .frame_act(phase == RUN),
      .push(px_push),
      .push_eof(last_col && last_row),
      .push_pix(gen_pix),
      .csr_we(csr_we),
      .csr_addr(wr_addr[2:0]),
      .csr_wdata(wr_data[7:0]),
      .ready(dr_ready),
      .drained(dr_drained),
      .eof_pend_o(dr_eof_pend),
      .fill_o(dr_fill),
      .col_o(dr_col),
      .px_o(dr_px),
      .px_vld_o(dr_px_vld),
      .px_eol_o(dr_px_eol),
      .hblank_o(dr_hblank),
      .sig_o(dr_sig),
      .stall_o(dr_stall)
  );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                       if (seq_fire)
                           phase <= RUN;
                    end
                    RUN: begin
                      if (dr_ready) begin
                       pix_row <= gen_pix;
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                      end
                    end
                    FIN: begin
                      if ((arm_req || seq_rearm) && !dr_eof_pend) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
              if (dr_drained)
                  done <= 1'b1;
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};
  assign o_scan_pix = dr_px;
  assign o_scan_vld = dr_px_vld;
  assign o_scan_eol = dr_px_eol;
  assign o_scan_hblank = dr_hblank;
  assign o_scan_ready = dr_ready;
  assign o_drain_busy = dr_eof_pend;
  assign o_scan_fill_col = {dr_fill, dr_col};
  assign o_frame_sig = dr_sig;
  assign o_scan_stall = dr_stall;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module toast_spi_cs_keeper (
   input  wire        clk,
   input  wire        rst,
   input  wire        en,
   input  wire        hold_done,
   input  wire        gap_end,
   input  wire        launch,
   input  wire        q_empty,
   input  wire [4:0]  head_slv,
   input  wire [4:0]  sel,
   output wire        keep,
   output wire        merge,
   output wire [23:0] rel_mask,
   output wire        held_o,
   output wire [2:0]  burst_o,
   output wire [2:0]  peak_o,
   output wire [7:0]  merge_cnt_o,
   output wire [7:0]  brk_cnt_o,
  output wire [23:0] merged_mask_o,
  output wire [2:0]  burst_nx_o
);
   localparam [2:0] MAX_BURST = 3'd4;

   reg        held        = 1'b0;
   reg [2:0]  burst       = 3'd0;
   reg [2:0]  peak        = 3'd0;
   reg [7:0]  merge_cnt   = 8'd0;
   reg [7:0]  brk_cnt     = 8'd0;
   reg [23:0] merged_mask = 24'd0;

   // CS is carried into the gap when the burst has room and the next frame
   // targets the same slave, or the queue is empty (linger for a follow-up).
   wire       same_slv = (head_slv == sel);
   wire       room     = (burst < MAX_BURST);
   wire       cont     = held && launch && same_slv;
   wire       broken   = held && gap_end && !cont;
   wire [2:0] burst_nx = cont ? burst + 3'd1 : 3'd0;

   assign keep          = hold_done && room && (q_empty || same_slv);
   assign merge         = held && same_slv;
   assign rel_mask      = held ? (24'd1 << sel) : 24'd0;
   assign held_o        = held;
   assign burst_o       = burst;
   assign peak_o        = peak;
   assign merge_cnt_o   = merge_cnt;
   assign brk_cnt_o     = brk_cnt;
   assign merged_mask_o = merged_mask;
  assign burst_nx_o    = burst_nx;

   always @(posedge clk) begin
       if (rst) begin
           held        <= 1'b0;
           burst       <= 3'd0;
           peak        <= 3'd0;
           merge_cnt   <= 8'd0;
           brk_cnt     <= 8'd0;
           merged_mask <= 24'd0;
       end else if (en) begin
           if (hold_done)
               held <= keep;
           else if (gap_end)
               held <= 1'b0;

           if (launch) begin
               burst <= burst_nx;
               if (burst_nx > peak)
                   peak <= burst_nx;
           end

           if (cont) begin
               if (merge_cnt != 8'hFF)
                   merge_cnt <= merge_cnt + 8'd1;
               merged_mask <= merged_mask | (24'd1 << sel);
           end

           if (broken && brk_cnt != 8'hFF)
               brk_cnt <= brk_cnt + 8'd1;
       end
   end
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
   output wire         full,
   output wire         cs_held,
   output wire [2:0]   cs_burst,
   output wire [2:0]   cs_peak_burst,
   output wire [7:0]   cs_merge_count,
   output wire [7:0]   cs_break_count,
  output wire [23:0]  cs_merged_slaves,
  output wire         trc_d,
  output wire         trc_frm,
  output wire         trc_eor,
  output wire         trc_rdy,
  output wire         trc_busy,
  output wire [3:0]   trc_level,
  output wire [3:0]   trc_hwm,
  output wire [4:0]   trc_last_slv,
  output wire [7:0]   trc_seq
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

   // Trace port: every launched frame posts a record into an 8-entry
   // record FIFO; a serializer ships records out on trc_d with a CRC-8.
   localparam [1:0] TX_IDLE = 2'd0;
   localparam [1:0] TX_BODY = 2'd1;
   localparam [1:0] TX_CRC  = 2'd2;
   localparam [1:0] TX_GAP  = 2'd3;
   localparam [7:0] TX_LAST = 8'd178;
   localparam [7:0] TX_IFG  = 8'd3;

   reg [4:0]   lg_slv [0:7];
   reg [2:0]   lg_pos [0:7];
   reg         lg_mrg [0:7];
   reg         lg_fst [0:7];
   reg [7:0]   lg_tsu [0:7];
   reg [7:0]   lg_prv [0:7];
   reg [7:0]   lg_seq [0:7];
   reg [15:0]  lg_ts  [0:7];
   reg [127:0] lg_dat [0:7];
   reg [3:0]   lg_wp  = 4'd0;
   reg [3:0]   lg_rp  = 4'd0;
   reg [3:0]   lg_hwm = 4'd0;
   reg [7:0]   fr_seq = 8'd0;
   reg [15:0]  ts_gap = 16'd0;

   // Per-slave history: sequence number of the last frame sent to a slave
   reg [7:0]   sl_seq [0:23];
   reg [23:0]  sl_seen = 24'd0;

   // Output stage between the record FIFO and the serializer
   reg         oh_vld = 1'b0;
   reg [4:0]   oh_slv = 5'd0;
   reg [2:0]   oh_pos = 3'd0;
   reg         oh_mrg = 1'b0;
   reg         oh_fst = 1'b0;
   reg [7:0]   oh_tsu = 8'd0;
   reg [7:0]   oh_prv = 8'd0;
   reg [7:0]   oh_seq = 8'd0;
   reg [15:0]  oh_ts  = 16'd0;
   reg [127:0] oh_dat = 128'd0;

   reg [1:0]   tx_st  = TX_IDLE;
   reg [7:0]   tx_cnt = 8'd0;
   reg [178:0] tx_sh  = 179'd0;
   reg [7:0]   tx_crc = 8'd0;
   reg         tx_out = 1'b0;
   reg         tx_frm = 1'b0;
   reg         tx_eor = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
           sl_seq[i] = 8'd0;
        end
       for (i = 0; i < 8; i = i + 1) begin
           lg_slv[i] = 5'd0;
           lg_pos[i] = 3'd0;
           lg_mrg[i] = 1'b0;
           lg_fst[i] = 1'b0;
           lg_tsu[i] = 8'd0;
           lg_prv[i] = 8'd0;
           lg_seq[i] = 8'd0;
           lg_ts[i]  = 16'd0;
           lg_dat[i] = 128'd0;
       end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

   wire [2:0]   lg_wi    = lg_wp[2:0];
   wire [2:0]   lg_ri    = lg_rp[2:0];
   wire [2:0]   lg_last  = lg_wi - 3'd1;
   wire [3:0]   lg_used  = lg_wp - lg_rp;
   wire         lg_empty = (lg_wp == lg_rp);
   wire         lg_full  = (lg_wp == {~lg_rp[3], lg_rp[2:0]});
   wire         lg_rdy   = !lg_full;
   wire         tx_take  = (tx_st == TX_IDLE) && oh_vld;
   wire         oh_load  = !lg_empty && (!oh_vld || tx_take);
   wire         tx_bit   = tx_sh[178];
   wire         tx_cnt_z = (tx_cnt == 8'd0);
   wire         crc_fb   = tx_crc[7] ^ tx_bit;
   wire [7:0]   crc_nx   = {tx_crc[6:0], 1'b0} ^ (crc_fb ? 8'h07 : 8'h00);
   wire [178:0] tx_rec   = {1'b1, oh_slv, oh_pos, oh_mrg, oh_fst, oh_tsu,
                            oh_prv, oh_seq, oh_ts, oh_dat};


   wire can_pop = (count != 5'd0) && lg_rdy &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
   wire [3:0] lg_used_nx = lg_used + {3'd0, can_pop} - {3'd0, oh_load};
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

   wire        hold_done = (st == ST_HOLD) && (dly == 8'd0);
   wire        gap_end   = (st == ST_GAP) && (dly == 8'd0);
   wire        cs_keep;
   wire        cs_merge;
   wire [23:0] cs_rel;
   wire        kp_held;
   wire [2:0]  kp_burst;
   wire [2:0]  kp_peak;
  wire [2:0]  kp_burst_nx;

   toast_spi_cs_keeper u_keeper (
       .clk           (clk),
       .rst           (rst),
       .en            (en),
       .hold_done     (hold_done),
       .gap_end       (gap_end),
       .launch        (can_pop),
       .q_empty       (count == 5'd0),
       .head_slv      (head_slv),
       .sel           (sel),
       .keep          (cs_keep),
       .merge         (cs_merge),
       .rel_mask      (cs_rel),
       .held_o        (kp_held),
       .burst_o       (kp_burst),
       .peak_o        (kp_peak),
       .merge_cnt_o   (cs_merge_count),
       .brk_cnt_o     (cs_break_count),
      .merged_mask_o (cs_merged_slaves),
      .burst_nx_o    (kp_burst_nx)
   );

   assign cs_held       = kp_held;
   assign cs_burst      = kp_burst;
   assign cs_peak_burst = kp_peak;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

   assign trc_d        = tx_out;
   assign trc_frm      = tx_frm;
   assign trc_eor      = tx_eor;
   assign trc_rdy      = lg_rdy;
   assign trc_busy     = !lg_empty || oh_vld || (tx_st != TX_IDLE);
   assign trc_level    = lg_used;
   assign trc_hwm      = lg_hwm;
   assign trc_last_slv = lg_slv[lg_last];
   assign trc_seq      = fr_seq;

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
           lg_wp   <= 4'd0;
           lg_rp   <= 4'd0;
           lg_hwm  <= 4'd0;
           fr_seq  <= 8'd0;
           ts_gap  <= 16'd0;
           sl_seen <= 24'd0;
           oh_vld  <= 1'b0;
           oh_slv  <= 5'd0;
           oh_pos  <= 3'd0;
           oh_mrg  <= 1'b0;
           oh_fst  <= 1'b0;
           oh_tsu  <= 8'd0;
           oh_prv  <= 8'd0;
           oh_seq  <= 8'd0;
           oh_ts   <= 16'd0;
           oh_dat  <= 128'd0;
           tx_st   <= TX_IDLE;
           tx_cnt  <= 8'd0;
           tx_sh   <= 179'd0;
           tx_crc  <= 8'd0;
           tx_out  <= 1'b0;
           tx_frm  <= 1'b0;
           tx_eor  <= 1'b0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

           // Trace capture: every launch posts one record. Launches are
           // held off by lg_rdy, so a record is never dropped.
           if (can_pop) begin
               lg_slv[lg_wi]    <= head_slv;
               lg_pos[lg_wi]    <= kp_burst_nx;
               lg_mrg[lg_wi]    <= cs_merge;
               lg_fst[lg_wi]    <= !sl_seen[head_slv];
               lg_tsu[lg_wi]    <= cs_merge ? 8'd0 : cfg_setup;
               lg_prv[lg_wi]    <= sl_seq[head_slv];
               lg_seq[lg_wi]    <= fr_seq;
               lg_ts[lg_wi]     <= ts_gap;
               lg_dat[lg_wi]    <= head_dat;
               lg_wp            <= lg_wp + 4'd1;
               fr_seq           <= fr_seq + 8'd1;
               sl_seq[head_slv] <= fr_seq;
               sl_seen          <= sl_seen | (24'd1 << head_slv);
               ts_gap           <= 16'd0;
           end else if (ts_gap != 16'hFFFF)
               ts_gap <= ts_gap + 16'd1;
           if (lg_used_nx > lg_hwm)
               lg_hwm <= lg_used_nx;

           // Output stage refills whenever empty or being handed over
           if (oh_load) begin
               oh_vld <= 1'b1;
               oh_slv <= lg_slv[lg_ri];
               oh_pos <= lg_pos[lg_ri];
               oh_mrg <= lg_mrg[lg_ri];
               oh_fst <= lg_fst[lg_ri];
               oh_tsu <= lg_tsu[lg_ri];
               oh_prv <= lg_prv[lg_ri];
               oh_seq <= lg_seq[lg_ri];
               oh_ts  <= lg_ts[lg_ri];
               oh_dat <= lg_dat[lg_ri];
               lg_rp  <= lg_rp + 4'd1;
           end else if (tx_take)
               oh_vld <= 1'b0;

           // Serializer: start bit + record body, then CRC-8, then a gap
           if ((tx_st != TX_IDLE) && !tx_cnt_z)
               tx_cnt <= tx_cnt - 8'd1;
           tx_eor <= 1'b0;
           case (tx_st)
               TX_IDLE: begin
                   if (tx_take) begin
                       tx_sh  <= tx_rec;
                       tx_cnt <= TX_LAST;
                       tx_crc <= 8'd0;
                       tx_st  <= TX_BODY;
                   end
               end
               TX_BODY: begin
                   tx_out <= tx_bit;
                   tx_frm <= 1'b1;
                   tx_crc <= crc_nx;
                   tx_sh  <= {tx_sh[177:0], 1'b0};
                   if (tx_cnt_z) begin
                       tx_cnt <= 8'd7;
                       tx_st  <= TX_CRC;
                   end
               end
               TX_CRC: begin
                   tx_out <= tx_crc[7];
                   tx_crc <= {tx_crc[6:0], 1'b0};
                   if (tx_cnt_z) begin
                       tx_cnt <= TX_IFG;
                       tx_eor <= 1'b1;
                       tx_st  <= TX_GAP;
                   end
               end
               default: begin
                   tx_out <= 1'b0;
                   tx_frm <= 1'b0;
                   if (tx_cnt_z)
                       tx_st <= TX_IDLE;
               end
           endcase

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                       if (!cs_keep)
                           cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                       cs_vec <= (cs_vec & ~cs_rel) | (24'd1 << head_slv);
                        shreg  <= head_dat;
                       dly    <= cs_merge ? 8'd0 : cfg_setup;
                        st     <= ST_SETUP;
                   end else begin
                       cs_vec <= cs_vec & ~cs_rel;
                       st     <= ST_IDLE;
                   end
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);

   // While a frame is on the wire, the newest trace record names the
   // asserted slave select and the keeper's burst position for it.
   always @(posedge clk)
       if (st == ST_SETUP || st == ST_XFER || st == ST_HOLD)
           assert (cs_vec == (24'd1 << lg_slv[lg_last]) &&
                   lg_pos[lg_last] == kp_burst);
endmodule

module wake_alloc_q #(
   parameter DEPTH = 4,
   parameter AW    = 2,
   parameter SLOTS = 32
) (
   input  wire          clk,
   input  wire          rst_n,
   input  wire          en,
   input  wire          in_vld,
   input  wire [31:0]   in_deps,
   output wire          in_rdy,
   input  wire          slot_ret,
   input  wire [31:0]   slot_clr,
   output wire          out_vld,
   output wire [31:0]   out_deps,
   output wire [5:0]    credits_o,
   output wire [AW:0]   count_o,
   output wire [7:0]    stall_o
);
   reg [31:0]   q_deps [0:DEPTH-1];
   reg [AW-1:0] wr_ptr   = {AW{1'b0}};
   reg [AW-1:0] rd_ptr   = {AW{1'b0}};
   reg [AW:0]   q_cnt    = {(AW+1){1'b0}};
   reg [5:0]    credits  = SLOTS;
   reg          stg_v    = 1'b0;
   reg [31:0]   stg_deps = 32'd0;
   reg [7:0]    stall    = 8'd0;

   integer i;
   initial for (i = 0; i < DEPTH; i = i + 1) q_deps[i] = 32'd0;
   initial wr_ptr   = {AW{1'b0}};
   initial rd_ptr   = {AW{1'b0}};
   initial q_cnt    = {(AW+1){1'b0}};
   initial credits  = SLOTS;
   initial stg_v    = 1'b0;
   initial stg_deps = 32'd0;
   initial stall    = 8'd0;

   wire q_empty = (q_cnt == {(AW+1){1'b0}});
   wire q_full  = (q_cnt == DEPTH);
   wire no_cred = (credits == 6'd0);
   wire push    = in_vld && !q_full;
   wire pop     = !q_empty && !no_cred;
   wire [31:0]   head_deps = q_deps[rd_ptr] & ~slot_clr;
   wire [AW-1:0] wr_nxt = (wr_ptr == DEPTH-1) ? {AW{1'b0}} : wr_ptr + 1'b1;
   wire [AW-1:0] rd_nxt = (rd_ptr == DEPTH-1) ? {AW{1'b0}} : rd_ptr + 1'b1;

   assign in_rdy    = !q_full;
   assign out_vld   = stg_v;
   assign out_deps  = stg_deps;
   assign credits_o = credits;
   assign count_o   = q_cnt;
   assign stall_o   = stall;

   integer j;
   always @(posedge clk) begin
       if (!rst_n) begin
           wr_ptr   <= {AW{1'b0}};
           rd_ptr   <= {AW{1'b0}};
           q_cnt    <= {(AW+1){1'b0}};
           credits  <= SLOTS;
           stg_v    <= 1'b0;
           stg_deps <= 32'd0;
           stall    <= 8'd0;
           for (j = 0; j < DEPTH; j = j + 1)
               q_deps[j] <= 32'd0;
       end else if (en) begin
           for (j = 0; j < DEPTH; j = j + 1)
               q_deps[j] <= q_deps[j] & ~slot_clr;
           if (push) begin
               q_deps[wr_ptr] <= in_deps & ~slot_clr;
               wr_ptr <= wr_nxt;
           end
           if (pop)
               rd_ptr <= rd_nxt;
           q_cnt    <= q_cnt + {{AW{1'b0}}, push} - {{AW{1'b0}}, pop};
           credits  <= credits + {5'd0, slot_ret} - {5'd0, pop};
           stg_v    <= pop;
           stg_deps <= pop ? head_deps : 32'd0;
           if (!q_empty && no_cred && (stall != 8'hff))
               stall <= stall + 8'd1;
       end
   end
endmodule

module pico_wakeup (
    input wire        clk,
    input wire        rst_n,
    input wire        en,
    input wire        alloc,
    input wire [31:0] alloc_deps,
    input wire        issue,
   input wire [4:0]  issue_idx,
   output wire       alloc_rdy,
   output wire       alloc_stg_v,
   output wire [5:0] alloc_credits,
   output wire [2:0] alloc_q_cnt,
   output wire [7:0] alloc_stall
);
    reg [31:0]   valid    = 32'd0;
    reg [1023:0] dep_flat = 1024'd0;
    reg [31:0]   pend     = 32'd0;
    reg [63:0]   occ      = 64'd0;
    reg [63:0]   wake_cnt = 64'd0;

    initial valid    = 32'd0;
    initial dep_flat = 1024'd0;
    initial pend     = 32'd0;
    initial occ      = 64'd0;
    initial wake_cnt = 64'd0;

    wire full = &valid;

    // lowest free index
    reg [4:0] free_idx;
    integer a;
    always @(*) begin
        free_idx = 5'd0;
        for (a = 31; a >= 0; a = a - 1)
            if (!valid[a]) free_idx = a[4:0];
    end

    // popcount of valid (status helper)
    reg [63:0] valid_cnt;
    integer b;
    always @(*) begin
        valid_cnt = 64'd0;
        for (b = 0; b < 32; b = b + 1)
            valid_cnt = valid_cnt + {63'd0, valid[b]};
    end

    // per-row OR of dependency matrix (status helper)
    reg [31:0] dep_or;
    integer c;
    always @(*) begin
        for (c = 0; c < 32; c = c + 1)
            dep_or[c] = |dep_flat[c*32 +: 32];
    end

   wire [31:0] aq_deps;
   wire alloc_fire = alloc_stg_v;
    wire issue_fire = issue && valid[issue_idx] && !pend[issue_idx];
    wire [31:0] clr_mask   = issue_fire ? (32'd1 << issue_idx) : 32'd0;
    wire [31:0] alloc_mask = alloc_fire ? (32'd1 << free_idx)  : 32'd0;
   wire [31:0] new_deps   = aq_deps & valid & ~clr_mask;

   // allocation request queue with slot credits
   wake_alloc_q #(.DEPTH(4), .AW(2), .SLOTS(32)) u_aq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .in_vld(alloc),
       .in_deps(alloc_deps),
       .in_rdy(alloc_rdy),
       .slot_ret(issue_fire),
       .slot_clr(clr_mask),
       .out_vld(alloc_stg_v),
       .out_deps(aq_deps),
       .credits_o(alloc_credits),
       .count_o(alloc_q_cnt),
       .stall_o(alloc_stall)
   );

    reg [1023:0] dep_nxt;
    reg [31:0]   pend_nxt;
    reg [63:0]   woke;
    integer k;
    always @(*) begin
        woke = 64'd0;
        dep_nxt = dep_flat;
        pend_nxt = pend;
        for (k = 0; k < 32; k = k + 1) begin
            if (alloc_mask[k]) begin
                dep_nxt[k*32 +: 32] = new_deps;
                pend_nxt[k] = |new_deps;
            end else if (clr_mask[k]) begin
                dep_nxt[k*32 +: 32] = 32'd0;
                pend_nxt[k] = 1'b0;
            end else begin
                dep_nxt[k*32 +: 32] = dep_flat[k*32 +: 32] & ~clr_mask;
                pend_nxt[k] = pend[k] && (|(dep_flat[k*32 +: 32] & ~clr_mask));
                if (pend[k] && !pend_nxt[k])
                    woke = woke + 64'd1;
            end
        end
    end

    wire [31:0] valid_nxt = (valid | alloc_mask) & ~clr_mask;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid    <= 32'd0;
            dep_flat <= 1024'd0;
            pend     <= 32'd0;
            occ      <= 64'd0;
            wake_cnt <= 64'd0;
        end else if (en) begin
            valid    <= valid_nxt;
            dep_flat <= dep_nxt;
            pend     <= pend_nxt;
            wake_cnt <= wake_cnt + woke;
            if (alloc_fire && !issue_fire)
                occ <= occ + 64'd1;
            else if (issue_fire && !alloc_fire)
                occ <= occ - 64'd1;
        end
    end

    always @(posedge clk)
        if (|valid) assert (occ <= 64'd32);
endmodule

module lookup_req_queue #(
   parameter DEPTH = 4,
   parameter AW    = 2
) (
   input  wire          clk,
   input  wire          rst,
   input  wire          ce,
   input  wire          push,
   input  wire [63:0]   push_key,
   input  wire [15:0]   push_len,
   input  wire          pop,
   input  wire          tbl_wr,
   input  wire [6:0]    tbl_idx,
   output wire          ready,
   output wire          avail,
   output wire [63:0]   head_key,
   output wire [15:0]   head_len,
   output reg  [AW:0]   count,
   output reg  [6:0]    hwm,
   output wire [6:0]    scan_lim
);
   reg [63:0]   key_q [0:DEPTH-1];
   reg [15:0]   len_q [0:DEPTH-1];
   reg [AW-1:0] wr_ptr;
   reg [AW-1:0] rd_ptr;

   integer n;
   initial begin
       for (n = 0; n < DEPTH; n = n + 1) begin
           key_q[n] = 64'd0;
           len_q[n] = 16'd0;
       end
       wr_ptr = {AW{1'b0}};
       rd_ptr = {AW{1'b0}};
       count  = {(AW+1){1'b0}};
       hwm    = 7'd0;
   end

   assign ready    = (count != DEPTH);
   assign avail    = (count != {(AW+1){1'b0}});
   assign head_key = key_q[rd_ptr];
   assign head_len = len_q[rd_ptr];
   // highest rule index that can hold a valid entry, including a write landing this cycle
   assign scan_lim = (tbl_wr && (tbl_idx > hwm)) ? tbl_idx : hwm;

   wire do_push = push && ready;
   wire do_pop  = pop && avail;

   always @(posedge clk) begin
       if (rst) begin
           wr_ptr <= {AW{1'b0}};
           rd_ptr <= {AW{1'b0}};
           count  <= {(AW+1){1'b0}};
           hwm    <= 7'd0;
       end else if (ce) begin
           if (do_push) begin
               key_q[wr_ptr] <= push_key;
               len_q[wr_ptr] <= push_len;
               wr_ptr        <= wr_ptr + 1'b1;
           end
           if (do_pop)
               rd_ptr <= rd_ptr + 1'b1;
           if (do_push && !do_pop)
               count <= count + 1'b1;
           else if (do_pop && !do_push)
               count <= count - 1'b1;
           if (tbl_wr)
               hwm <= scan_lim;
       end
   end
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
output reg  [6:0]  rsp_rule,
output wire        req_ready,
output wire [2:0]  req_pending,
output wire [6:0]  scan_limit
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;
reg [6:0]  q_lim;

wire        rq_ready;
wire        rq_avail;
wire [63:0] rq_key;
wire [15:0] rq_len;
wire [2:0]  rq_count;
wire [6:0]  rq_hwm;
wire [6:0]  rq_scan_lim;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
q_lim      = 7'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
wire last = (idx == q_lim);

lookup_req_queue #(.DEPTH(4), .AW(2)) u_req_q (
    .clk      (clk),
    .rst      (rst),
    .ce       (i_ce),
    .push     (req),
    .push_key (req_key),
    .push_len (req_len),
    .pop      (!busy),
    .tbl_wr   (wr_en && !busy),
    .tbl_idx  (wr_idx),
    .ready    (rq_ready),
    .avail    (rq_avail),
    .head_key (rq_key),
    .head_len (rq_len),
    .count    (rq_count),
    .hwm      (rq_hwm),
    .scan_lim (rq_scan_lim)
);

assign req_ready   = rq_ready;
assign req_pending = rq_count;
assign scan_limit  = rq_hwm;

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
q_lim     <= 7'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
if (rq_avail) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
timer <= {1'b0, rq_scan_lim} + 8'd1;
q_key <= rq_key;
q_len <= {48'd0, rq_len};
q_lim <= rq_scan_lim;
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
endmodule

// Host-side scheduler for the flow classifier. The flow table only takes a
// lookup or a rule write while it is not scanning, so both are queued here
// and handed over while no lookup is outstanding; every accepted lookup is
// given a sequence tag that comes back with its completion.
module lookup_scheduler #(
   parameter RQ_AW = 2,
   parameter WQ_AW = 2,
   parameter TAG_W = 4
) (
   input  wire             clk,
   input  wire             rst,
   input  wire             i_ce,
   input  wire             in_req,
   input  wire [63:0]      in_key,
   input  wire [15:0]      in_len,
   output wire             in_ready,
   output wire [TAG_W-1:0] in_tag,
   input  wire             in_wr,
   input  wire [6:0]       in_wr_idx,
   input  wire [63:0]      in_wr_key,
   input  wire [31:0]      in_wr_action,
   output wire             wr_ready,
   input  wire             tb_rsp_valid,
   input  wire             tb_rsp_hit,
   output wire             tb_req,
   output wire [63:0]      tb_key,
   output wire [15:0]      tb_len,
   output wire             tb_wr,
   output wire [6:0]       tb_wr_idx,
   output wire [63:0]      tb_wr_key,
   output wire [31:0]      tb_wr_action,
   output wire             done_valid,
   output wire             done_hit,
   output wire [TAG_W-1:0] done_tag,
   output wire             pend_o,
   output wire [RQ_AW:0]   rq_cnt_o,
   output wire [WQ_AW:0]   wq_cnt_o,
   output wire [RQ_AW:0]   rq_hwm_o,
   output wire [15:0]      miss_cnt_o
);
   localparam RQ_DEPTH = 1 << RQ_AW;
   localparam WQ_DEPTH = 1 << WQ_AW;
   reg [63:0]      rq_key [0:RQ_DEPTH-1];
   reg [15:0]      rq_len [0:RQ_DEPTH-1];
   reg [TAG_W-1:0] rq_tag [0:RQ_DEPTH-1];
   reg [RQ_AW-1:0] rq_wp;
   reg [RQ_AW-1:0] rq_rp;
   reg [RQ_AW:0]   rq_cnt;
   reg [RQ_AW:0]   rq_hwm;
   reg [TAG_W-1:0] tag_ctr;
   reg [6:0]       wq_idx [0:WQ_DEPTH-1];
   reg [63:0]      wq_key [0:WQ_DEPTH-1];
   reg [31:0]      wq_act [0:WQ_DEPTH-1];
   reg [WQ_AW-1:0] wq_wp;
   reg [WQ_AW-1:0] wq_rp;
   reg [WQ_AW:0]   wq_cnt;
   reg             pend;
   reg [TAG_W-1:0] cur_tag;
   reg [15:0]      miss_cnt;
   integer k;
   initial begin
       for (k = 0; k < RQ_DEPTH; k = k + 1) begin
           rq_key[k] = 64'd0;
           rq_len[k] = 16'd0;
           rq_tag[k] = {TAG_W{1'b0}};
       end
       for (k = 0; k < WQ_DEPTH; k = k + 1) begin
           wq_idx[k] = 7'd0;
           wq_key[k] = 64'd0;
           wq_act[k] = 32'd0;
       end
       rq_wp    = {RQ_AW{1'b0}};
       rq_rp    = {RQ_AW{1'b0}};
       rq_cnt   = {(RQ_AW+1){1'b0}};
       rq_hwm   = {(RQ_AW+1){1'b0}};
       tag_ctr  = {TAG_W{1'b0}};
       wq_wp    = {WQ_AW{1'b0}};
       wq_rp    = {WQ_AW{1'b0}};
       wq_cnt   = {(WQ_AW+1){1'b0}};
       pend     = 1'b0;
       cur_tag  = {TAG_W{1'b0}};
       miss_cnt = 16'd0;
   end
   wire rq_full  = (rq_cnt == RQ_DEPTH);
   wire rq_empty = (rq_cnt == 0);
   wire wq_full  = (wq_cnt == WQ_DEPTH);
   wire wq_empty = (wq_cnt == 0);
   // the table is handed work only while none of ours is outstanding
   assign tb_req = !pend && !rq_empty;
   assign tb_wr  = !pend && !wq_empty;
   wire rq_pop  = i_ce && tb_req;
   wire wq_pop  = i_ce && tb_wr;
   wire rq_push = i_ce && in_req && !rq_full;
   // a rule write to the same index as the newest queued write replaces it
   // in place, unless that entry is the one leaving for the table this cycle
   wire [WQ_AW-1:0] wq_tail = wq_wp - 1'b1;
   wire wq_tail_leaving = tb_wr && (wq_cnt == 1);
   wire wr_merge = !wq_empty && !wq_tail_leaving && (wq_idx[wq_tail] == in_wr_idx);
   wire wr_take  = i_ce && in_wr && (!wq_full || wr_merge);
   wire wr_push  = wr_take && !wr_merge;
   assign in_ready = !rq_full;
   assign in_tag   = tag_ctr;
   assign wr_ready = !wq_full || wr_merge;
   assign tb_key       = rq_key[rq_rp];
   assign tb_len       = rq_len[rq_rp];
   assign tb_wr_idx    = wq_idx[wq_rp];
   assign tb_wr_key    = wq_key[wq_rp];
   assign tb_wr_action = wq_act[wq_rp];
   wire done = tb_rsp_valid && pend;
   always @(posedge clk) begin
       if (rst) begin
           rq_wp   <= {RQ_AW{1'b0}};
           rq_rp   <= {RQ_AW{1'b0}};
           rq_cnt  <= {(RQ_AW+1){1'b0}};
           rq_hwm  <= {(RQ_AW+1){1'b0}};
           tag_ctr <= {TAG_W{1'b0}};
       end else if (i_ce) begin
           if (rq_push) begin
               rq_key[rq_wp] <= in_key;
               rq_len[rq_wp] <= in_len;
               rq_tag[rq_wp] <= tag_ctr;
               rq_wp         <= rq_wp + 1'b1;
               tag_ctr       <= tag_ctr + 1'b1;
           end
           if (rq_pop)
               rq_rp <= rq_rp + 1'b1;
           if (rq_push && !rq_pop)
               rq_cnt <= rq_cnt + 1'b1;
           else if (rq_pop && !rq_push)
               rq_cnt <= rq_cnt - 1'b1;
           if (rq_cnt > rq_hwm)
               rq_hwm <= rq_cnt;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           wq_wp  <= {WQ_AW{1'b0}};
           wq_rp  <= {WQ_AW{1'b0}};
           wq_cnt <= {(WQ_AW+1){1'b0}};
       end else if (i_ce) begin
           if (wr_take && wr_merge) begin
               wq_key[wq_tail] <= in_wr_key;
               wq_act[wq_tail] <= in_wr_action;
           end else if (wr_push) begin
               wq_idx[wq_wp] <= in_wr_idx;
               wq_key[wq_wp] <= in_wr_key;
               wq_act[wq_wp] <= in_wr_action;
               wq_wp         <= wq_wp + 1'b1;
           end
           if (wq_pop)
               wq_rp <= wq_rp + 1'b1;
           if (wr_push && !wq_pop)
               wq_cnt <= wq_cnt + 1'b1;
           else if (wq_pop && !wr_push)
               wq_cnt <= wq_cnt - 1'b1;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           pend     <= 1'b0;
           cur_tag  <= {TAG_W{1'b0}};
           miss_cnt <= 16'd0;
       end else if (i_ce) begin
           if (rq_pop) begin
               pend    <= 1'b1;
               cur_tag <= rq_tag[rq_rp];
           end else if (tb_rsp_valid) begin
               pend <= 1'b0;
           end
           if (done && !tb_rsp_hit && (miss_cnt != 16'hFFFF))
               miss_cnt <= miss_cnt + 16'd1;
       end
   end
   assign done_valid = done;
   assign done_hit   = tb_rsp_hit;
   assign done_tag   = cur_tag;
   assign pend_o     = pend;
   assign rq_cnt_o   = rq_cnt;
   assign wq_cnt_o   = wq_cnt;
   assign rq_hwm_o   = rq_hwm;
   assign miss_cnt_o = miss_cnt;
endmodule
module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module flow_mpu_top (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    output wire        grant,
    output wire        fault,
    output wire [6:0]  rsp_rule,
    output wire        g_valid_o,
    output wire [15:0] g_addr_o,
   output wire        g_write_o,
   output wire        req_ready,
   output wire [3:0]  req_tag,
   output wire        wr_ready,
   output wire        lk_done,
   output wire        lk_hit,
   output wire [3:0]  lk_tag,
   output wire        sch_pend_o,
   output wire [2:0]  rq_cnt_o,
   output wire [2:0]  wq_cnt_o,
   output wire [2:0]  rq_hwm_o,
   output wire [15:0] miss_cnt_o
);
    wire        rsp_valid;
    wire        rsp_hit;
    wire [31:0] rsp_action;
    wire        busy_a;
    wire [6:0]  idx_a;
    wire [7:0]  timer_a;
    wire        hit_q;
    wire        miss_q;
   wire        s_req;
   wire [63:0] s_key;
   wire [15:0] s_len;
   wire        s_wr;
   wire [6:0]  s_wr_idx;
   wire [63:0] s_wr_key;
   wire [31:0] s_wr_action;
   wire        sch_pend;
   wire [2:0]  rq_cnt;
   wire [2:0]  wq_cnt;
   wire [2:0]  rq_hwm;

    // pending destination-buffer access handed from the classifier to the MPU
    reg        g_valid;
    reg [15:0] g_addr;
    reg        g_write;

    initial begin
        g_valid = 1'b0;
        g_addr  = 16'd0;
        g_write = 1'b0;
    end

    flow_match_table u_flow (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
       .req(s_req),
       .req_key(s_key),
       .req_len(s_len),
       .wr_en(s_wr),
       .wr_idx(s_wr_idx),
       .wr_key(s_wr_key),
       .wr_action(s_wr_action),
        .rsp_valid(rsp_valid),
        .rsp_hit(rsp_hit),
        .rsp_action(rsp_action),
        .rsp_rule(rsp_rule),
        .busy_o(busy_a),
        .idx_o(idx_a),
        .timer_o(timer_a)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_valid <= 1'b0;
            g_addr  <= 16'd0;
            g_write <= 1'b0;
        end else if (i_ce) begin
            g_valid <= rsp_valid && rsp_hit;
            if (rsp_valid && rsp_hit) begin
                g_addr  <= rsp_action[15:0];
                g_write <= rsp_action[16];
            end
        end
    end

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(g_valid),
        .acc_write(g_write),
        .acc_addr(g_addr),
        .grant(grant),
        .fault(fault),
        .hit_q_o(hit_q),
        .miss_q_o(miss_q)
    );

    assign g_valid_o = g_valid;
    assign g_addr_o  = g_addr;
    assign g_write_o = g_write;
   lookup_scheduler #(
       .RQ_AW(2),
       .WQ_AW(2),
       .TAG_W(4)
   ) u_sched (
       .clk(clk),
       .rst(rst),
       .i_ce(i_ce),
       .in_req(req),
       .in_key(req_key),
       .in_len(req_len),
       .in_ready(req_ready),
       .in_tag(req_tag),
       .in_wr(wr_en),
       .in_wr_idx(wr_idx),
       .in_wr_key(wr_key),
       .in_wr_action(wr_action),
       .wr_ready(wr_ready),
       .tb_rsp_valid(rsp_valid),
       .tb_rsp_hit(rsp_hit),
       .tb_req(s_req),
       .tb_key(s_key),
       .tb_len(s_len),
       .tb_wr(s_wr),
       .tb_wr_idx(s_wr_idx),
       .tb_wr_key(s_wr_key),
       .tb_wr_action(s_wr_action),
       .done_valid(lk_done),
       .done_hit(lk_hit),
       .done_tag(lk_tag),
       .pend_o(sch_pend),
       .rq_cnt_o(rq_cnt),
       .wq_cnt_o(wq_cnt),
       .rq_hwm_o(rq_hwm),
       .miss_cnt_o(miss_cnt_o)
   );
   assign sch_pend_o = sch_pend;
   assign rq_cnt_o   = rq_cnt;
   assign wq_cnt_o   = wq_cnt;
   assign rq_hwm_o   = rq_hwm;
   // every response the flow table produces belongs to a lookup the scheduler handed it
   always @(posedge clk)
       if (rsp_valid)
           assert (sch_pend);

    // the MPU never holds two packet steering decisions in its check stage at once
    always @(posedge clk)
        if (g_valid)
            assert (!(hit_q || miss_q));
endmodule

// Fault log for the packet steering MPU. Every steering decision the MPU
// rejects is recorded with its destination, deliver flag, matching rule and
// a timestamp. Software reads the oldest entry and manages the log through
// the region indexes the MPU table does not implement (24 and up). A new
// lookup is only admitted when the log can absorb a fault from every
// decision still travelling down the steering pipeline.
module mpu_fault_log #(
    parameter DEPTH   = 4,
    parameter PTR_W   = 2,
    parameter CNT_W   = 3,
    parameter STAMP_W = 8
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               i_ce,
    input  wire               lk_busy,
    input  wire               rsp_fire,
    input  wire [6:0]         rsp_rule,
    input  wire               acc_pending,
    input  wire [15:0]        acc_addr,
    input  wire               acc_write,
    input  wire               chk_hit,
    input  wire               chk_miss,
    input  wire               csr_we,
    input  wire [4:0]         csr_idx,
    input  wire [15:0]        csr_wdata,
    input  wire               lk_req,
    output wire               lk_ready,
    output wire               lk_req_gated,
    output wire [CNT_W-1:0]   log_count,
    output wire               log_empty,
    output wire               log_full,
    output wire [15:0]        head_addr,
    output wire               head_write,
    output wire [6:0]         head_rule,
    output wire [STAMP_W-1:0] head_stamp,
    output wire [3:0]         head_rep,
    output wire [CNT_W+2:0]   ctrl_rb,
    output wire               irq,
    output wire [7:0]         ok_cnt,
    output wire [7:0]         flt_cnt
);
    localparam [4:0]       CSR_CTRL  = 5'd24;
    localparam [4:0]       CSR_POP   = 5'd25;
    localparam [4:0]       CSR_FLUSH = 5'd26;
    localparam [4:0]       CSR_STCLR = 5'd27;
    localparam [PTR_W-1:0] LAST_PTR  = DEPTH - 1;
    localparam [CNT_W-1:0] FULL_CNT  = DEPTH;
    localparam [CNT_W-1:0] ONE_CNT   = 1;
    // log storage
    reg [15:0]        ent_addr  [0:DEPTH-1];
    reg               ent_write [0:DEPTH-1];
    reg [6:0]         ent_rule  [0:DEPTH-1];
    reg [STAMP_W-1:0] ent_stamp [0:DEPTH-1];
    reg [3:0]         ent_rep   [0:DEPTH-1];
    reg [PTR_W-1:0]   wr_ptr;
    reg [PTR_W-1:0]   rd_ptr;
    reg [CNT_W-1:0]   count;
    // shadow of the decision in the access register (rule) and of the
    // decision in the MPU check stage (rule, destination, deliver flag)
    reg [6:0]         g_rule;
    reg [15:0]        c_addr;
    reg               c_write;
    reg [6:0]         c_rule;
    // control, timestamp and statistics
    reg [STAMP_W-1:0] stamp;
    reg               irq_en;
    reg               halt_en;
    reg               coal_en;
    reg [CNT_W-1:0]   wmark;
    reg               irq_q;
    reg [7:0]         ok_q;
    reg [7:0]         flt_q;
    integer k;
    initial begin
        for (k = 0; k < DEPTH; k = k + 1) begin
            ent_addr[k]  = 16'd0;
            ent_write[k] = 1'b0;
            ent_rule[k]  = 7'd0;
            ent_stamp[k] = {STAMP_W{1'b0}};
            ent_rep[k]   = 4'd0;
        end
        wr_ptr  = {PTR_W{1'b0}};
        rd_ptr  = {PTR_W{1'b0}};
        count   = {CNT_W{1'b0}};
        g_rule  = 7'd0;
        c_addr  = 16'd0;
        c_write = 1'b0;
        c_rule  = 7'd0;
        stamp   = {STAMP_W{1'b0}};
        irq_en  = 1'b0;
        halt_en = 1'b0;
        coal_en = 1'b0;
        wmark   = {CNT_W{1'b0}};
        irq_q   = 1'b0;
        ok_q    = 8'd0;
        flt_q   = 8'd0;
    end
    // CSR decode on the region indexes the MPU table does not implement
    wire csr_ctrl  = csr_we && (csr_idx == CSR_CTRL);
    wire csr_pop   = csr_we && (csr_idx == CSR_POP);
    wire csr_flush = csr_we && (csr_idx == CSR_FLUSH);
    wire csr_stclr = csr_we && (csr_idx == CSR_STCLR);
    wire empty = (count == {CNT_W{1'b0}});
    wire full  = (count == FULL_CNT);
    // ring pointers; wr_prev names the newest entry
    wire [PTR_W-1:0] wr_prev = (wr_ptr == {PTR_W{1'b0}}) ? LAST_PTR : wr_ptr - 1'b1;
    wire [PTR_W-1:0] wr_nxt  = (wr_ptr == LAST_PTR) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
    wire [PTR_W-1:0] rd_nxt  = (rd_ptr == LAST_PTR) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
    wire pop = csr_pop && !empty && !csr_flush;
    // a fault repeating the newest entry is folded into it when enabled,
    // unless that entry is being popped in the same cycle
    wire same_as_newest = (ent_addr[wr_prev] == c_addr) &&
                          (ent_write[wr_prev] == c_write) &&
                          (ent_rule[wr_prev] == c_rule);
    wire coalesce = chk_miss && coal_en && !empty && !csr_flush && same_as_newest &&
                    !(pop && (count == ONE_CNT));
    wire push = chk_miss && !coalesce && !full;
    // every decision still in the steering pipeline may turn into a fault;
    // a new lookup is only started when the log can absorb all of them
    wire [CNT_W:0] reserved = {1'b0, count}
                            + {{CNT_W{1'b0}}, lk_busy}
                            + {{CNT_W{1'b0}}, rsp_fire}
                            + {{CNT_W{1'b0}}, acc_pending}
                            + {{CNT_W{1'b0}}, chk_miss};
    wire room   = (reserved < DEPTH);
    wire halted = halt_en && !empty;
    assign lk_ready     = room && !halted;
    assign lk_req_gated = lk_req && lk_ready;
    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < DEPTH; k = k + 1) begin
                ent_addr[k]  <= 16'd0;
                ent_write[k] <= 1'b0;
                ent_rule[k]  <= 7'd0;
                ent_stamp[k] <= {STAMP_W{1'b0}};
                ent_rep[k]   <= 4'd0;
            end
            wr_ptr  <= {PTR_W{1'b0}};
            rd_ptr  <= {PTR_W{1'b0}};
            count   <= {CNT_W{1'b0}};
            g_rule  <= 7'd0;
            c_addr  <= 16'd0;
            c_write <= 1'b0;
            c_rule  <= 7'd0;
            stamp   <= {STAMP_W{1'b0}};
            irq_en  <= 1'b0;
            halt_en <= 1'b0;
            coal_en <= 1'b0;
            wmark   <= {CNT_W{1'b0}};
            irq_q   <= 1'b0;
            ok_q    <= 8'd0;
            flt_q   <= 8'd0;
        end else if (i_ce) begin
            stamp <= stamp + 1'b1;
            if (rsp_fire)
                g_rule <= rsp_rule;
            if (acc_pending) begin
                c_addr  <= acc_addr;
                c_write <= acc_write;
                c_rule  <= g_rule;
            end
            if (csr_ctrl) begin
                irq_en  <= csr_wdata[0];
                halt_en <= csr_wdata[1];
                coal_en <= csr_wdata[2];
                wmark   <= csr_wdata[8 +: CNT_W];
            end
            if (push) begin
                ent_addr[wr_ptr]  <= c_addr;
                ent_write[wr_ptr] <= c_write;
                ent_rule[wr_ptr]  <= c_rule;
                ent_stamp[wr_ptr] <= stamp;
                ent_rep[wr_ptr]   <= 4'd0;
                wr_ptr            <= wr_nxt;
            end
            if (coalesce && (ent_rep[wr_prev] != 4'hF))
                ent_rep[wr_prev] <= ent_rep[wr_prev] + 4'd1;
            if (csr_flush) begin
                rd_ptr <= wr_ptr;
                count  <= push ? ONE_CNT : {CNT_W{1'b0}};
            end else begin
                if (pop)
                    rd_ptr <= rd_nxt;
                count <= count + {{(CNT_W-1){1'b0}}, push} - {{(CNT_W-1){1'b0}}, pop};
            end
            if (csr_stclr) begin
                ok_q  <= 8'd0;
                flt_q <= 8'd0;
            end else begin
                if (chk_hit && (ok_q != 8'hFF))
                    ok_q <= ok_q + 8'd1;
                if (chk_miss && (flt_q != 8'hFF))
                    flt_q <= flt_q + 8'd1;
            end
            irq_q <= irq_en && (((wmark != {CNT_W{1'b0}}) && (count >= wmark)) || halted);
        end
    end
    assign log_count  = count;
    assign log_empty  = empty;
    assign log_full   = full;
    assign head_addr  = empty ? 16'd0 : ent_addr[rd_ptr];
    assign head_write = !empty && ent_write[rd_ptr];
    assign head_rule  = empty ? 7'd0 : ent_rule[rd_ptr];
    assign head_stamp = empty ? {STAMP_W{1'b0}} : ent_stamp[rd_ptr];
    assign head_rep   = empty ? 4'd0 : ent_rep[rd_ptr];
    assign ctrl_rb    = {wmark, coal_en, halt_en, irq_en};
    assign irq        = irq_q;
    assign ok_cnt     = ok_q;
    assign flt_cnt    = flt_q;
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module flow_mpu_top (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    output wire        grant,
    output wire        fault,
    output wire [6:0]  rsp_rule,
    output wire        g_valid_o,
    output wire [15:0] g_addr_o,
    output wire        g_write_o
,
    output wire        lookup_ready,
    output wire        flog_irq,
    output wire [2:0]  flog_count_o,
    output wire        flog_empty_o,
    output wire        flog_full_o,
    output wire [15:0] flog_head_addr,
    output wire        flog_head_write,
    output wire [6:0]  flog_head_rule,
    output wire [7:0]  flog_head_stamp,
    output wire [3:0]  flog_head_rep,
    output wire [5:0]  flog_ctrl,
    output wire [7:0]  steer_ok_cnt,
    output wire [7:0]  steer_flt_cnt
);
    wire        rsp_valid;
    wire        rsp_hit;
    wire [31:0] rsp_action;
    wire        busy_a;
    wire [6:0]  idx_a;
    wire [7:0]  timer_a;
    wire        hit_q;
    wire        miss_q;
    // fault log in front of the lookup request: every steering decision
    // still in flight holds one log slot in reserve
    localparam FLOG_DEPTH = 4;
    wire        flow_req;
    wire [2:0]  flog_count;
    wire        steer_fire = rsp_valid && rsp_hit;

    // pending destination-buffer access handed from the classifier to the MPU
    reg        g_valid;
    reg [15:0] g_addr;
    reg        g_write;

    initial begin
        g_valid = 1'b0;
        g_addr  = 16'd0;
        g_write = 1'b0;
    end

    flow_match_table u_flow (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
        .req(flow_req),
        .req_key(req_key),
        .req_len(req_len),
        .wr_en(wr_en),
        .wr_idx(wr_idx),
        .wr_key(wr_key),
        .wr_action(wr_action),
        .rsp_valid(rsp_valid),
        .rsp_hit(rsp_hit),
        .rsp_action(rsp_action),
        .rsp_rule(rsp_rule),
        .busy_o(busy_a),
        .idx_o(idx_a),
        .timer_o(timer_a)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_valid <= 1'b0;
            g_addr  <= 16'd0;
            g_write <= 1'b0;
        end else if (i_ce) begin
            g_valid <= rsp_valid && rsp_hit;
            if (rsp_valid && rsp_hit) begin
                g_addr  <= rsp_action[15:0];
                g_write <= rsp_action[16];
            end
        end
    end

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(g_valid),
        .acc_write(g_write),
        .acc_addr(g_addr),
        .grant(grant),
        .fault(fault),
        .hit_q_o(hit_q),
        .miss_q_o(miss_q)
    );
    mpu_fault_log #(
        .DEPTH(FLOG_DEPTH),
        .PTR_W(2),
        .CNT_W(3),
        .STAMP_W(8)
    ) u_flog (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
        .lk_busy(busy_a),
        .rsp_fire(steer_fire),
        .rsp_rule(rsp_rule),
        .acc_pending(g_valid),
        .acc_addr(g_addr),
        .acc_write(g_write),
        .chk_hit(hit_q),
        .chk_miss(miss_q),
        .csr_we(cfg_we),
        .csr_idx(cfg_idx),
        .csr_wdata(cfg_base),
        .lk_req(req),
        .lk_ready(lookup_ready),
        .lk_req_gated(flow_req),
        .log_count(flog_count),
        .log_empty(flog_empty_o),
        .log_full(flog_full_o),
        .head_addr(flog_head_addr),
        .head_write(flog_head_write),
        .head_rule(flog_head_rule),
        .head_stamp(flog_head_stamp),
        .head_rep(flog_head_rep),
        .ctrl_rb(flog_ctrl),
        .irq(flog_irq),
        .ok_cnt(steer_ok_cnt),
        .flt_cnt(steer_flt_cnt)
    );
    assign flog_count_o = flog_count;

    assign g_valid_o = g_valid;
    assign g_addr_o  = g_addr;
    assign g_write_o = g_write;

    // the MPU never holds two packet steering decisions in its check stage at once
    always @(posedge clk)
        if (g_valid)
            assert (!(hit_q || miss_q));
    // a steering decision the MPU rejects always finds a free fault-log slot
    always @(posedge clk)
        if (miss_q)
            assert (flog_count < FLOG_DEPTH);
endmodule

module flow_hint_cache #(
  parameter ENTRIES = 4,
  parameter EW      = 2,
  parameter RW      = 7
) (
  input  wire                  clk,
  input  wire                  rst,
  input  wire                  ce,
  input  wire                  inv_en,
  input  wire [RW-1:0]         inv_idx,
  input  wire                  lk_en,
  input  wire [63:0]           lk_key,
  input  wire                  fill_en,
  input  wire [63:0]           fill_key,
  input  wire [RW-1:0]         fill_rule,
  output reg                   lk_hit,
  output reg  [RW-1:0]         lk_rule,
  output wire [ENTRIES-1:0]    ent_vld,
  output wire [ENTRIES*RW-1:0] ent_rules,
  output reg  [EW:0]           occ,
  output reg  [15:0]           hit_cnt,
  output reg  [15:0]           evict_cnt
);
  // cached flow key -> lowest matching rule index
  reg [63:0]        c_key  [0:ENTRIES-1];
  reg [RW-1:0]      c_rule [0:ENTRIES-1];
  reg [ENTRIES-1:0] c_vld;
  // second-chance reference bits and clock hand for replacement
  reg [ENTRIES-1:0] c_ref;
  reg [EW-1:0]      hand;

  integer n;
  initial begin
      for (n = 0; n < ENTRIES; n = n + 1) begin
          c_key[n]  = 64'd0;
          c_rule[n] = {RW{1'b0}};
      end
      c_vld     = {ENTRIES{1'b0}};
      c_ref     = {ENTRIES{1'b0}};
      hand      = {EW{1'b0}};
      hit_cnt   = 16'd0;
      evict_cnt = 16'd0;
  end

  assign ent_vld = c_vld;

  genvar g;
  generate
      for (g = 0; g < ENTRIES; g = g + 1) begin : g_rule_out
          assign ent_rules[g*RW +: RW] = c_rule[g];
      end
  endgenerate

  // lookup port: lowest-numbered valid entry holding the key
  reg [EW-1:0] lk_slot;
  integer jl;
  always @(*) begin
      lk_hit  = 1'b0;
      lk_rule = {RW{1'b0}};
      lk_slot = {EW{1'b0}};
      for (jl = ENTRIES - 1; jl >= 0; jl = jl - 1) begin
          if (c_vld[jl] && (c_key[jl] == lk_key)) begin
              lk_hit  = 1'b1;
              lk_rule = c_rule[jl];
              lk_slot = jl;
          end
      end
  end

  // fill port: refresh in place if the key is already cached
  reg          fl_hit;
  reg [EW-1:0] fl_slot;
  integer jf;
  always @(*) begin
      fl_hit  = 1'b0;
      fl_slot = {EW{1'b0}};
      for (jf = ENTRIES - 1; jf >= 0; jf = jf - 1) begin
          if (c_vld[jf] && (c_key[jf] == fill_key)) begin
              fl_hit  = 1'b1;
              fl_slot = jf;
          end
      end
  end

  // first free entry
  reg          fr_any;
  reg [EW-1:0] fr_slot;
  integer jv;
  always @(*) begin
      fr_any  = 1'b0;
      fr_slot = {EW{1'b0}};
      for (jv = ENTRIES - 1; jv >= 0; jv = jv - 1) begin
          if (!c_vld[jv]) begin
              fr_any  = 1'b1;
              fr_slot = jv;
          end
      end
  end

  // clock replacement: first entry from the hand with its reference bit clear
  reg          sc_any;
  reg [EW-1:0] sc_slot;
  reg [EW-1:0] sc_probe;
  integer js;
  always @(*) begin
      sc_any   = 1'b0;
      sc_slot  = hand;
      sc_probe = hand;
      for (js = ENTRIES - 1; js >= 0; js = js - 1) begin
          sc_probe = hand + js;
          if (!c_ref[sc_probe]) begin
              sc_any  = 1'b1;
              sc_slot = sc_probe;
          end
      end
  end

  // reference bits after the hand sweeps past the entries it skipped
  reg [ENTRIES-1:0] ref_swept;
  reg [EW-1:0]      sc_dist;
  reg [EW-1:0]      ent_dist;
  integer jr;
  always @(*) begin
      sc_dist   = sc_slot - hand;
      ent_dist  = {EW{1'b0}};
      ref_swept = {ENTRIES{1'b0}};
      for (jr = 0; jr < ENTRIES; jr = jr + 1) begin
          ent_dist      = jr - hand;
          ref_swept[jr] = c_ref[jr] && sc_any && (ent_dist > sc_dist);
      end
  end

  // a rule written at inv_idx can shadow any cached result at or above it
  reg [ENTRIES-1:0] inv_mask;
  integer ji;
  always @(*) begin
      for (ji = 0; ji < ENTRIES; ji = ji + 1)
          inv_mask[ji] = c_vld[ji] && (c_rule[ji] >= inv_idx);
  end

  integer jo;
  always @(*) begin
      occ = {(EW+1){1'b0}};
      for (jo = 0; jo < ENTRIES; jo = jo + 1)
          occ = occ + c_vld[jo];
  end

  wire [EW-1:0] vic_slot = fl_hit ? fl_slot : (fr_any ? fr_slot : sc_slot);

  always @(posedge clk) begin
      if (rst) begin
          c_vld     <= {ENTRIES{1'b0}};
          c_ref     <= {ENTRIES{1'b0}};
          hand      <= {EW{1'b0}};
          hit_cnt   <= 16'd0;
          evict_cnt <= 16'd0;
      end else if (ce) begin
          if (inv_en) begin
              c_vld <= c_vld & ~inv_mask;
              c_ref <= c_ref & ~inv_mask;
          end else begin
              if (lk_en && lk_hit) begin
                  c_ref[lk_slot] <= 1'b1;
                  if (hit_cnt != 16'hffff)
                      hit_cnt <= hit_cnt + 16'd1;
              end
              if (fill_en) begin
                  c_key[vic_slot]  <= fill_key;
                  c_rule[vic_slot] <= fill_rule;
                  c_vld[vic_slot]  <= 1'b1;
                  if (fl_hit)
                      c_ref[vic_slot] <= 1'b1;
                  else if (fr_any)
                      c_ref[vic_slot] <= 1'b0;
                  else begin
                      c_ref <= ref_swept;
                      hand  <= sc_slot + 1'b1;
                      if (evict_cnt != 16'hffff)
                          evict_cnt <= evict_cnt + 16'd1;
                  end
              end
          end
      end
  end
endmodule

module lookup_req_queue #(
   parameter DEPTH = 4,
   parameter AW    = 2
) (
   input  wire          clk,
   input  wire          rst,
   input  wire          ce,
   input  wire          push,
   input  wire [63:0]   push_key,
   input  wire [15:0]   push_len,
   input  wire          pop,
   input  wire          tbl_wr,
   input  wire [6:0]    tbl_idx,
   output wire          ready,
   output wire          avail,
   output wire [63:0]   head_key,
   output wire [15:0]   head_len,
   output reg  [AW:0]   count,
   output reg  [6:0]    hwm,
   output wire [6:0]    scan_lim
);
   reg [63:0]   key_q [0:DEPTH-1];
   reg [15:0]   len_q [0:DEPTH-1];
   reg [AW-1:0] wr_ptr;
   reg [AW-1:0] rd_ptr;

   integer n;
   initial begin
       for (n = 0; n < DEPTH; n = n + 1) begin
           key_q[n] = 64'd0;
           len_q[n] = 16'd0;
       end
       wr_ptr = {AW{1'b0}};
       rd_ptr = {AW{1'b0}};
       count  = {(AW+1){1'b0}};
       hwm    = 7'd0;
   end

   assign ready    = (count != DEPTH);
   assign avail    = (count != {(AW+1){1'b0}});
   assign head_key = key_q[rd_ptr];
   assign head_len = len_q[rd_ptr];
   // highest rule index that can hold a valid entry, including a write landing this cycle
   assign scan_lim = (tbl_wr && (tbl_idx > hwm)) ? tbl_idx : hwm;

   wire do_push = push && ready;
   wire do_pop  = pop && avail;

   always @(posedge clk) begin
       if (rst) begin
           wr_ptr <= {AW{1'b0}};
           rd_ptr <= {AW{1'b0}};
           count  <= {(AW+1){1'b0}};
           hwm    <= 7'd0;
       end else if (ce) begin
           if (do_push) begin
               key_q[wr_ptr] <= push_key;
               len_q[wr_ptr] <= push_len;
               wr_ptr        <= wr_ptr + 1'b1;
           end
           if (do_pop)
               rd_ptr <= rd_ptr + 1'b1;
           if (do_push && !do_pop)
               count <= count + 1'b1;
           else if (do_pop && !do_push)
               count <= count - 1'b1;
           if (tbl_wr)
               hwm <= scan_lim;
       end
   end
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
output reg  [6:0]  rsp_rule,
output wire        req_ready,
output wire [2:0]  req_pending,
output wire [6:0]  scan_limit,
output reg         rsp_cached,
output wire [2:0]  cache_occ,
output wire [15:0] cache_hits,
output wire [15:0] cache_evicts
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;
reg [6:0]  q_lim;

wire        rq_ready;
wire        rq_avail;
wire [63:0] rq_key;
wire [15:0] rq_len;
wire [2:0]  rq_count;
wire [6:0]  rq_hwm;
wire [6:0]  rq_scan_lim;
reg         q_hint;
wire        fc_hit;
wire [6:0]  fc_rule;
wire [3:0]  fc_vld;
wire [27:0] fc_rules;
// start the scan at the cached rule unless a rule write lands this cycle
wire [6:0]  scan_start = (fc_hit && !wr_en) ? fc_rule : 7'd0;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
q_lim      = 7'd0;
       q_hint     = 1'b0;
       rsp_cached = 1'b0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
wire last = (idx == q_lim);

lookup_req_queue #(.DEPTH(4), .AW(2)) u_req_q (
    .clk      (clk),
    .rst      (rst),
    .ce       (i_ce),
    .push     (req),
    .push_key (req_key),
    .push_len (req_len),
    .pop      (!busy),
    .tbl_wr   (wr_en && !busy),
    .tbl_idx  (wr_idx),
    .ready    (rq_ready),
    .avail    (rq_avail),
    .head_key (rq_key),
    .head_len (rq_len),
    .count    (rq_count),
    .hwm      (rq_hwm),
    .scan_lim (rq_scan_lim)
);

assign req_ready   = rq_ready;
assign req_pending = rq_count;
assign scan_limit  = rq_hwm;

flow_hint_cache #(.ENTRIES(4), .EW(2), .RW(7)) u_fcache (
   .clk       (clk),
   .rst       (rst),
   .ce        (i_ce),
   .inv_en    (wr_en && !busy),
   .inv_idx   (wr_idx),
   .lk_en     (!busy && rq_avail && !wr_en),
   .lk_key    (rq_key),
   .fill_en   (busy && hit),
   .fill_key  (q_key),
   .fill_rule (idx),
   .lk_hit    (fc_hit),
   .lk_rule   (fc_rule),
   .ent_vld   (fc_vld),
   .ent_rules (fc_rules),
   .occ       (cache_occ),
   .hit_cnt   (cache_hits),
   .evict_cnt (cache_evicts)
);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
q_lim     <= 7'd0;
           q_hint     <= 1'b0;
           rsp_cached <= 1'b0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
if (rq_avail) begin
                    busy  <= 1'b1;
                   idx   <= scan_start;
timer <= {1'b0, rq_scan_lim} + 8'd1 - {1'b0, scan_start};
q_key <= rq_key;
q_len <= {48'd0, rq_len};
q_lim <= rq_scan_lim;
q_hint <= fc_hit && !wr_en;
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                   rsp_cached    <= q_hint;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                   rsp_cached    <= 1'b0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
   output wire [31:0] o_x3,
   output wire [2:0]  o_jq_cnt,
   output wire [2:0]  o_jq_hwm,
   output wire        o_jq_full,
   output wire        o_jq_ovf,
   output wire [7:0]  o_jq_drop,
   output wire        o_jq_hmode,
   output wire [31:0] o_jq_hseed,
   output wire        o_jq_tmode,
   output wire [31:0] o_jq_tseed,
   output wire        o_busy,
   output wire [2:0]  o_hist_cnt,
   output wire        o_hist_hit,
   output wire [31:0] o_hist_x,
   output wire [31:0] o_hist_y,
   output wire [31:0] o_hist_z,
   output wire        o_hist_md,
   output wire        o_hist_src,
   output wire [7:0]  o_hist_tag,
   output wire [7:0]  o_hist_lag,
   output wire [31:0] o_hist_sum,
   output wire [7:0]  o_job_seq,
   output wire [7:0]  o_n_qlaunch,
   output wire [7:0]  o_n_dbl,
   output wire [7:0]  o_n_add
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];
   localparam [2:0]  JQ_DEPTH = 3'd4;
   reg        jq_mode [0:3];
   reg        jq_ld   [0:3];
   reg [31:0] jq_seed [0:3];
   reg [1:0]  jq_wp;
   reg [1:0]  jq_rp;
   reg [2:0]  jq_cnt;
   reg [2:0]  jq_hwm;
   reg        jq_ovf;
   reg [7:0]  jq_drop;
   reg [7:0]  n_qlaunch;
   reg [31:0] hist_x   [0:3];
   reg [31:0] hist_y   [0:3];
   reg [31:0] hist_z   [0:3];
   reg        hist_md  [0:3];
   reg        hist_src [0:3];
   reg [7:0]  hist_tag [0:3];
   reg [1:0]  hist_wp;
   reg        hist_wrap;
   reg [31:0] hist_sum;
   reg [7:0]  job_seq;
   reg        job_src;
   reg [7:0]  n_dbl;
   reg [7:0]  n_add;

    integer i;
   integer k;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
       jq_wp     = 2'd0;
       jq_rp     = 2'd0;
       jq_cnt    = 3'd0;
       jq_hwm    = 3'd0;
       jq_ovf    = 1'b0;
       jq_drop   = 8'd0;
       n_qlaunch = 8'd0;
       hist_wp   = 2'd0;
       hist_wrap = 1'b0;
       hist_sum  = 32'd0;
       job_seq   = 8'd0;
       job_src   = 1'b0;
       n_dbl     = 8'd0;
       n_add     = 8'd0;
       for (i = 0; i < 4; i = i + 1) begin
           jq_mode[i]  = 1'b0;
           jq_ld[i]    = 1'b0;
           jq_seed[i]  = 32'd0;
           hist_x[i]   = 32'd0;
           hist_y[i]   = 32'd0;
           hist_z[i]   = 32'd0;
           hist_md[i]  = 1'b0;
           hist_src[i] = 1'b0;
           hist_tag[i] = 8'd0;
       end
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);
   wire        idle       = (step == 32'd0);
   wire        jq_empty   = (jq_cnt == 3'd0);
   wire        jq_full    = (jq_cnt == JQ_DEPTH);
   wire        req_ok     = start && armed && !clr;
   wire        q_launch   = en && idle && !clr && !jq_empty;
   wire        d_launch   = en && idle && req_ok && jq_empty;
   wire        job_launch = q_launch || d_launch;
   wire        req_queue  = en && req_ok && (!idle || !jq_empty);
   wire        jq_pop     = q_launch;
   wire        jq_push    = req_queue && (!jq_full || jq_pop);
   wire        jq_reject  = req_queue && jq_full && !jq_pop;
   wire [2:0]  jq_nxt_cnt = jq_cnt + {2'd0, jq_push} - {2'd0, jq_pop};
   wire [1:0]  jq_tail    = jq_wp - 2'd1;
   wire        hd_mode    = jq_mode[jq_rp];
   wire        hd_ld      = jq_ld[jq_rp];
   wire [31:0] hd_seed    = jq_seed[jq_rp];
   wire        nxt_mode   = q_launch ? hd_mode : sel_add;
   wire        job_end    = en && (step == LAST);
   wire [31:0] hist_nsum  = fadd(hist_sum, y3);
   wire [1:0]  hist_ra    = hist_wp - 2'd1 - wr_addr[1:0];
   wire [2:0]  hist_cnt   = hist_wrap ? 3'd4 : {1'b0, hist_wp};
   wire        hist_hit   = ({1'b0, wr_addr[1:0]} < hist_cnt);

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
           jq_wp     <= 2'd0;
           jq_rp     <= 2'd0;
           jq_cnt    <= 3'd0;
           jq_hwm    <= 3'd0;
           jq_ovf    <= 1'b0;
           jq_drop   <= 8'd0;
           n_qlaunch <= 8'd0;
           hist_wp   <= 2'd0;
           hist_wrap <= 1'b0;
           hist_sum  <= 32'd0;
           job_seq   <= 8'd0;
           job_src   <= 1'b0;
           n_dbl     <= 8'd0;
           n_add     <= 8'd0;
           for (k = 0; k < 4; k = k + 1) begin
               jq_mode[k]  <= 1'b0;
               jq_ld[k]    <= 1'b0;
               jq_seed[k]  <= 32'd0;
               hist_x[k]   <= 32'd0;
               hist_y[k]   <= 32'd0;
               hist_z[k]   <= 32'd0;
               hist_md[k]  <= 1'b0;
               hist_src[k] <= 1'b0;
               hist_tag[k] <= 8'd0;
           end
        end else if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
               if (job_launch)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
               if (job_launch) begin
                    step <= 32'd1;
                   mode    <= nxt_mode;
                   job_seq <= job_seq + 8'd1;
                   job_src <= q_launch;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
           if (clr) begin
               jq_wp  <= 2'd0;
               jq_rp  <= 2'd0;
               jq_cnt <= 3'd0;
               jq_ovf <= 1'b0;
           end else begin
               if (jq_push) begin
                   jq_mode[jq_wp] <= sel_add;
                   jq_ld[jq_wp]   <= wr_en;
                   jq_seed[jq_wp] <= wr_data;
                   jq_wp          <= jq_wp + 2'd1;
               end
               if (jq_pop) begin
                   jq_rp     <= jq_rp + 2'd1;
                   n_qlaunch <= n_qlaunch + 8'd1;
               end
               jq_cnt <= jq_nxt_cnt;
               if (jq_reject) begin
                   jq_ovf <= 1'b1;
                   if (jq_drop != 8'hFF)
                       jq_drop <= jq_drop + 8'd1;
               end
           end
           if (jq_cnt > jq_hwm)
               jq_hwm <= jq_cnt;
           if (job_end) begin
               hist_x[hist_wp]   <= rf[12];
               hist_y[hist_wp]   <= y3;
               hist_z[hist_wp]   <= z3;
               hist_md[hist_wp]  <= mode;
               hist_src[hist_wp] <= job_src;
               hist_tag[hist_wp] <= job_seq;
               hist_wp           <= hist_wp + 2'd1;
               if (hist_wp == 2'd3)
                   hist_wrap <= 1'b1;
               hist_sum <= hist_nsum;
               if (mode)
                   n_add <= n_add + 8'd1;
               else
                   n_dbl <= n_dbl + 8'd1;
           end
        end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
                if (wr_en)
                    rf[wr_addr] <= wr_data;
               if (q_launch && hd_ld)
                   rf[0] <= hd_seed;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];
   assign o_jq_cnt    = jq_cnt;
   assign o_jq_hwm    = jq_hwm;
   assign o_jq_full   = jq_full;
   assign o_jq_ovf    = jq_ovf;
   assign o_jq_drop   = jq_drop;
   assign o_jq_hmode  = jq_empty ? 1'b0 : hd_mode;
   assign o_jq_hseed  = (jq_empty || !hd_ld) ? 32'd0 : hd_seed;
   assign o_jq_tmode  = jq_empty ? 1'b0 : jq_mode[jq_tail];
   assign o_jq_tseed  = (jq_empty || !jq_ld[jq_tail]) ? 32'd0 : jq_seed[jq_tail];
   assign o_busy      = !idle || !jq_empty;
   assign o_hist_cnt  = hist_cnt;
   assign o_hist_hit  = hist_hit;
   assign o_hist_x    = hist_hit ? hist_x[hist_ra]   : 32'd0;
   assign o_hist_y    = hist_hit ? hist_y[hist_ra]   : 32'd0;
   assign o_hist_z    = hist_hit ? hist_z[hist_ra]   : 32'd0;
   assign o_hist_md   = hist_hit ? hist_md[hist_ra]  : 1'b0;
   assign o_hist_src  = hist_hit ? hist_src[hist_ra] : 1'b0;
   assign o_hist_tag  = hist_hit ? hist_tag[hist_ra] : 8'd0;
   assign o_hist_lag  = hist_hit ? (job_seq - hist_tag[hist_ra]) : 8'd0;
   assign o_hist_sum  = hist_sum;
   assign o_job_seq   = job_seq;
   assign o_n_qlaunch = n_qlaunch;
   assign o_n_dbl     = n_dbl;
   assign o_n_add     = n_add;

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

module benes_lane_shuffler (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    output wire         out_valid,
    output wire [511:0] out_data,
output wire [63:0]  o_beats_done,
output wire         out_inv_valid,
output wire [511:0] out_inv_data,
output wire [63:0]  o_inv_beats_done,
output wire         o_any_valid,
output wire [511:0] o_merged_data,
output wire [63:0]  o_dir_switches
);
    reg [19:0]  cfg_tab   [0:255];
    reg [3:0]   stage_cfg [0:4];
    reg [19:0]  cfg_pipe  [0:3];
    reg [511:0] data_pipe [0:4];
    reg [4:0]   valid_pipe;
    reg [63:0]  inflight;
    reg [63:0]  beats_done;
    reg         armed;
reg [19:0]  inv_cfg_pipe  [0:3];
reg [3:0]   inv_stage_cfg [0:4];
reg [511:0] inv_data_pipe [0:4];
reg [4:0]   inv_valid_pipe;
reg [63:0]  inv_beats_done;
reg         last_dir;
reg [63:0]  dir_switches;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) cfg_tab[i] = 20'd0;
        for (i = 0; i < 5; i = i + 1) begin
            stage_cfg[i] = 4'd0;
            data_pipe[i] = 512'd0;
        end
        for (i = 0; i < 4; i = i + 1) cfg_pipe[i] = 20'd0;
        valid_pipe = 5'd0;
        inflight   = 64'd0;
        beats_done = 64'd0;
        armed      = 1'b0;
for (i = 0; i < 5; i = i + 1) begin
inv_stage_cfg[i] = 4'd0;
inv_data_pipe[i] = 512'd0;
end
for (i = 0; i < 4; i = i + 1) inv_cfg_pipe[i] = 20'd0;
inv_valid_pipe = 5'd0;
inv_beats_done = 64'd0;
last_dir       = 1'b0;
dir_switches   = 64'd0;
    end

    // butterfly stage, pair distance 4
    function [511:0] sw4;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw4[0*64 +: 64] = c[0] ? d[4*64 +: 64] : d[0*64 +: 64];
            sw4[4*64 +: 64] = c[0] ? d[0*64 +: 64] : d[4*64 +: 64];
            sw4[1*64 +: 64] = c[1] ? d[5*64 +: 64] : d[1*64 +: 64];
            sw4[5*64 +: 64] = c[1] ? d[1*64 +: 64] : d[5*64 +: 64];
            sw4[2*64 +: 64] = c[2] ? d[6*64 +: 64] : d[2*64 +: 64];
            sw4[6*64 +: 64] = c[2] ? d[2*64 +: 64] : d[6*64 +: 64];
            sw4[3*64 +: 64] = c[3] ? d[7*64 +: 64] : d[3*64 +: 64];
            sw4[7*64 +: 64] = c[3] ? d[3*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 2
    function [511:0] sw2;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw2[0*64 +: 64] = c[0] ? d[2*64 +: 64] : d[0*64 +: 64];
            sw2[2*64 +: 64] = c[0] ? d[0*64 +: 64] : d[2*64 +: 64];
            sw2[1*64 +: 64] = c[1] ? d[3*64 +: 64] : d[1*64 +: 64];
            sw2[3*64 +: 64] = c[1] ? d[1*64 +: 64] : d[3*64 +: 64];
            sw2[4*64 +: 64] = c[2] ? d[6*64 +: 64] : d[4*64 +: 64];
            sw2[6*64 +: 64] = c[2] ? d[4*64 +: 64] : d[6*64 +: 64];
            sw2[5*64 +: 64] = c[3] ? d[7*64 +: 64] : d[5*64 +: 64];
            sw2[7*64 +: 64] = c[3] ? d[5*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 1 (middle stage)
    function [511:0] sw1;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw1[0*64 +: 64] = c[0] ? d[1*64 +: 64] : d[0*64 +: 64];
            sw1[1*64 +: 64] = c[0] ? d[0*64 +: 64] : d[1*64 +: 64];
            sw1[2*64 +: 64] = c[1] ? d[3*64 +: 64] : d[2*64 +: 64];
            sw1[3*64 +: 64] = c[1] ? d[2*64 +: 64] : d[3*64 +: 64];
            sw1[4*64 +: 64] = c[2] ? d[5*64 +: 64] : d[4*64 +: 64];
            sw1[5*64 +: 64] = c[2] ? d[4*64 +: 64] : d[5*64 +: 64];
            sw1[6*64 +: 64] = c[3] ? d[7*64 +: 64] : d[6*64 +: 64];
            sw1[7*64 +: 64] = c[3] ? d[6*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    wire [19:0] cfg0 = cfg_tab[in_sel];
// in_sel[7] routes the beat through the inverse (unshuffle) lane; both
// lanes share the single input port, the config table and the credit count
wire        go_inv     = in_valid & in_sel[7];
wire        go_fwd     = in_valid & ~in_sel[7];
wire        retire_fwd = valid_pipe[4];
wire        retire_inv = inv_valid_pipe[4];

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 256; i = i + 1) cfg_tab[i] <= 20'd0;
            for (i = 0; i < 5; i = i + 1) begin
                stage_cfg[i] <= 4'd0;
                data_pipe[i] <= 512'd0;
            end
            for (i = 0; i < 4; i = i + 1) cfg_pipe[i] <= 20'd0;
            valid_pipe <= 5'd0;
            inflight   <= 64'd0;
            beats_done <= 64'd0;
            armed      <= 1'b0;
for (i = 0; i < 5; i = i + 1) begin
inv_stage_cfg[i] <= 4'd0;
inv_data_pipe[i] <= 512'd0;
end
for (i = 0; i < 4; i = i + 1) inv_cfg_pipe[i] <= 20'd0;
inv_valid_pipe <= 5'd0;
inv_beats_done <= 64'd0;
last_dir       <= 1'b0;
dir_switches   <= 64'd0;
        end else if (en) begin
            if (cfg_we) begin
                cfg_tab[cfg_addr] <= cfg_bits;
                armed <= 1'b1;
            end
            data_pipe[0] <= sw4(in_data, cfg0[3:0]);
            stage_cfg[0] <= cfg0[3:0];
            cfg_pipe[0]  <= cfg0;
            data_pipe[1] <= sw2(data_pipe[0], cfg_pipe[0][7:4]);
            stage_cfg[1] <= cfg_pipe[0][7:4];
            cfg_pipe[1]  <= cfg_pipe[0];
            data_pipe[2] <= sw1(data_pipe[1], cfg_pipe[1][11:8]);
            stage_cfg[2] <= cfg_pipe[1][11:8];
            cfg_pipe[2]  <= cfg_pipe[1];
            data_pipe[3] <= sw2(data_pipe[2], cfg_pipe[2][15:12]);
            stage_cfg[3] <= cfg_pipe[2][15:12];
            cfg_pipe[3]  <= cfg_pipe[2];
            data_pipe[4] <= sw4(data_pipe[3], cfg_pipe[3][19:16]);
            stage_cfg[4] <= cfg_pipe[3][19:16];
valid_pipe <= {valid_pipe[3:0], go_fwd};
inflight   <= inflight + {63'd0, in_valid} - {63'd0, retire_fwd} - {63'd0, retire_inv};
            if (valid_pipe[4])
                beats_done <= beats_done + 64'd1;
// inverse lane: same switch stages, control fields applied in reverse
inv_data_pipe[0] <= sw4(in_data, cfg0[19:16]);
inv_stage_cfg[0] <= cfg0[19:16];
inv_cfg_pipe[0]  <= cfg0;
inv_data_pipe[1] <= sw2(inv_data_pipe[0], inv_cfg_pipe[0][15:12]);
inv_stage_cfg[1] <= inv_cfg_pipe[0][15:12];
inv_cfg_pipe[1]  <= inv_cfg_pipe[0];
inv_data_pipe[2] <= sw1(inv_data_pipe[1], inv_cfg_pipe[1][11:8]);
inv_stage_cfg[2] <= inv_cfg_pipe[1][11:8];
inv_cfg_pipe[2]  <= inv_cfg_pipe[1];
inv_data_pipe[3] <= sw2(inv_data_pipe[2], inv_cfg_pipe[2][7:4]);
inv_stage_cfg[3] <= inv_cfg_pipe[2][7:4];
inv_cfg_pipe[3]  <= inv_cfg_pipe[2];
inv_data_pipe[4] <= sw4(inv_data_pipe[3], inv_cfg_pipe[3][3:0]);
inv_stage_cfg[4] <= inv_cfg_pipe[3][3:0];
inv_valid_pipe <= {inv_valid_pipe[3:0], go_inv};
if (retire_inv)
inv_beats_done <= inv_beats_done + 64'd1;
// turnaround statistics: count lane direction changes on the input port
if (in_valid) begin
last_dir <= in_sel[7];
if (in_sel[7] != last_dir)
dir_switches <= dir_switches + 64'd1;
end
        end
    end

    assign out_valid    = valid_pipe[4];
    assign out_data     = data_pipe[4];
    assign o_beats_done = beats_done;
assign out_inv_valid    = inv_valid_pipe[4];
assign out_inv_data     = inv_data_pipe[4];
assign o_inv_beats_done = inv_beats_done;
assign o_any_valid      = retire_fwd | retire_inv;
assign o_merged_data    = retire_inv ? inv_data_pipe[4] : data_pipe[4];
assign o_dir_switches   = dir_switches;

    always @(posedge clk)
        if (armed)
            assert (inflight <= 64'd5);
endmodule

module fm_frame_guard (
   input  wire       clk,
   input  wire       rst,
   input  wire       i_open,
   input  wire       i_close,
   input  wire       i_byte,
   input  wire [7:0] i_data,
   output reg        o_open,
   output reg        o_abort,
   output reg  [5:0] o_len,
   output reg  [7:0] o_csum,
   output reg  [7:0] o_last_csum,
   output reg  [5:0] o_last_len,
   output reg  [5:0] o_max_len,
   output reg  [7:0] o_runt_cnt,
   output reg  [7:0] o_abort_cnt,
   output reg  [7:0] o_good_cnt,
   output reg  [1:0] o_status
);
   // frames longer than LEN_FULL payload bytes are cut off with an abort,
   // frames shorter than LEN_MIN bytes are counted as runts
   localparam [5:0] LEN_FULL = 6'd63;
   localparam [5:0] LEN_MIN  = 6'd4;
   localparam [1:0] ST_NONE = 2'd0, ST_GOOD = 2'd1, ST_RUNT = 2'd2, ST_ABORT = 2'd3;

   wire       byte_ok   = i_byte && o_open && !o_abort;
   wire       overrun   = byte_ok && (o_len == LEN_FULL);
   wire       close_frm = i_close && o_open;
   wire       is_runt   = (o_len < LEN_MIN);
   wire [7:0] csum_nxt  = {o_csum[6:0], o_csum[7]} ^ i_data;
   wire       runt_sat  = (o_runt_cnt == 8'hFF);
   wire       abort_sat = (o_abort_cnt == 8'hFF);
   wire       good_sat  = (o_good_cnt == 8'hFF);

   initial begin
       o_open = 1'b0; o_abort = 1'b0; o_len = 6'd0; o_csum = 8'd0;
       o_last_csum = 8'd0; o_last_len = 6'd0; o_max_len = 6'd0;
       o_runt_cnt = 8'd0; o_abort_cnt = 8'd0; o_good_cnt = 8'd0;
       o_status = ST_NONE;
   end

   // frame window and overrun abort request
   always @(posedge clk) begin
       if (rst) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (close_frm) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (i_open) begin
           o_open  <= 1'b1;
           o_abort <= 1'b0;
       end else if (overrun) begin
           o_abort <= 1'b1;
       end
   end

   // payload length and rotating checksum of the open frame
   always @(posedge clk) begin
       if (rst) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (i_open && !o_open) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (byte_ok && !overrun) begin
           o_len  <= o_len + 6'd1;
           o_csum <= csum_nxt;
       end
   end

   // record of the most recently closed frame
   always @(posedge clk) begin
       if (rst) begin
           o_last_csum <= 8'd0;
           o_last_len  <= 6'd0;
           o_status    <= ST_NONE;
       end else if (close_frm) begin
           o_last_csum <= o_csum;
           o_last_len  <= o_len;
           if (o_abort)
               o_status <= ST_ABORT;
           else if (is_runt)
               o_status <= ST_RUNT;
           else
               o_status <= ST_GOOD;
       end
   end

   // link statistics, saturating
   always @(posedge clk) begin
       if (rst) begin
           o_max_len   <= 6'd0;
           o_runt_cnt  <= 8'd0;
           o_abort_cnt <= 8'd0;
           o_good_cnt  <= 8'd0;
       end else if (close_frm) begin
           if (o_abort) begin
               if (!abort_sat) o_abort_cnt <= o_abort_cnt + 8'd1;
           end else begin
               if (o_len > o_max_len) o_max_len <= o_len;
               if (is_runt && !runt_sat) o_runt_cnt <= o_runt_cnt + 8'd1;
               if (!is_runt && !good_sat) o_good_cnt <= o_good_cnt + 8'd1;
           end
       end
   end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
   output reg  [31:0] o_pkt_cnt,
   output wire        o_frm_open,
   output wire        o_frm_abort,
   output wire [5:0]  o_frm_len,
   output wire [7:0]  o_frm_csum,
   output wire [7:0]  o_last_csum,
   output wire [5:0]  o_last_len,
   output wire [5:0]  o_max_len,
   output wire [7:0]  o_runt_cnt,
   output wire [7:0]  o_abort_cnt,
   output wire [7:0]  o_good_cnt,
   output wire [1:0]  o_frm_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
    wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;

   // frame length guard: a frame that overruns the payload limit is closed
   // early with a K30.7 abort symbol in place of the next offered symbol
   wire       frm_open, frm_abort;
   wire       do_abort = i_ce && frm_abort;

   fm_frame_guard u_guard (
       .clk        (clk),
       .rst        (rst),
       .i_open     (do_sof && !do_abort),
       .i_close    (do_abort || do_eof),
       .i_byte     (do_data && !do_abort),
       .i_data     (i_data),
       .o_open     (frm_open),
       .o_abort    (frm_abort),
       .o_len      (o_frm_len),
       .o_csum     (o_frm_csum),
       .o_last_csum(o_last_csum),
       .o_last_len (o_last_len),
       .o_max_len  (o_max_len),
       .o_runt_cnt (o_runt_cnt),
       .o_abort_cnt(o_abort_cnt),
       .o_good_cnt (o_good_cnt),
       .o_status   (o_frm_status)
   );

   assign o_frm_open  = frm_open;
   assign o_frm_abort = frm_abort;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
       end else if (do_abort) begin
           o_sym      <= o_rd ? 10'b1000010111 : 10'b0111101000;
           seen_end   <= 1'b1;
           phase      <= PH_ALIGN;
           o_sym_cnt  <= o_sym_cnt + 32'd1;
       end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire [63:0] o_hist_stamp,
   output wire [15:0] o_hist_sig,
   output wire [1:0] o_hist_state,
   output wire [2:0] o_hist_level,
   output wire o_hist_open,
   output wire [15:0] o_last_sig,
   output wire [7:0] o_hist_drops,
   output wire [7:0] o_abort_cnt,
   output wire [63:0] o_ret_stamp,
   output wire [15:0] o_ret_sig,
   output wire [1:0] o_ret_state,
   output wire o_ret_valid
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;
   localparam [1:0] ST_FREE = 2'd0, ST_OPEN = 2'd1, ST_DONE = 2'd2, ST_ABRT = 2'd3;
   localparam [4:0] HIST_CLR = 5'd30, HIST_ACK = 5'd31;
   localparam [2:0] HIST_DEPTH = 3'd4;
   // frame history: one record per launched frame, oldest at hist_rd_ptr
   reg [63:0] hist_mem [0:3];
   reg [15:0] hist_sum [0:3];
   reg [1:0]  hist_st  [0:3];
   reg [1:0]  hist_wr_ptr;
   reg [1:0]  hist_rd_ptr;
   reg [2:0]  hist_cnt;
   reg [7:0]  hist_drop;
   reg [7:0]  abort_cnt;
   reg [15:0] frame_sig;
   // last record retired through HIST_ACK
   reg [63:0] ret_stamp;
   reg [15:0] ret_sum;
   reg [1:0]  ret_st;
   reg        ret_vld;
   integer j;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;
   initial begin
       for (j = 0; j < 4; j = j + 1) begin
           hist_mem[j] = 64'd0;
           hist_sum[j] = 16'd0;
           hist_st[j] = ST_FREE;
       end
   end
   initial hist_wr_ptr = 2'd0;
   initial hist_rd_ptr = 2'd0;
   initial hist_cnt = 3'd0;
   initial hist_drop = 8'd0;
   initial abort_cnt = 8'd0;
   initial frame_sig = 16'd0;
   initial ret_stamp = 64'd0;
   initial ret_sum = 16'd0;
   initial ret_st = ST_FREE;
   initial ret_vld = 1'b0;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire [1:0]  hist_last  = hist_wr_ptr - 2'd1;
   wire        hist_empty = (hist_cnt == 3'd0);
   wire        hist_full  = (hist_cnt == HIST_DEPTH);
   // a new record is opened whenever a frame is launched
   wire        hist_push  = !abort_req && (phase == ARMED) && start_req;
   // the record of the frame on screen (running or just finished) may not be acked away
   wire        hist_pin   = (hist_cnt == 3'd1) && ((phase == RUN) || done);
   wire        hist_ack   = wr_en && (wr_addr == HIST_ACK) && !hist_empty && !hist_push && !hist_pin;
   wire        hist_clr   = wr_en && (wr_addr == HIST_CLR) && (phase != RUN) && !done && !hist_push;
   wire        frame_end  = !abort_req && (phase == RUN) && last_col && last_row;
   wire        frame_kill = abort_req && (phase == RUN);
   wire [7:0]  next_pix   = font_row(cur_char, row_cnt[2:0]);
   wire [15:0] next_sig   = {frame_sig[14:0], frame_sig[15] ^ frame_sig[12]} ^ {frame_sig[3:0], 4'h0, next_pix};

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
           for (j = 0; j < 4; j = j + 1) begin
               hist_mem[j] <= 64'd0;
               hist_sum[j] <= 16'd0;
               hist_st[j] <= ST_FREE;
           end
           hist_wr_ptr <= 2'd0;
           hist_rd_ptr <= 2'd0;
           hist_cnt <= 3'd0;
           hist_drop <= 8'd0;
           abort_cnt <= 8'd0;
           frame_sig <= 16'd0;
           ret_stamp <= 64'd0;
           ret_sum <= 16'd0;
           ret_st <= ST_FREE;
           ret_vld <= 1'b0;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
           // ---- frame history ----
           if (hist_push)
               frame_sig <= 16'd0;
           else if (!abort_req && (phase == RUN))
               frame_sig <= next_sig;
           if (hist_push) begin
               hist_mem[hist_wr_ptr] <= frame_cnt + 64'd1;
               hist_sum[hist_wr_ptr] <= 16'd0;
               hist_st[hist_wr_ptr] <= ST_OPEN;
               hist_wr_ptr <= hist_wr_ptr + 2'd1;
               if (hist_full) begin
                   // overwrite the oldest record and account for the loss
                   hist_rd_ptr <= hist_rd_ptr + 2'd1;
                   if (hist_drop != 8'hFF)
                       hist_drop <= hist_drop + 8'd1;
               end else begin
                   hist_cnt <= hist_cnt + 3'd1;
               end
           end else if (hist_ack) begin
               ret_stamp <= hist_mem[hist_rd_ptr];
               ret_sum <= hist_sum[hist_rd_ptr];
               ret_st <= hist_st[hist_rd_ptr];
               ret_vld <= 1'b1;
               hist_st[hist_rd_ptr] <= ST_FREE;
               hist_rd_ptr <= hist_rd_ptr + 2'd1;
               hist_cnt <= hist_cnt - 3'd1;
           end else if (hist_clr) begin
               for (j = 0; j < 4; j = j + 1)
                   hist_st[j] <= ST_FREE;
               hist_rd_ptr <= hist_wr_ptr;
               hist_cnt <= 3'd0;
               ret_vld <= 1'b0;
           end
           if (frame_kill) begin
               hist_st[hist_last] <= ST_ABRT;
               hist_sum[hist_last] <= frame_sig;
               if (abort_cnt != 8'hFF)
                   abort_cnt <= abort_cnt + 8'd1;
           end
           if (frame_end) begin
               hist_st[hist_last] <= ST_DONE;
               hist_sum[hist_last] <= next_sig;
           end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_hist_stamp = hist_empty ? 64'd0 : hist_mem[hist_rd_ptr];
   assign o_hist_sig = hist_empty ? 16'd0 : hist_sum[hist_rd_ptr];
   assign o_hist_state = hist_empty ? ST_FREE : hist_st[hist_rd_ptr];
   assign o_hist_level = hist_cnt;
   assign o_hist_open = !hist_empty && (hist_st[hist_last] == ST_OPEN);
   assign o_last_sig = hist_empty ? 16'd0 : hist_sum[hist_last];
   assign o_hist_drops = hist_drop;
   assign o_abort_cnt = abort_cnt;
   assign o_ret_stamp = ret_stamp;
   assign o_ret_sig = ret_sum;
   assign o_ret_state = ret_st;
   assign o_ret_valid = ret_vld;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);

   always @(posedge clk)
       if (done)
           assert (hist_cnt != 3'd0 && hist_st[hist_last] == ST_DONE && hist_mem[hist_last] == frame_cnt);
endmodule

module fm_frame_guard (
   input  wire       clk,
   input  wire       rst,
   input  wire       i_open,
   input  wire       i_close,
   input  wire       i_byte,
   input  wire [7:0] i_data,
   output reg        o_open,
   output reg        o_abort,
   output reg  [5:0] o_len,
   output reg  [7:0] o_csum,
   output reg  [7:0] o_last_csum,
   output reg  [5:0] o_last_len,
   output reg  [5:0] o_max_len,
   output reg  [7:0] o_runt_cnt,
   output reg  [7:0] o_abort_cnt,
   output reg  [7:0] o_good_cnt,
   output reg  [1:0] o_status
);
   // frames longer than LEN_FULL payload bytes are cut off with an abort,
   // frames shorter than LEN_MIN bytes are counted as runts
   localparam [5:0] LEN_FULL = 6'd63;
   localparam [5:0] LEN_MIN  = 6'd4;
   localparam [1:0] ST_NONE = 2'd0, ST_GOOD = 2'd1, ST_RUNT = 2'd2, ST_ABORT = 2'd3;

   wire       byte_ok   = i_byte && o_open && !o_abort;
   wire       overrun   = byte_ok && (o_len == LEN_FULL);
   wire       close_frm = i_close && o_open;
   wire       is_runt   = (o_len < LEN_MIN);
   wire [7:0] csum_nxt  = {o_csum[6:0], o_csum[7]} ^ i_data;
   wire       runt_sat  = (o_runt_cnt == 8'hFF);
   wire       abort_sat = (o_abort_cnt == 8'hFF);
   wire       good_sat  = (o_good_cnt == 8'hFF);

   initial begin
       o_open = 1'b0; o_abort = 1'b0; o_len = 6'd0; o_csum = 8'd0;
       o_last_csum = 8'd0; o_last_len = 6'd0; o_max_len = 6'd0;
       o_runt_cnt = 8'd0; o_abort_cnt = 8'd0; o_good_cnt = 8'd0;
       o_status = ST_NONE;
   end

   // frame window and overrun abort request
   always @(posedge clk) begin
       if (rst) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (close_frm) begin
           o_open  <= 1'b0;
           o_abort <= 1'b0;
       end else if (i_open) begin
           o_open  <= 1'b1;
           o_abort <= 1'b0;
       end else if (overrun) begin
           o_abort <= 1'b1;
       end
   end

   // payload length and rotating checksum of the open frame
   always @(posedge clk) begin
       if (rst) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (i_open && !o_open) begin
           o_len  <= 6'd0;
           o_csum <= 8'd0;
       end else if (byte_ok && !overrun) begin
           o_len  <= o_len + 6'd1;
           o_csum <= csum_nxt;
       end
   end

   // record of the most recently closed frame
   always @(posedge clk) begin
       if (rst) begin
           o_last_csum <= 8'd0;
           o_last_len  <= 6'd0;
           o_status    <= ST_NONE;
       end else if (close_frm) begin
           o_last_csum <= o_csum;
           o_last_len  <= o_len;
           if (o_abort)
               o_status <= ST_ABORT;
           else if (is_runt)
               o_status <= ST_RUNT;
           else
               o_status <= ST_GOOD;
       end
   end

   // link statistics, saturating
   always @(posedge clk) begin
       if (rst) begin
           o_max_len   <= 6'd0;
           o_runt_cnt  <= 8'd0;
           o_abort_cnt <= 8'd0;
           o_good_cnt  <= 8'd0;
       end else if (close_frm) begin
           if (o_abort) begin
               if (!abort_sat) o_abort_cnt <= o_abort_cnt + 8'd1;
           end else begin
               if (o_len > o_max_len) o_max_len <= o_len;
               if (is_runt && !runt_sat) o_runt_cnt <= o_runt_cnt + 8'd1;
               if (!is_runt && !good_sat) o_good_cnt <= o_good_cnt + 8'd1;
           end
       end
   end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
   output reg  [31:0] o_pkt_cnt,
   output wire        o_frm_open,
   output wire        o_frm_abort,
   output wire [5:0]  o_frm_len,
   output wire [7:0]  o_frm_csum,
   output wire [7:0]  o_last_csum,
   output wire [5:0]  o_last_len,
   output wire [5:0]  o_max_len,
   output wire [7:0]  o_runt_cnt,
   output wire [7:0]  o_abort_cnt,
   output wire [7:0]  o_good_cnt,
output wire [1:0]  o_frm_status,
output reg         o_desc_valid,
output reg  [5:0]  o_desc_len,
output reg  [7:0]  o_desc_csum,
output reg  [1:0]  o_desc_stat,
output reg  [3:0]  o_desc_seq,
output reg         o_desc_perr,
output wire [3:0]  o_q_level,
output wire        o_q_full,
output reg  [7:0]  o_sof_refused
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;
   // frame descriptor queue: each accepted SOF reserves the youngest slot,
   // the slot is completed with length, checksum and status when the frame
   // closes (EOF or abort), and completed slots are handed to the host port
   // in order on idle (clock-enable low) cycles, one every DRAIN_GAP+1 cycles
   localparam [3:0] Q_DEPTH   = 4'd8;
   localparam [1:0] DRAIN_GAP = 2'd3;
   localparam [5:0] RUNT_LEN  = 6'd4;
   localparam [1:0] ST_NONE = 2'd0, ST_GOOD = 2'd1, ST_RUNT = 2'd2, ST_ABORT = 2'd3;
   reg  [2:0] q_wr, q_rd;
   reg  [3:0] q_cnt;
   reg  [7:0] q_done;
   reg  [1:0] q_hold;
   reg  [3:0] q_seq;
   reg  [5:0] q0_len, q1_len, q2_len, q3_len, q4_len, q5_len, q6_len, q7_len;
   reg  [7:0] q0_csum, q1_csum, q2_csum, q3_csum, q4_csum, q5_csum, q6_csum, q7_csum;
   reg  [1:0] q0_stat, q1_stat, q2_stat, q3_stat, q4_stat, q5_stat, q6_stat, q7_stat;
   reg  [3:0] q0_seq, q1_seq, q2_seq, q3_seq, q4_seq, q5_seq, q6_seq, q7_seq;
   reg        q0_par, q1_par, q2_par, q3_par, q4_par, q5_par, q6_par, q7_par;
   wire       q_room = (q_cnt != Q_DEPTH);
   wire [2:0] q_tail = q_wr - 3'd1;
   initial begin
       q_wr = 3'd0; q_rd = 3'd0; q_cnt = 4'd0; q_done = 8'd0; q_hold = 2'd0; q_seq = 4'd0;
       q0_len = 6'd0; q0_csum = 8'd0; q0_stat = ST_NONE; q0_seq = 4'd0; q0_par = 1'b0;
       q1_len = 6'd0; q1_csum = 8'd0; q1_stat = ST_NONE; q1_seq = 4'd0; q1_par = 1'b0;
       q2_len = 6'd0; q2_csum = 8'd0; q2_stat = ST_NONE; q2_seq = 4'd0; q2_par = 1'b0;
       q3_len = 6'd0; q3_csum = 8'd0; q3_stat = ST_NONE; q3_seq = 4'd0; q3_par = 1'b0;
       q4_len = 6'd0; q4_csum = 8'd0; q4_stat = ST_NONE; q4_seq = 4'd0; q4_par = 1'b0;
       q5_len = 6'd0; q5_csum = 8'd0; q5_stat = ST_NONE; q5_seq = 4'd0; q5_par = 1'b0;
       q6_len = 6'd0; q6_csum = 8'd0; q6_stat = ST_NONE; q6_seq = 4'd0; q6_par = 1'b0;
       q7_len = 6'd0; q7_csum = 8'd0; q7_stat = ST_NONE; q7_seq = 4'd0; q7_par = 1'b0;
       o_desc_valid = 1'b0; o_desc_len = 6'd0; o_desc_csum = 8'd0; o_desc_stat = ST_NONE;
       o_desc_seq = 4'd0; o_desc_perr = 1'b0; o_sof_refused = 8'd0;
   end

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
   wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN) && q_room;
   wire sof_refused = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN) && !q_room;
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;

   // frame length guard: a frame that overruns the payload limit is closed
   // early with a K30.7 abort symbol in place of the next offered symbol
   wire       frm_open, frm_abort;
   wire       do_abort = i_ce && frm_abort;

   fm_frame_guard u_guard (
       .clk        (clk),
       .rst        (rst),
       .i_open     (do_sof && !do_abort),
       .i_close    (do_abort || do_eof),
       .i_byte     (do_data && !do_abort),
       .i_data     (i_data),
       .o_open     (frm_open),
       .o_abort    (frm_abort),
       .o_len      (o_frm_len),
       .o_csum     (o_frm_csum),
       .o_last_csum(o_last_csum),
       .o_last_len (o_last_len),
       .o_max_len  (o_max_len),
       .o_runt_cnt (o_runt_cnt),
       .o_abort_cnt(o_abort_cnt),
       .o_good_cnt (o_good_cnt),
       .o_status   (o_frm_status)
   );

   assign o_frm_open  = frm_open;
   assign o_frm_abort = frm_abort;
  // descriptor queue: reserve on SOF, complete on close, drain on idle
  wire        q_rsv      = do_sof && !do_abort;
  wire        q_fill     = (do_abort || do_eof) && frm_open;
  wire        q_pop      = !i_ce && (q_cnt != 4'd0) && q_done[q_rd] && (q_hold == 2'd0);
  wire [7:0]  q_rsv_sel  = q_rsv  ? (8'd1 << q_wr)   : 8'd0;
  wire [7:0]  q_fill_sel = q_fill ? (8'd1 << q_tail) : 8'd0;
  wire [7:0]  q_pop_sel  = q_pop  ? (8'd1 << q_rd)   : 8'd0;
  wire [1:0]  fill_stat  = frm_abort ? ST_ABORT : ((o_frm_len < RUNT_LEN) ? ST_RUNT : ST_GOOD);
  wire        fill_par   = ^{fill_stat, o_frm_len, o_frm_csum};
  // packed slot words {parity, seq, status, length, checksum}
  wire [20:0] q0_word = {q0_par, q0_seq, q0_stat, q0_len, q0_csum};
  wire [20:0] q1_word = {q1_par, q1_seq, q1_stat, q1_len, q1_csum};
  wire [20:0] q2_word = {q2_par, q2_seq, q2_stat, q2_len, q2_csum};
  wire [20:0] q3_word = {q3_par, q3_seq, q3_stat, q3_len, q3_csum};
  wire [20:0] q4_word = {q4_par, q4_seq, q4_stat, q4_len, q4_csum};
  wire [20:0] q5_word = {q5_par, q5_seq, q5_stat, q5_len, q5_csum};
  wire [20:0] q6_word = {q6_par, q6_seq, q6_stat, q6_len, q6_csum};
  wire [20:0] q7_word = {q7_par, q7_seq, q7_stat, q7_len, q7_csum};
  function [20:0] q_pick;
      input [2:0]  s;
      input [20:0] w0, w1, w2, w3, w4, w5, w6, w7;
      begin
          case (s)
              3'd0: q_pick = w0;
              3'd1: q_pick = w1;
              3'd2: q_pick = w2;
              3'd3: q_pick = w3;
              3'd4: q_pick = w4;
              3'd5: q_pick = w5;
              3'd6: q_pick = w6;
              default: q_pick = w7;
          endcase
      end
  endfunction
  wire [20:0] rd_word = q_pick(q_rd, q0_word, q1_word, q2_word, q3_word, q4_word, q5_word, q6_word, q7_word);
  wire [7:0]  rd_csum = rd_word[7:0];
  wire [5:0]  rd_len  = rd_word[13:8];
  wire [1:0]  rd_stat = rd_word[15:14];
  wire [3:0]  rd_seq  = rd_word[19:16];
  wire        rd_perr = ^rd_word;
  assign o_q_level = q_cnt;
  assign o_q_full  = !q_room;
  // queue pointers, occupancy and completion flags
  always @(posedge clk) begin
      if (rst) begin
          q_wr   <= 3'd0;
          q_rd   <= 3'd0;
          q_cnt  <= 4'd0;
          q_done <= 8'd0;
          q_seq  <= 4'd0;
      end else begin
          q_done <= (q_done & ~(q_rsv_sel | q_pop_sel)) | q_fill_sel;
          if (q_rsv) begin
              q_wr  <= q_wr + 3'd1;
              q_seq <= q_seq + 4'd1;
          end
          if (q_pop)
              q_rd <= q_rd + 3'd1;
          if (q_rsv && !q_pop)
              q_cnt <= q_cnt + 4'd1;
          else if (q_pop && !q_rsv)
              q_cnt <= q_cnt - 4'd1;
      end
  end
  // host port pacing: after a hand-off the port is busy for DRAIN_GAP cycles
  always @(posedge clk) begin
      if (rst)
          q_hold <= 2'd0;
      else if (q_pop)
          q_hold <= DRAIN_GAP;
      else if (q_hold != 2'd0)
          q_hold <= q_hold - 2'd1;
  end
  always @(posedge clk) begin
      if (rst) begin
          q0_len  <= 6'd0;
          q0_csum <= 8'd0;
          q0_stat <= ST_NONE;
          q0_seq  <= 4'd0;
          q0_par  <= 1'b0;
      end else if (q_rsv_sel[0]) begin
          q0_len  <= 6'd0;
          q0_csum <= 8'd0;
          q0_stat <= ST_NONE;
          q0_seq  <= q_seq;
          q0_par  <= ^q_seq;
      end else if (q_fill_sel[0]) begin
          q0_len  <= o_frm_len;
          q0_csum <= o_frm_csum;
          q0_stat <= fill_stat;
          q0_par  <= fill_par ^ (^q0_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q1_len  <= 6'd0;
          q1_csum <= 8'd0;
          q1_stat <= ST_NONE;
          q1_seq  <= 4'd0;
          q1_par  <= 1'b0;
      end else if (q_rsv_sel[1]) begin
          q1_len  <= 6'd0;
          q1_csum <= 8'd0;
          q1_stat <= ST_NONE;
          q1_seq  <= q_seq;
          q1_par  <= ^q_seq;
      end else if (q_fill_sel[1]) begin
          q1_len  <= o_frm_len;
          q1_csum <= o_frm_csum;
          q1_stat <= fill_stat;
          q1_par  <= fill_par ^ (^q1_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q2_len  <= 6'd0;
          q2_csum <= 8'd0;
          q2_stat <= ST_NONE;
          q2_seq  <= 4'd0;
          q2_par  <= 1'b0;
      end else if (q_rsv_sel[2]) begin
          q2_len  <= 6'd0;
          q2_csum <= 8'd0;
          q2_stat <= ST_NONE;
          q2_seq  <= q_seq;
          q2_par  <= ^q_seq;
      end else if (q_fill_sel[2]) begin
          q2_len  <= o_frm_len;
          q2_csum <= o_frm_csum;
          q2_stat <= fill_stat;
          q2_par  <= fill_par ^ (^q2_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q3_len  <= 6'd0;
          q3_csum <= 8'd0;
          q3_stat <= ST_NONE;
          q3_seq  <= 4'd0;
          q3_par  <= 1'b0;
      end else if (q_rsv_sel[3]) begin
          q3_len  <= 6'd0;
          q3_csum <= 8'd0;
          q3_stat <= ST_NONE;
          q3_seq  <= q_seq;
          q3_par  <= ^q_seq;
      end else if (q_fill_sel[3]) begin
          q3_len  <= o_frm_len;
          q3_csum <= o_frm_csum;
          q3_stat <= fill_stat;
          q3_par  <= fill_par ^ (^q3_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q4_len  <= 6'd0;
          q4_csum <= 8'd0;
          q4_stat <= ST_NONE;
          q4_seq  <= 4'd0;
          q4_par  <= 1'b0;
      end else if (q_rsv_sel[4]) begin
          q4_len  <= 6'd0;
          q4_csum <= 8'd0;
          q4_stat <= ST_NONE;
          q4_seq  <= q_seq;
          q4_par  <= ^q_seq;
      end else if (q_fill_sel[4]) begin
          q4_len  <= o_frm_len;
          q4_csum <= o_frm_csum;
          q4_stat <= fill_stat;
          q4_par  <= fill_par ^ (^q4_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q5_len  <= 6'd0;
          q5_csum <= 8'd0;
          q5_stat <= ST_NONE;
          q5_seq  <= 4'd0;
          q5_par  <= 1'b0;
      end else if (q_rsv_sel[5]) begin
          q5_len  <= 6'd0;
          q5_csum <= 8'd0;
          q5_stat <= ST_NONE;
          q5_seq  <= q_seq;
          q5_par  <= ^q_seq;
      end else if (q_fill_sel[5]) begin
          q5_len  <= o_frm_len;
          q5_csum <= o_frm_csum;
          q5_stat <= fill_stat;
          q5_par  <= fill_par ^ (^q5_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q6_len  <= 6'd0;
          q6_csum <= 8'd0;
          q6_stat <= ST_NONE;
          q6_seq  <= 4'd0;
          q6_par  <= 1'b0;
      end else if (q_rsv_sel[6]) begin
          q6_len  <= 6'd0;
          q6_csum <= 8'd0;
          q6_stat <= ST_NONE;
          q6_seq  <= q_seq;
          q6_par  <= ^q_seq;
      end else if (q_fill_sel[6]) begin
          q6_len  <= o_frm_len;
          q6_csum <= o_frm_csum;
          q6_stat <= fill_stat;
          q6_par  <= fill_par ^ (^q6_seq);
      end
  end
  always @(posedge clk) begin
      if (rst) begin
          q7_len  <= 6'd0;
          q7_csum <= 8'd0;
          q7_stat <= ST_NONE;
          q7_seq  <= 4'd0;
          q7_par  <= 1'b0;
      end else if (q_rsv_sel[7]) begin
          q7_len  <= 6'd0;
          q7_csum <= 8'd0;
          q7_stat <= ST_NONE;
          q7_seq  <= q_seq;
          q7_par  <= ^q_seq;
      end else if (q_fill_sel[7]) begin
          q7_len  <= o_frm_len;
          q7_csum <= o_frm_csum;
          q7_stat <= fill_stat;
          q7_par  <= fill_par ^ (^q7_seq);
      end
  end
  // descriptor hand-off to the host, with storage parity check
  always @(posedge clk) begin
      if (rst) begin
          o_desc_valid <= 1'b0;
          o_desc_len   <= 6'd0;
          o_desc_csum  <= 8'd0;
          o_desc_stat  <= ST_NONE;
          o_desc_seq   <= 4'd0;
          o_desc_perr  <= 1'b0;
      end else begin
          o_desc_valid <= q_pop;
          if (q_pop) begin
              o_desc_len  <= rd_len;
              o_desc_csum <= rd_csum;
              o_desc_stat <= rd_stat;
              o_desc_seq  <= rd_seq;
              o_desc_perr <= rd_perr;
          end
      end
  end
  // start-of-frame requests turned away because no descriptor slot was free
  always @(posedge clk) begin
      if (rst)
          o_sof_refused <= 8'd0;
      else if (sof_refused && (o_sof_refused != 8'hFF))
          o_sof_refused <= o_sof_refused + 8'd1;
  end

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
       end else if (do_abort) begin
           o_sym      <= o_rd ? 10'b1000010111 : 10'b0111101000;
           seen_end   <= 1'b1;
           phase      <= PH_ALIGN;
           o_sym_cnt  <= o_sym_cnt + 32'd1;
       end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
   always @(*) assert ((phase != PH_PKT) || (q_cnt != 4'd0));
endmodule

module fm_pkt_guard #(
   parameter [5:0] MAX_LEN = 6'd48,
   parameter [5:0] MIN_LEN = 6'd4,
   parameter [1:0] IFG     = 2'd3
) (
   input  wire        clk,
   input  wire        rst,
   input  wire        i_sym,
   input  wire        i_in_pkt,
   input  wire        i_sof,
   input  wire        i_eof,
   input  wire        i_trunc,
   input  wire        i_beat,
   input  wire        i_comma,
   input  wire [7:0]  i_data,
   output wire [5:0]  o_len,
   output wire [1:0]  o_holdoff,
   output wire        o_trunc_req,
   output wire        o_sof_ok,
   output reg  [7:0]  o_trunc_cnt,
   output reg  [7:0]  o_drop_cnt,
   output reg  [7:0]  o_runt_cnt,
   output reg  [7:0]  o_kin_cnt,
   output reg  [31:0] o_byte_cnt,
   output reg  [7:0]  o_pkt_sum,
   output reg         o_last_trunc,
   output reg         o_last_runt
);
   reg [5:0] len;
   reg [1:0] holdoff;
   reg [7:0] run_sum;

   initial begin
       len = 6'd0; holdoff = 2'd0; run_sum = 8'd0;
       o_trunc_cnt = 8'd0; o_drop_cnt = 8'd0; o_runt_cnt = 8'd0; o_kin_cnt = 8'd0;
       o_byte_cnt = 32'd0; o_pkt_sum = 8'd0;
       o_last_trunc = 1'b0; o_last_runt = 1'b0;
   end

   // a packet is closed either by a real EOF or by the length limit
   wire at_limit  = (len == MAX_LEN);
   wire close_pkt = i_eof || i_trunc;
   wire take_beat = i_beat && i_in_pkt && !at_limit;
   wire runt      = i_eof && (len < MIN_LEN);
   wire dropped   = i_trunc && i_beat;
   wire in_band_k = i_comma && i_in_pkt;

   assign o_len       = len;
   assign o_holdoff   = holdoff;
   assign o_trunc_req = at_limit;
   assign o_sof_ok    = (holdoff == 2'd0);

   // payload length of the open packet
   always @(posedge clk) begin
       if (rst) begin
           len <= 6'd0;
       end else if (i_sof || close_pkt) begin
           len <= 6'd0;
       end else if (take_beat) begin
           len <= len + 6'd1;
       end
   end

   // minimum inter-frame gap after each packet
   always @(posedge clk) begin
       if (rst) begin
           holdoff <= 2'd0;
       end else if (close_pkt) begin
           holdoff <= IFG;
       end else if (i_sym && (holdoff != 2'd0)) begin
           holdoff <= holdoff - 2'd1;
       end
   end

   // running payload sum, published when the packet closes
   always @(posedge clk) begin
       if (rst) begin
           run_sum   <= 8'd0;
           o_pkt_sum <= 8'd0;
       end else if (i_sof) begin
           run_sum   <= 8'd0;
       end else if (close_pkt) begin
           o_pkt_sum <= run_sum;
           run_sum   <= 8'd0;
       end else if (take_beat) begin
           run_sum   <= run_sum + i_data;
       end
   end

   // saturating event counters
   always @(posedge clk) begin
       if (rst) begin
           o_trunc_cnt <= 8'd0;
           o_drop_cnt  <= 8'd0;
           o_runt_cnt  <= 8'd0;
           o_kin_cnt   <= 8'd0;
       end else begin
           if (i_trunc && (o_trunc_cnt != 8'hFF))
               o_trunc_cnt <= o_trunc_cnt + 8'd1;
           if (dropped && (o_drop_cnt != 8'hFF))
               o_drop_cnt <= o_drop_cnt + 8'd1;
           if (runt && (o_runt_cnt != 8'hFF))
               o_runt_cnt <= o_runt_cnt + 8'd1;
           if (in_band_k && (o_kin_cnt != 8'hFF))
               o_kin_cnt <= o_kin_cnt + 8'd1;
       end
   end

   // payload byte counter and per-packet close status
   always @(posedge clk) begin
       if (rst) begin
           o_byte_cnt   <= 32'd0;
           o_last_trunc <= 1'b0;
           o_last_runt  <= 1'b0;
       end else begin
           if (take_beat)
               o_byte_cnt <= o_byte_cnt + 32'd1;
           if (close_pkt) begin
               o_last_trunc <= i_trunc;
               o_last_runt  <= runt;
           end
       end
   end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
   output reg  [31:0] o_pkt_cnt,
   output wire [5:0]  o_pg_len,
   output wire [1:0]  o_pg_holdoff,
   output wire [7:0]  o_trunc_cnt,
   output wire [7:0]  o_drop_cnt,
   output wire [7:0]  o_runt_cnt,
   output wire [7:0]  o_kin_cnt,
   output wire [31:0] o_byte_cnt,
   output wire [7:0]  o_pkt_sum,
   output wire [3:0]  o_pg_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

   // packet guard status
   wire [5:0] pg_len;
   wire [1:0] pg_holdoff;
   wire       pg_trunc_req;
   wire       pg_sof_ok;
   wire       pg_last_trunc;
   wire       pg_last_runt;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
   wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN) && pg_sof_ok;
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
   // oversize packet: close it with an EOF in place of the next symbol
   wire do_trunc   = i_ce && pg_trunc_req;
   wire trunc_take = do_trunc && !do_comma && !do_sof && !do_eof;

   fm_pkt_guard #(
       .MAX_LEN(6'd48),
       .MIN_LEN(6'd4),
       .IFG(2'd3)
   ) u_guard (
       .clk(clk),
       .rst(rst),
       .i_sym(i_ce),
       .i_in_pkt(phase == PH_PKT),
       .i_sof(do_sof),
       .i_eof(do_eof),
       .i_trunc(trunc_take),
       .i_beat(do_data),
       .i_comma(do_comma),
       .i_data(i_data),
       .o_len(pg_len),
       .o_holdoff(pg_holdoff),
       .o_trunc_req(pg_trunc_req),
       .o_sof_ok(pg_sof_ok),
       .o_trunc_cnt(o_trunc_cnt),
       .o_drop_cnt(o_drop_cnt),
       .o_runt_cnt(o_runt_cnt),
       .o_kin_cnt(o_kin_cnt),
       .o_byte_cnt(o_byte_cnt),
       .o_pkt_sum(o_pkt_sum),
       .o_last_trunc(pg_last_trunc),
       .o_last_runt(pg_last_runt)
   );

   assign o_pg_len     = pg_len;
   assign o_pg_holdoff = pg_holdoff;
   assign o_pg_status  = {pg_last_trunc, pg_last_runt, pg_trunc_req, pg_sof_ok};

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
       end else if (do_trunc) begin
           o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
           seen_end   <= 1'b1;
           phase      <= PH_ALIGN;
           o_pkt_cnt  <= o_pkt_cnt + 32'd1;
           o_sym_cnt  <= o_sym_cnt + 32'd1;
       end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire [7:0] o_scan_pix,
   output wire o_scan_valid,
   output wire o_scan_eol,
   output wire o_scan_eof,
   output wire [7:0] o_scan_pos,
   output wire [3:0] o_pixq_level,
   output wire [3:0] o_pixq_peak,
   output wire [7:0] o_underrun,
   output wire [63:0] o_scan_frames
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

   localparam [4:0] SCAN_CFG_ADDR = 5'd24;
   localparam [3:0] PIXQ_DEPTH = 4'd8;

   reg [7:0]  pixq_data [0:7];
   reg [7:0]  pixq_eof;
   reg [2:0]  pixq_wr_ptr;
   reg [2:0]  pixq_rd_ptr;
   reg [3:0]  pixq_count;
   reg [3:0]  pixq_peak;
   reg [3:0]  scan_div;
   reg [3:0]  scan_tmr;
   reg [4:0]  scan_col;
   reg [2:0]  scan_row;
   reg [7:0]  scan_pix;
   reg        scan_valid;
   reg        scan_eol;
   reg        scan_eof;
   reg [7:0]  underrun_cnt;
   reg [63:0] scan_frames;
   integer k;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;
   initial begin
       for (i = 0; i < 8; i = i + 1)
           pixq_data[i] = 8'h00;
   end
   initial pixq_eof = 8'h00;
   initial pixq_wr_ptr = 3'd0;
   initial pixq_rd_ptr = 3'd0;
   initial pixq_count = 4'd0;
   initial pixq_peak = 4'd0;
   initial scan_div = 4'd1;
   initial scan_tmr = 4'd0;
   initial scan_col = 5'd0;
   initial scan_row = 3'd0;
   initial scan_pix = 8'h00;
   initial scan_valid = 1'b0;
   initial scan_eol = 1'b0;
   initial scan_eof = 1'b0;
   initial underrun_cnt = 8'd0;
   initial scan_frames = 64'd0;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire last_px = last_col && last_row;
   wire [7:0] gen_pix = font_row(cur_char, row_cnt[2:0]);
   wire pixq_full = (pixq_count >= PIXQ_DEPTH);
   wire pixq_empty = (pixq_count == 4'd0);
   wire gen_push = (phase == RUN) && !pixq_full;
   wire scan_tick = (scan_tmr == 4'd0);
   wire scan_pop = scan_tick && !pixq_empty;
   wire head_eof = pixq_eof[pixq_rd_ptr];
   wire [7:0] head_pix = pixq_data[pixq_rd_ptr];
   wire scan_line_end = (scan_col >= 5'd23);
   wire scan_starved = scan_tick && pixq_empty && (phase == RUN);

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
           for (k = 0; k < 8; k = k + 1)
               pixq_data[k] <= 8'h00;
           pixq_eof <= 8'h00;
           pixq_wr_ptr <= 3'd0;
           pixq_rd_ptr <= 3'd0;
           pixq_count <= 4'd0;
           pixq_peak <= 4'd0;
           scan_div <= 4'd1;
           scan_tmr <= 4'd0;
           scan_col <= 5'd0;
           scan_row <= 3'd0;
           scan_pix <= 8'h00;
           scan_valid <= 1'b0;
           scan_eol <= 1'b0;
           scan_eof <= 1'b0;
           underrun_cnt <= 8'd0;
           scan_frames <= 64'd0;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
           if (wr_en && (wr_addr == SCAN_CFG_ADDR))
               scan_div <= wr_data[3:0];
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
               pixq_eof <= 8'h00;
               pixq_wr_ptr <= 3'd0;
               pixq_rd_ptr <= 3'd0;
               pixq_count <= 4'd0;
               scan_tmr <= scan_div;
               scan_col <= 5'd0;
               scan_row <= 3'd0;
               scan_valid <= 1'b0;
               scan_eol <= 1'b0;
               scan_eof <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                       if (gen_push) begin
                           pix_row <= gen_pix;
                           pixq_data[pixq_wr_ptr] <= gen_pix;
                           pixq_eof[pixq_wr_ptr] <= last_px;
                           pixq_wr_ptr <= pixq_wr_ptr + 3'd1;
                           if (last_col) begin
                               col_cnt <= 64'd0;
                               if (last_row) begin
                                   row_cnt <= 64'd0;
                                   phase <= FIN;
                                   frame_cnt <= frame_cnt + 64'd1;
                               end else begin
                                   row_cnt <= row_cnt + 64'd1;
                               end
                           end else begin
                               col_cnt <= col_cnt + 64'd1;
                           end
                       end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
               if (scan_pop) begin
                   scan_pix <= head_pix;
                   scan_eof <= head_eof;
                   scan_eol <= scan_line_end || head_eof;
                   pixq_rd_ptr <= pixq_rd_ptr + 3'd1;
                   if (head_eof) begin
                       scan_col <= 5'd0;
                       scan_row <= 3'd0;
                       scan_frames <= scan_frames + 64'd1;
                       done <= 1'b1;
                   end else if (scan_line_end) begin
                       scan_col <= 5'd0;
                       scan_row <= scan_row + 3'd1;
                   end else begin
                       scan_col <= scan_col + 5'd1;
                   end
               end
               scan_valid <= scan_pop;
               if (gen_push && !scan_pop)
                   pixq_count <= pixq_count + 4'd1;
               else if (scan_pop && !gen_push)
                   pixq_count <= pixq_count - 4'd1;
               if (pixq_count > pixq_peak)
                   pixq_peak <= pixq_count;
               if (scan_tick)
                   scan_tmr <= scan_div;
               else
                   scan_tmr <= scan_tmr - 4'd1;
               if (scan_starved && (underrun_cnt != 8'hFF))
                   underrun_cnt <= underrun_cnt + 8'd1;
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_scan_pix = scan_pix;
   assign o_scan_valid = scan_valid;
   assign o_scan_eol = scan_eol;
   assign o_scan_eof = scan_eof;
   assign o_scan_pos = {scan_row, scan_col};
   assign o_pixq_level = pixq_count;
   assign o_pixq_peak = pixq_peak;
   assign o_underrun = underrun_cnt;
   assign o_scan_frames = scan_frames;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module fm_link_lock_ctl (
   input  wire       clk,
   input  wire       rst,
   input  wire       i_comma,
   input  wire       i_sof_req,
   input  wire       i_eof,
   input  wire       i_dsym,
   input  wire       i_in_pkt,
   input  wire [7:0] i_byte,
   output reg        o_sof_ok,
   output reg        o_locked,
   output reg  [1:0] o_comma_run,
   output reg  [3:0] o_idle_run,
   output reg  [7:0] o_pkt_len,
   output reg        o_len_err,
   output reg  [7:0] o_pkt_sum,
   output reg  [7:0] o_last_sum,
   output reg  [7:0] o_sof_rej,
   output reg  [7:0] o_lock_loss,
   output wire [3:0] o_status
);
   localparam [1:0] RUN_MAX  = 2'd3;
   localparam [3:0] IDLE_MAX = 4'd15;
   localparam [7:0] LEN_MAX  = 8'd192;
   localparam [7:0] CNT_MAX  = 8'hff;
   // lock is held once four back-to-back commas have been observed
   wire lock_next = o_locked || (o_comma_run == RUN_MAX);
   // start-of-frame admission: a request is only honoured while armed
   wire sof_take  = i_sof_req && o_sof_ok;
   wire sof_drop  = i_sof_req && !o_sof_ok;
   // data symbols seen outside a packet are treated as line noise
   wire idle_dat  = i_dsym && !i_in_pkt;
   wire pkt_dat   = i_dsym && i_in_pkt;
   wire idle_trip = idle_dat && (o_idle_run == IDLE_MAX);
   wire len_hit   = pkt_dat && (o_pkt_len == LEN_MAX);
   assign o_status = {o_len_err, (o_sof_rej != 8'd0), o_sof_ok, o_locked};
   initial begin
       o_sof_ok = 1'b0; o_locked = 1'b0; o_comma_run = 2'd0; o_idle_run = 4'd0;
       o_pkt_len = 8'd0; o_len_err = 1'b0; o_pkt_sum = 8'd0; o_last_sum = 8'd0;
       o_sof_rej = 8'd0; o_lock_loss = 8'd0;
   end
   // alignment tracking: acquire on a comma run, drop on a noise run
   always @(posedge clk) begin
       if (rst) begin
           o_locked    <= 1'b0;
           o_comma_run <= 2'd0;
           o_idle_run  <= 4'd0;
           o_lock_loss <= 8'd0;
       end else if (i_comma) begin
           o_locked    <= lock_next;
           o_idle_run  <= 4'd0;
           if (o_comma_run != RUN_MAX) o_comma_run <= o_comma_run + 2'd1;
       end else if (idle_trip) begin
           o_locked    <= 1'b0;
           o_comma_run <= 2'd0;
           o_idle_run  <= 4'd0;
           if (o_locked && (o_lock_loss != CNT_MAX)) o_lock_loss <= o_lock_loss + 8'd1;
       end else if (idle_dat) begin
           o_idle_run  <= o_idle_run + 4'd1;
           if (!o_locked) o_comma_run <= 2'd0;
       end
   end
   // start-of-frame arm flag and refused-request counter
   always @(posedge clk) begin
       if (rst) begin
           o_sof_ok  <= 1'b0;
           o_sof_rej <= 8'd0;
       end else if (i_comma) begin
           o_sof_ok  <= !i_in_pkt && lock_next;
       end else if (sof_take) begin
           o_sof_ok  <= 1'b0;
       end else if (sof_drop) begin
           if (o_sof_rej != CNT_MAX) o_sof_rej <= o_sof_rej + 8'd1;
       end else if (i_eof) begin
           o_sof_ok  <= o_locked;
       end else if (idle_trip) begin
           o_sof_ok  <= 1'b0;
       end
   end
   // in-packet length limit and running checksum
   always @(posedge clk) begin
       if (rst) begin
           o_pkt_len  <= 8'd0;
           o_len_err  <= 1'b0;
           o_pkt_sum  <= 8'd0;
           o_last_sum <= 8'd0;
       end else if (sof_take) begin
           o_pkt_len  <= 8'd0;
           o_len_err  <= 1'b0;
           o_pkt_sum  <= 8'd0;
       end else if (pkt_dat) begin
           if (o_pkt_len != CNT_MAX) o_pkt_len <= o_pkt_len + 8'd1;
           if (len_hit) o_len_err <= 1'b1;
           o_pkt_sum  <= o_pkt_sum + i_byte;
       end else if (i_eof) begin
           o_last_sum <= o_pkt_sum;
       end
   end
endmodule
module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
   output reg  [31:0] o_pkt_cnt,
   output wire        o_sof_ok,
   output wire        o_locked,
   output wire [1:0]  o_comma_run,
   output wire [3:0]  o_idle_run,
   output wire [7:0]  o_pkt_len,
   output wire        o_len_err,
   output wire [7:0]  o_pkt_sum,
   output wire [7:0]  o_last_sum,
   output wire [7:0]  o_sof_rej,
   output wire [7:0]  o_lock_loss,
   output wire [3:0]  o_link_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
   wire sof_req  = i_ce && i_k && (i_kcode == K_SOF);
   wire do_sof   = sof_req && o_sof_ok;
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
   // link alignment and frame admission controller
   fm_link_lock_ctl u_lock (
       .clk         (clk),
       .rst         (rst),
       .i_comma     (do_comma),
       .i_sof_req   (sof_req),
       .i_eof       (do_eof),
       .i_dsym      (do_data),
       .i_in_pkt    (phase == PH_PKT),
       .i_byte      (i_data),
       .o_sof_ok    (o_sof_ok),
       .o_locked    (o_locked),
       .o_comma_run (o_comma_run),
       .o_idle_run  (o_idle_run),
       .o_pkt_len   (o_pkt_len),
       .o_len_err   (o_len_err),
       .o_pkt_sum   (o_pkt_sum),
       .o_last_sum  (o_last_sum),
       .o_sof_rej   (o_sof_rej),
       .o_lock_loss (o_lock_loss),
       .o_status    (o_link_status)
   );

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
   output wire [31:0] o_x3,
   output wire [2:0]  o_jq_cnt,
   output wire [2:0]  o_jq_hwm,
   output wire        o_jq_full,
   output wire        o_jq_ovf,
   output wire [7:0]  o_jq_drop,
   output wire        o_jq_hmode,
   output wire [31:0] o_jq_hseed,
   output wire        o_jq_tmode,
